function pqrsClearRespOficioError(){
  const el=document.getElementById('pqrs-resp-oficio-err');
  const inp=document.getElementById('pqrs-resp-oficio');
  if(el){el.style.display='none';el.textContent='';}
  if(inp)inp.classList.remove('fld-invalid');
}
function pqrsClearRespComposeAttError(){
  const el=document.getElementById('pqrs-compose-att-err');
  if(el){el.style.display='none';el.textContent='';}
}
function pqrsClearRespAdjError(){
  const el=document.getElementById('pqrs-resp-adj-err');
  if(el){el.style.display='none';el.textContent='';}
}
function pqrsShowRespOficioError(msg){
  const el=document.getElementById('pqrs-resp-oficio-err');
  const inp=document.getElementById('pqrs-resp-oficio');
  if(inp)inp.classList.add('fld-invalid');
  if(el){el.style.display='';el.textContent=msg||'Indique el N° de oficio.';}
  if(inp)inp.focus();
}
function pqrsShowRespComposeAttError(msg){
  const el=document.getElementById('pqrs-compose-att-err');
  if(el){el.style.display='';el.textContent=msg||'Adjunte el oficio firmado.';}
}
function pqrsShowRespAdjError(msg){
  const el=document.getElementById('pqrs-resp-adj-err');
  if(el){el.style.display='';el.textContent=msg||'Adjunte los documentos requeridos.';}
}
function pqrsCountAdjuntosRespuesta(){
  const adj=collectPqrsRespAdjuntos();
  const compose=(window._pqrsComposeAttachments||[]).length;
  return(adj.files?adj.files.length:0)+(adj.links?adj.links.length:0)+compose;
}
function pqrsValidateOficioRespuesta(tipoResp,opts){
  opts=opts||{};
  pqrsClearRespOficioError();
  pqrsClearRespComposeAttError();
  pqrsClearRespAdjError();
  if(tipoResp!==PQRS_WF_TIPO.OFICIO)return true;
  const oficio=String((document.getElementById('pqrs-resp-oficio')||{}).value||'').trim();
  if(!oficio){pqrsShowRespOficioError('Favor diligenciar el N° de oficio.');return false;}
  if(opts.requireComposeAtt){
    const files=window._pqrsComposeAttachments||[];
    if(!files.length){pqrsShowRespComposeAttError('Para oficio firmado debe adjuntar el documento del oficio.');return false;}
  }
  if(opts.requireAdj){
    if(pqrsCountAdjuntosRespuesta()<1){
      pqrsShowRespAdjError(opts.adjMsg||'Para oficio firmado debe adjuntar el documento del oficio.');
      return false;
    }
  }
  // Duplicado: bloquear y mostrar modal
  if(!opts.skipDupCheck){
    const expId=String((document.getElementById('gmail-resp-pqrs-hid')||{}).value||(window._taskModalCtx||{}).expId||'').trim();
    if(!validarNumeroOficioDisponible(oficio,expId))return false;
  }
  return true;
}
/** Normaliza N° de oficio para comparación (sin espacios, mayúsculas). */
function pqrsNormOficioNum(s){
  return String(s||'').trim().toUpperCase().replace(/\s+/g,'');
}
/**
 * Busca usos previos del N° de oficio en PQRSD/trámites/actos/actividades.
 * @returns {Array<{expId:string,contexto:string,detalle:string}>}
 */
function buscarUsosNumeroOficio(oficio,excludeExpId){
  const needle=pqrsNormOficioNum(oficio);
  if(!needle||needle.length<3)return[];
  const excl=pqrsNormOficioNum(excludeExpId);
  const hits=[];
  const lista=(typeof exps!=='undefined'&&Array.isArray(exps))?exps:[];
  lista.forEach(function(e){
    if(!e)return;
    const id=String(e._exp||'').trim();
    if(excl&&pqrsNormOficioNum(id)===excl)return;
    const esPqrs=typeof esPqrsSecretaria==='function'?esPqrsSecretaria(e):(!!e._es_pqrs||String(e._tipo_solicitud||'').toUpperCase().indexOf('PQR')>=0);
    const tipoLbl=esPqrs?'PQRSD':(e._tramite||'Trámite');
    const asunto=String(e.f_f1||e._pqrs_detalle||e._asunto||'').trim().slice(0,80);
    // Respuesta PQRSD
    const wf=typeof getPqrsWorkflow==='function'?getPqrsWorkflow(e):{};
    const ofiResp=pqrsNormOficioNum(wf.oficio||e._pqrs_respuesta_oficio||'');
    if(ofiResp&&ofiResp===needle){
      hits.push({
        expId:id,
        contexto:tipoLbl+' · respuesta',
        detalle:(asunto?asunto+' · ':'')+'Oficio de respuesta '+String(wf.oficio||e._pqrs_respuesta_oficio||'')
      });
    }
    // Actos administrativos
    let actos=[];
    try{
      actos=typeof e._actos_admin==='string'?JSON.parse(e._actos_admin||'[]'):(e._actos_admin||[]);
    }catch(x){actos=[];}
    if(Array.isArray(actos)){
      actos.forEach(function(a,i){
        if(!a)return;
        const num=pqrsNormOficioNum(a.numero||a.oficio||'');
        if(num&&num===needle){
          hits.push({
            expId:id,
            contexto:tipoLbl+' · acto administrativo',
            detalle:(a.tipo||'Acto')+(a.numero?' · '+a.numero:'')+(asunto?' · '+asunto:'')
          });
        }
      });
    }
    // Actividades / tareas (campo oficio o descripción con el número exacto en metadatos)
    const tasks=Array.isArray(e.tasks)?e.tasks:[];
    tasks.forEach(function(t){
      if(!t||t.eliminada)return;
      const tofi=pqrsNormOficioNum(t.oficio||t.nro_oficio||t._oficio||'');
      if(tofi&&tofi===needle){
        hits.push({
          expId:id,
          contexto:'Actividad',
          detalle:String(t.desc||t.actividad||t.codigo||t.id||'Actividad').slice(0,80)
        });
      }
    });
  });
  // Actividades libres (sin expediente)
  if(typeof actividadesLibres!=='undefined'&&Array.isArray(actividadesLibres)){
    try{
      actividadesLibres.forEach(function(t){
        if(!t||t.eliminada)return;
        const tofi=pqrsNormOficioNum(t.oficio||t.nro_oficio||t._oficio||'');
        if(tofi&&tofi===needle){
          hits.push({
            expId:String(t.codigo||t.id||'—'),
            contexto:'Actividad libre',
            detalle:String(t.desc||t.actividad||'').slice(0,80)
          });
        }
      });
    }catch(x){}
  }
  return hits;
}
/** Si el N° ya existe, muestra modal de advertencia y retorna false. */
function validarNumeroOficioDisponible(oficio,excludeExpId){
  const usos=buscarUsosNumeroOficio(oficio,excludeExpId);
  if(!usos.length)return true;
  const u=usos[0];
  const mas=usos.length>1?' (+'+(usos.length-1)+' más)':'';
  const detail='Usado en: '+u.expId+' ('+u.contexto+')'+(u.detalle?' — '+u.detalle:'')+mas;
  if(typeof confirmPrecaucion==='function'){
    confirmPrecaucion({
      title:'N° de oficio no válido',
      message:'El número de oficio «'+String(oficio||'').trim()+'» ya fue usado en otra respuesta o registro.',
      detail:detail,
      confirmLabel:'Entendido',
      hideCancel:true,
      tone:'warn'
    },function(){});
  }else if(typeof notif==='function'){
    notif('N° de oficio ya usado: '+detail,'err');
  }
  pqrsShowRespOficioError('Este N° de oficio ya fue usado ('+u.expId+').');
  return false;
}
/** Normaliza N° factura / concepto para unicidad. */
function normContableRefNum(s){
  return String(s||'').trim().toUpperCase().replace(/\s+/g,'');
}
/**
 * Busca usos previos del N° de factura (referencia).
 * @param {string} excludeExpId — expediente a ignorar (al editar el mismo)
 * @param {number|null} excludeIndex — índice de factura a ignorar en ese expediente
 */
function buscarUsosNumeroFactura(ref,excludeExpId,excludeIndex){
  const needle=normContableRefNum(ref);
  if(!needle)return[];
  const excl=String(excludeExpId||'').trim();
  const hits=[];
  const lista=(typeof exps!=='undefined'&&Array.isArray(exps))?exps:[];
  lista.forEach(function(e){
    if(!e)return;
    const id=String(e._exp||'').trim();
    let facs=[];
    try{facs=typeof facturasData==='function'?facturasData(e._facturas_extra):(e._facturas_extra?JSON.parse(e._facturas_extra):[]);}catch(x){facs=[];}
    if(!Array.isArray(facs))return;
    facs.forEach(function(f,i){
      if(!f)return;
      if(excl&&id===excl&&excludeIndex!=null&&Number(excludeIndex)===i)return;
      const r=normContableRefNum(f.ref);
      if(r&&r===needle){
        hits.push({
          expId:id||'—',
          contexto:'Factura',
          detalle:(f.tipo||'Factura')+(f.ref?' · '+String(f.ref):'')
        });
      }
    });
  });
  return hits;
}
function buscarUsosNumeroConcepto(concepto,excludeExpId,excludeIndex){
  const needle=normContableRefNum(concepto);
  if(!needle)return[];
  const excl=String(excludeExpId||'').trim();
  const hits=[];
  const lista=(typeof exps!=='undefined'&&Array.isArray(exps))?exps:[];
  lista.forEach(function(e){
    if(!e)return;
    const id=String(e._exp||'').trim();
    let arr=[];
    try{arr=typeof conceptosSegData==='function'?conceptosSegData(e._conceptos_seg):(e._conceptos_seg?JSON.parse(e._conceptos_seg):[]);}catch(x){arr=[];}
    if(!Array.isArray(arr))return;
    arr.forEach(function(c,i){
      if(!c)return;
      if(excl&&id===excl&&excludeIndex!=null&&Number(excludeIndex)===i)return;
      const n=normContableRefNum(c.concepto);
      if(n&&n===needle){
        hits.push({
          expId:id||'—',
          contexto:'Concepto técnico',
          detalle:'N° '+String(c.concepto||'')+(c.fecha?' · '+c.fecha:'')
        });
      }
    });
  });
  return hits;
}
function _avisoNumeroContableDuplicado(kind,valor,usos){
  if(!usos||!usos.length)return false;
  const u=usos[0];
  const mas=usos.length>1?' (+'+(usos.length-1)+' más)':'';
  const detail='Usado en: '+u.expId+' ('+u.contexto+')'+(u.detalle?' — '+u.detalle:'')+mas;
  const label=kind==='factura'?'N° de factura':'N° de concepto';
  if(typeof confirmPrecaucion==='function'){
    confirmPrecaucion({
      title:label+' no válido',
      message:'El '+label.toLowerCase()+' «'+String(valor||'').trim()+'» ya fue ingresado en otro registro.',
      detail:detail,
      confirmLabel:'Entendido',
      hideCancel:true,
      tone:'warn'
    },function(){});
  }else if(typeof notif==='function'){
    notif(label+' ya usado: '+detail,'err');
  }
  return true;
}
/** false si el N° de factura (ref) ya existe. */
function validarNumeroFacturaDisponible(ref,excludeExpId,excludeIndex){
  if(!normContableRefNum(ref))return true;
  const usos=buscarUsosNumeroFactura(ref,excludeExpId,excludeIndex);
  if(_avisoNumeroContableDuplicado('factura',ref,usos))return false;
  return true;
}
/** false si el N° de concepto ya existe. */
function validarNumeroConceptoDisponible(concepto,excludeExpId,excludeIndex){
  if(!normContableRefNum(concepto))return true;
  const usos=buscarUsosNumeroConcepto(concepto,excludeExpId,excludeIndex);
  if(_avisoNumeroContableDuplicado('concepto',concepto,usos))return false;
  return true;
}
/** Valida adjuntos según canal (oficio + soporte de notificación). */
function pqrsValidateAdjuntosPorCanal(tipoResp,canal,opts){
  opts=opts||{};
  pqrsClearRespAdjError();
  pqrsClearRespComposeAttError();
  const n=pqrsCountAdjuntosRespuesta();
  if(tipoResp===PQRS_WF_TIPO.OFICIO&&pqrsEsCanalCorreo(canal)){
    // En correo el adjunto va en compose
    return true;
  }
  if(tipoResp===PQRS_WF_TIPO.OFICIO&&!pqrsEsCanalCorreo(canal)){
    if(n<1){pqrsShowRespAdjError('Adjunte el oficio firmado.');return false;}
  }
  if(canal===PQRS_WF_CANAL.WHATSAPP){
    // Oficio (si aplica) + soporte de notificación (img/pdf)
    const min=tipoResp===PQRS_WF_TIPO.OFICIO?2:1;
    if(n<min){
      pqrsShowRespAdjError(tipoResp===PQRS_WF_TIPO.OFICIO
        ?'Adjunte el oficio firmado y el soporte de notificación por WhatsApp (imagen o PDF).'
        :'Adjunte el soporte de notificación por WhatsApp.');
      return false;
    }
  }
  if(canal===PQRS_WF_CANAL.AVISO){
    const min=tipoResp===PQRS_WF_TIPO.OFICIO?2:1;
    if(n<min){
      pqrsShowRespAdjError(tipoResp===PQRS_WF_TIPO.OFICIO
        ?'Adjunte el oficio y el soporte de notificación por aviso.'
        :'Adjunte el soporte de notificación por aviso.');
      return false;
    }
  }
  if((canal===PQRS_WF_CANAL.PRESENCIAL||canal===PQRS_WF_CANAL.FISICA)&&tipoResp===PQRS_WF_TIPO.OFICIO){
    if(n<1){pqrsShowRespAdjError('Adjunte el oficio firmado (y constancia de notificación si la tiene).');return false;}
  }
  return true;
}
function pqrsPlantillaMensajeSimple(expId){
  const num=String(expId||'').trim()||'XXXXXXX';
  return 'Cordial saludo,\n\n'+
    'Conforme a su solicitud radicada bajo el número de PQRSD '+num+', nos permitimos informarle lo siguiente:\n\n'+
    '[Indique aquí la respuesta al ciudadano]\n\n'+
    'Quedamos atentos a cualquier inquietud adicional.';
}
function pqrsPlantillaOficioFirmado(expId,oficio){
  const num=String(expId||'').trim()||'XXXXXXX';
  const ofi=String(oficio||'').trim()||'DSGV-E________';
  return 'Cordial saludo,\n\nEn atención a su comunicación identificada con el No. '+num+', esta Dirección Seccional, en ejercicio de sus competencias legales y reglamentarias, se permite dar respuesta de fondo a su solicitud mediante el oficio '+ofi+'.\n\nEl detalle completo de la respuesta, con el análisis correspondiente, se encuentra en el oficio adjunto al presente correo electrónico.\n\nQuedamos atentos a cualquier inquietud adicional.';
}
function _pqrsEsPlantillaRespuesta(txt){
  const cur=String(txt||'').trim();
  if(!cur)return true;
  if(window._pqrsUltimaPlantillaOficio&&cur===window._pqrsUltimaPlantillaOficio)return true;
  if(window._pqrsUltimaPlantillaMensaje&&cur===window._pqrsUltimaPlantillaMensaje)return true;
  // Detectar plantillas aunque el N° de oficio/PQRSD haya cambiado
  if(/^Cordial saludo,/i.test(cur)&&/oficio adjunto al presente correo/i.test(cur))return true;
  if(/^Cordial saludo,/i.test(cur)&&/Conforme a su solicitud radicada bajo el número de PQRSD/i.test(cur))return true;
  if(/^(\s*(fwd?|re):)/i.test(cur))return true;
  return false;
}
function pqrsResetComposeBodyForTipo(tipo){
  // Compat: el switch real lo hace pqrsAplicarPlantillaSegunTipo
  pqrsAplicarPlantillaSegunTipo(tipo,true);
}
function pqrsAplicarPlantillaOficioSiCorresponde(force){
  pqrsAplicarPlantillaSegunTipo(PQRS_WF_TIPO.OFICIO,!!force);
}
function pqrsAplicarPlantillaSegunTipo(tipo,force){
  tipo=String(tipo||(document.getElementById('pqrs-resp-tipo')||{}).value||'');
  const expId=String((document.getElementById('gmail-resp-pqrs-hid')||{}).value||(window._taskModalCtx||{}).expId||'').trim();
  const oficio=String((document.getElementById('pqrs-resp-oficio')||document.getElementById('pqrs-entrega-resp-oficio')||{}).value||'').trim();
  let plantilla='';
  if(tipo===PQRS_WF_TIPO.OFICIO){
    plantilla=pqrsPlantillaOficioFirmado(expId,oficio);
    window._pqrsUltimaPlantillaOficio=plantilla;
    window._pqrsUltimaPlantillaMensaje='';
  }else if(tipo===PQRS_WF_TIPO.MENSAJE){
    plantilla=pqrsPlantillaMensajeSimple(expId);
    window._pqrsUltimaPlantillaMensaje=plantilla;
    window._pqrsUltimaPlantillaOficio='';
  }else{
    return;
  }
  // Oficio: plantilla solo al notificar (VITAL / NCA / oficina en Por notificar).
  // Mensaje: plantilla en compose / entrega.
  const ids=tipo===PQRS_WF_TIPO.OFICIO
    ?['pqrs-notif-cuerpo']
    :['pqrs-resp-cuerpo','pqrs-compose-body','pqrs-entrega-resp-cuerpo','pqrs-notif-cuerpo'];
  ids.forEach(function(id){
    const el=document.getElementById(id);
    if(!el)return;
    const cur=el.value.trim();
    if(force||!cur||_pqrsEsPlantillaRespuesta(cur)||cur.length<40){
      el.value=plantilla;
    }
  });
  // Al pasar a oficio en Responder, limpiar plantilla del compose (no se usa hasta notificar)
  if(tipo===PQRS_WF_TIPO.OFICIO&&(force||true)){
    ['pqrs-compose-body','pqrs-resp-cuerpo'].forEach(function(id){
      const el=document.getElementById(id);
      if(el&&_pqrsEsPlantillaRespuesta(el.value))el.value='';
    });
  }
}
function pqrsRespRefreshModalUiGmail(){
  const tipo=String((document.getElementById('pqrs-resp-tipo')||{}).value||PQRS_WF_TIPO.MENSAJE);
  const cuerpoWrap=document.getElementById('pqrs-resp-cuerpo-wrap');
  const canalWrap=document.getElementById('pqrs-resp-canal-wrap');
  const adjWrap=document.getElementById('pqrs-resp-adj-wrap');
  const submitBtn=document.getElementById('pqrs-resp-submit-btn');
  const oficioReq=document.getElementById('pqrs-resp-oficio-req');
  const oficioHint=document.getElementById('pqrs-resp-oficio-hint');
  const adjLabel=document.getElementById('pqrs-resp-adj-label');
  const adjHint=document.getElementById('pqrs-resp-adj-hint');
  const isOficio=tipo===PQRS_WF_TIPO.OFICIO;
  if(cuerpoWrap)cuerpoWrap.style.display='';
  if(canalWrap)canalWrap.style.display='none';
  if(adjWrap)adjWrap.style.display='';
  if(submitBtn){
    submitBtn.style.display='';
    submitBtn.textContent='✅ Registrar como respuesta oficial';
  }
  if(oficioReq)oficioReq.style.display=isOficio?'':'none';
  if(oficioHint)oficioHint.style.display=isOficio?'none':'';
  if(adjLabel)adjLabel.textContent=isOficio?'Documento del oficio firmado (obligatorio)':'Documentos adjuntos';
  if(adjHint)adjHint.textContent=isOficio?'Debe adjuntar el PDF u oficio firmado. Quedará en Drive y en consulta ciudadana.':'';
  if(tipo===PQRS_WF_TIPO.OFICIO||tipo===PQRS_WF_TIPO.MENSAJE)pqrsAplicarPlantillaSegunTipo(tipo,false);
}
function pqrsRespRefreshModalUi(){
  // Formulario de entrega (responsable): no alterar UI del modal de respuesta
  if(document.getElementById('pqrs-entrega-resp-cuerpo')&&!document.getElementById('pqrs-resp-email-compose')&&!document.getElementById('pqrs-resp-cuerpo')){
    return;
  }
  const tipo=String((document.getElementById('pqrs-resp-tipo')||{}).value||PQRS_WF_TIPO.MENSAJE);
  const canal=String((document.getElementById('pqrs-resp-canal')||{}).value||PQRS_WF_CANAL.CORREO);
  const isInfo=tipo===PQRS_WF_TIPO.INFORMATIVA;
  const isOficio=tipo===PQRS_WF_TIPO.OFICIO;
  const isMensaje=tipo===PQRS_WF_TIPO.MENSAJE;
  const isCorreo=pqrsEsCanalCorreo(canal);
  const isPersonal=pqrsEsCanalNotifPersonal(canal);
  const modoFirmaCtx=!!(window._taskModalCtx&&window._taskModalCtx.modoFirma);
  // Mensaje simple solo por correo; si canal no es correo, pasar a oficio
  if(!isInfo&&isMensaje&&!isCorreo){
    const hid=document.getElementById('pqrs-resp-tipo');
    if(hid)hid.value=PQRS_WF_TIPO.OFICIO;
    document.querySelectorAll('#pqrs-resp-tipo-btns .tipo-resp-btn').forEach(b=>{
      b.classList.toggle('on',b.getAttribute('data-val')===PQRS_WF_TIPO.OFICIO);
    });
    return pqrsRespRefreshModalUi();
  }
  // modoFirma (botón 🖊): oficio → Director. Responder + oficio: ya firmado → notificar.
  const useEmail=!isInfo&&isCorreo&&isMensaje;
  const puedeFirma=modoFirmaCtx&&isOficio&&!isInfo&&typeof pqrsPuedeAtajoParaFirma==='function'&&pqrsPuedeAtajoParaFirma();
  const oficioNotificar=isOficio&&!isInfo&&!modoFirmaCtx;
  const compose=document.getElementById('pqrs-resp-email-compose');
  const cuerpoWrap=document.getElementById('pqrs-resp-cuerpo-wrap');
  const canalWrap=document.getElementById('pqrs-resp-canal-wrap');
  const adjWrap=document.getElementById('pqrs-resp-adj-wrap');
  const anexosWrap=document.getElementById('pqrs-resp-anexos-wrap');
  const emailBtn=document.getElementById('pqrs-resp-email-send-btn');
  const submitBtn=document.getElementById('pqrs-resp-submit-btn');
  const firmaBtn=document.getElementById('pqrs-resp-firma-btn');
  const oficioReq=document.getElementById('pqrs-resp-oficio-req');
  const oficioWrap=document.getElementById('pqrs-resp-oficio-wrap');
  const fechaLbl=document.getElementById('pqrs-resp-fecha-label');
  const adjLabel=document.getElementById('pqrs-resp-adj-label');
  const adjHint=document.getElementById('pqrs-resp-adj-hint');
  const cuerpoLbl=document.getElementById('pqrs-resp-cuerpo-label');

  if(canalWrap)canalWrap.style.display=isInfo||modoFirmaCtx?'none':'';
  document.querySelectorAll('#pqrs-resp-canal-btns .canal-resp-btn').forEach(function(b){
    b.style.display=(isInfo||modoFirmaCtx)?'none':'';
    b.classList.toggle('on',b.getAttribute('data-val')===canal);
  });
  document.querySelectorAll('#pqrs-resp-tipo-btns .tipo-resp-btn').forEach(function(b){
    const v=b.getAttribute('data-val');
    if(v===PQRS_WF_TIPO.MENSAJE)b.style.display=(!isInfo&&!isCorreo)||modoFirmaCtx?'none':'';
    if(v===PQRS_WF_TIPO.INFORMATIVA&&modoFirmaCtx)b.style.display='none';
  });

  if(compose)compose.style.display=(useEmail||(oficioNotificar&&isCorreo))?'':'none';
  const showCuerpo=isInfo||(!useEmail&&!isInfo&&oficioNotificar&&isPersonal);
  if(cuerpoWrap)cuerpoWrap.style.display=showCuerpo?'':'none';
  if(cuerpoLbl){
    if(isInfo)cuerpoLbl.innerHTML='Descripción <span class="req-star">*</span>';
    else if(isPersonal)cuerpoLbl.textContent='Nota (opcional)';
    else cuerpoLbl.textContent='Descripción';
  }
  const cuerpoTxt=document.getElementById('pqrs-resp-cuerpo');
  if(cuerpoTxt){
    if(isInfo){
      cuerpoTxt.placeholder='Descripción visible en consulta ciudadana…';
      if(_pqrsEsPlantillaRespuesta(cuerpoTxt.value))cuerpoTxt.value='';
    }else if(isOficio&&_pqrsEsPlantillaRespuesta(cuerpoTxt.value)){
      cuerpoTxt.value='';
    }else if(!cuerpoTxt.value){
      cuerpoTxt.placeholder=isPersonal?'Opcional…':'';
    }
  }
  const composeBody=document.getElementById('pqrs-compose-body');
  if(composeBody&&isOficio&&_pqrsEsPlantillaRespuesta(composeBody.value))composeBody.value='';

  // Oficio: documento + anexos. Mensaje: adjuntos en compose.
  if(adjWrap)adjWrap.style.display=(useEmail||isInfo)?'none':'';
  if(anexosWrap)anexosWrap.style.display=isOficio&&!isInfo?'inline-flex':'none';
  if(!isOficio){
    const cb=document.getElementById('pqrs-resp-tiene-anexos');
    if(cb&&cb.checked){cb.checked=false;pqrsRespToggleAnexos();}
  }
  if(adjLabel){
    if(puedeFirma)adjLabel.textContent='Oficio para firma (PDF)';
    else if(oficioNotificar)adjLabel.textContent='Oficio firmado (PDF)';
    else if(canal===PQRS_WF_CANAL.WHATSAPP)adjLabel.textContent='Oficio y soporte WhatsApp';
    else if(canal===PQRS_WF_CANAL.AVISO)adjLabel.textContent='Oficio y soporte por aviso';
    else if(isPersonal)adjLabel.textContent='Oficio / constancia';
    else adjLabel.textContent='Documento';
  }
  if(adjHint){adjHint.style.display='none';adjHint.textContent='';}

  if(fechaLbl){
    fechaLbl.innerHTML=(isPersonal||(oficioNotificar&&!isCorreo))
      ?'Fecha de notificación<span class="req-star">*</span>'
      :'Fecha de la respuesta<span class="req-star">*</span>';
  }

  if(firmaBtn){
    firmaBtn.style.display=puedeFirma?'':'none';
    firmaBtn.textContent='🖊 Enviar a firma del Director';
  }
  if(emailBtn){
    emailBtn.style.display=(useEmail||(oficioNotificar&&isCorreo))?'':'none';
    emailBtn.textContent='📤 Enviar correo y cerrar';
  }
  if(submitBtn){
    const hideSubmit=useEmail||(puedeFirma)||(oficioNotificar&&isCorreo);
    submitBtn.style.display=hideSubmit?'none':'';
    if(isInfo)submitBtn.textContent='ℹ️ Marcar informativa y cerrar';
    else if(oficioNotificar||isPersonal)submitBtn.textContent='✅ Registrar notificación y cerrar';
    else submitBtn.textContent='✅ Confirmar y cerrar';
  }
  if(oficioWrap)oficioWrap.style.display=isInfo?'none':(isMensaje?'none':'');
  if(oficioReq)oficioReq.style.display=isOficio?'':'none';

  if(useEmail)pqrsAplicarPlantillaSegunTipo(PQRS_WF_TIPO.MENSAJE,false);
  else if(isPersonal||oficioNotificar){
    const cuerpoEl=document.getElementById('pqrs-resp-cuerpo');
    if(cuerpoEl&&_pqrsEsPlantillaRespuesta(cuerpoEl.value))cuerpoEl.value='';
  }
}
function pqrsComposeAddAttachment(){
  (typeof sstSolicitarGmailParaAdjuntar==='function'?sstSolicitarGmailParaAdjuntar():Promise.resolve(true)).then(function(ok){
    if(!ok)return;
    const inp=document.createElement('input');
    inp.type='file';inp.multiple=true;inp.accept='*/*';
    inp.onchange=function(){
      window._pqrsComposeAttachments=window._pqrsComposeAttachments||[];
      Array.from(inp.files||[]).forEach(function(f){window._pqrsComposeAttachments.push(f);});
      pqrsComposeRenderAttachments();
    };
    inp.click();
  });
}
function pqrsComposeRenderAttachments(){
  const box=document.getElementById('pqrs-compose-att-list');
  if(!box)return;
  const files=window._pqrsComposeAttachments||[];
  if(!files.length){box.innerHTML='';return;}
  if(typeof pqrsClearRespComposeAttError==='function')pqrsClearRespComposeAttError();
  box.innerHTML=files.map(function(f,i){
    return '<div class="fx" style="gap:6px;align-items:center;margin-top:4px;font-size:12px;padding:4px 6px;background:var(--sf2);border-radius:var(--r)">'+
      '📎 <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+escAttr(f.name)+'</span>'+
      '<button type="button" class="btn bsm bd2" onclick="pqrsComposeRemoveAttachment('+i+')">✕</button></div>';
  }).join('');
}
function pqrsComposeRemoveAttachment(idx){
  window._pqrsComposeAttachments=(window._pqrsComposeAttachments||[]).filter(function(_,i){return i!==idx;});
  pqrsComposeRenderAttachments();
}
function setPqrsRespTipo(val){
  const hid=document.getElementById('pqrs-resp-tipo');
  const prev=String((hid&&hid.value)||'');
  if(hid)hid.value=val||'';
  document.querySelectorAll('#pqrs-resp-tipo-btns .tipo-resp-btn').forEach(b=>{b.classList.toggle('on',b.getAttribute('data-val')===val);});
  if(val===PQRS_WF_TIPO.MENSAJE&&!window._gmailVinculoMsg){
    const canHid=document.getElementById('pqrs-resp-canal');
    if(canHid&&!pqrsEsCanalCorreo(canHid.value)){
      canHid.value=PQRS_WF_CANAL.CORREO;
      document.querySelectorAll('#pqrs-resp-canal-btns .canal-resp-btn').forEach(b=>{
        b.classList.toggle('on',b.getAttribute('data-val')===PQRS_WF_CANAL.CORREO);
      });
    }
  }
  if(val===PQRS_WF_TIPO.MENSAJE){
    const canal=String((document.getElementById('pqrs-resp-canal')||{}).value||'');
    if(pqrsEsCanalCorreo(canal)){
      const cambioTipo=(prev===PQRS_WF_TIPO.MENSAJE||prev===PQRS_WF_TIPO.OFICIO)&&prev!==val;
      pqrsAplicarPlantillaSegunTipo(val,cambioTipo);
    }
  }else if(val===PQRS_WF_TIPO.OFICIO){
    // Sin plantilla en Responder/entrega: se limpia compose y se usa al notificar
    pqrsAplicarPlantillaSegunTipo(val,true);
  }else{
    pqrsClearRespOficioError();
    window._pqrsUltimaPlantillaOficio='';
    window._pqrsUltimaPlantillaMensaje='';
  }
  if(val!==PQRS_WF_TIPO.OFICIO)pqrsClearRespOficioError();
  if(document.getElementById('pqrs-entrega-resp-cuerpo')){
    pqrsEntregaRefreshUi();
    return;
  }
  if(window._taskModalCtx&&window._taskModalCtx.mode==='gmailVincularPqrs')pqrsRespRefreshModalUiGmail();
  else if(document.getElementById('pqrs-resp-email-compose')||document.getElementById('pqrs-resp-cuerpo'))pqrsRespRefreshModalUi();
}
function setPqrsRespCanal(val){
  const hid=document.getElementById('pqrs-resp-canal');if(hid)hid.value=val||'';
  document.querySelectorAll('#pqrs-resp-canal-btns .canal-resp-btn').forEach(b=>{b.classList.toggle('on',b.getAttribute('data-val')===val);});
  if(!pqrsEsCanalCorreo(val)){
    const tipoHid=document.getElementById('pqrs-resp-tipo');
    if(tipoHid&&tipoHid.value===PQRS_WF_TIPO.MENSAJE){
      tipoHid.value=PQRS_WF_TIPO.OFICIO;
      document.querySelectorAll('#pqrs-resp-tipo-btns .tipo-resp-btn').forEach(b=>{
        b.classList.toggle('on',b.getAttribute('data-val')===PQRS_WF_TIPO.OFICIO);
      });
    }
  }
  if(document.getElementById('pqrs-entrega-resp-cuerpo')){
    pqrsEntregaRefreshUi();
    return;
  }
  if(window._taskModalCtx&&window._taskModalCtx.mode==='gmailVincularPqrs')pqrsRespRefreshModalUiGmail();
  else if(document.getElementById('pqrs-resp-email-compose')||document.getElementById('pqrs-resp-cuerpo'))pqrsRespRefreshModalUi();
}

function onPqrsRespOficioInput(){
  const tipo=String((document.getElementById('pqrs-resp-tipo')||{}).value||'');
  if(tipo!==PQRS_WF_TIPO.OFICIO)return;
  const canal=String((document.getElementById('pqrs-resp-canal')||{}).value||'');
  if(!pqrsEsCanalCorreo(canal))return;
  const composeEl=document.getElementById('pqrs-compose-body');
  const cuerpoEl=document.getElementById('pqrs-resp-cuerpo');
  const cur=(composeEl&&composeEl.value.trim())||(cuerpoEl&&cuerpoEl.value.trim())||'';
  const esPlantilla=window._pqrsUltimaPlantillaOficio&&cur===window._pqrsUltimaPlantillaOficio;
  if(esPlantilla||!cur||/^(\s*(fwd?|re):)/i.test(cur)||_pqrsEsPlantillaRespuesta(cur))pqrsAplicarPlantillaOficioSiCorresponde(true);
}
function onPqrsRespOficioBlur(){
  const tipo=String((document.getElementById('pqrs-resp-tipo')||{}).value||'');
  const oficio=String((document.getElementById('pqrs-resp-oficio')||{}).value||'').trim();
  if(!oficio||oficio.length<4)return;
  // Validar duplicado también en entrega (oficio opcional) y en respuesta
  if(tipo&&tipo!==PQRS_WF_TIPO.OFICIO&&!document.getElementById('pqrs-entrega-resp-oficio'))return;
  const expId=String((document.getElementById('gmail-resp-pqrs-hid')||{}).value||(window._taskModalCtx||{}).expId||'').trim();
  const usos=buscarUsosNumeroOficio(oficio,expId);
  if(usos.length)validarNumeroOficioDisponible(oficio,expId);
}
function addPqrsRespAdjFile(boxId){
  (typeof sstSolicitarGmailParaAdjuntar==='function'?sstSolicitarGmailParaAdjuntar():Promise.resolve(true)).then(function(ok){
    if(!ok)return;
    const boxSel=boxId||'pqrs-resp-adj-rows';
    const inp=document.createElement('input');inp.type='file';inp.multiple=true;inp.accept='*/*';
    inp.onchange=function(){
      const box=document.getElementById(boxSel);
      if(!box)return;
      Array.from(inp.files||[]).forEach(f=>{
        const row=document.createElement('div');
        row.className='fx pqrs-adj-file-row';
        row.style.cssText='gap:6px;margin-bottom:5px;align-items:center;padding:5px;background:var(--sf2);border-radius:var(--r);font-size:12px';
        row.dataset.file=f.name;
        const icon=f.type.startsWith('image/')?'🖼️':f.type.includes('pdf')?'📄':'📎';
        row.innerHTML=icon+' <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+escAttr(f.name)+'</span>'+
          '<span class="adj-upload-status" style="font-size:11px;color:var(--tx2)">Listo</span>'+
          '<button type="button" class="btn bsm bd2" onclick="this.parentElement.remove()">✕</button>';
        row._adjFile=f;
        box.appendChild(row);
        if(typeof pqrsClearRespAdjError==='function')pqrsClearRespAdjError();
      });
    };
    inp.click();
  });
}
function setPqrsRespMedioNotif(val){
  // Legacy compat — delegate to canal
  setPqrsRespCanal(val||'');
}
function addPqrsRespAdjRow(boxId){
  // Legacy: ya no se usa «+ Link Drive» en Responder; se conserva por compatibilidad
  const box=document.getElementById(boxId||'pqrs-resp-adj-rows');
  if(!box)return;
  const row=document.createElement('div');
  row.className='fx pqrs-adj-link-row';
  row.style.cssText='gap:6px;margin-bottom:6px;align-items:center';
  row.innerHTML='<input type="url" data-adj="link" placeholder="https://drive.google.com/file/d/…" style="flex:1;padding:6px;border:1px solid var(--bd);border-radius:var(--r);font-size:12px"><button type="button" class="btn bsm bd2" onclick="this.parentElement.remove()">✕</button>';
  box.appendChild(row);
}
function pqrsRespToggleAnexos(){
  const cb=document.getElementById('pqrs-resp-tiene-anexos');
  const box=document.getElementById('pqrs-resp-anexos-box');
  if(!box)return;
  const on=!!(cb&&cb.checked);
  box.style.display=on?'':'none';
  if(!on)pqrsRespClearAnexos();
}
function pqrsRespAddAnexos(){
  (typeof sstSolicitarGmailParaAdjuntar==='function'?sstSolicitarGmailParaAdjuntar():Promise.resolve(true)).then(function(ok){
    if(!ok)return;
    const inp=document.getElementById('pqrs-resp-anexos-file');
    if(inp)inp.click();
  });
}
function pqrsRespOnAnexosChange(inp){
  const box=document.getElementById('pqrs-resp-anexos-list');
  if(!box)return;
  const files=inp&&inp.files?Array.from(inp.files):[];
  if(!files.length){box.innerHTML='';return;}
  box.innerHTML=files.map(function(f,i){
    return '<div class="fx" style="gap:6px;align-items:center;margin-top:4px;font-size:12px;padding:4px 6px;background:var(--sf2);border-radius:var(--r)">'+
      '📎 <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap"><strong>Anexo '+(i+1)+'</strong> · '+escAttr(f.name)+'</span>'+
      (i===0?'<button type="button" class="btn bsm bd2" onclick="pqrsRespClearAnexos()">✕</button>':'')+
      '</div>';
  }).join('');
}
function pqrsRespClearAnexos(){
  const expId=String((document.getElementById('gmail-resp-pqrs-hid')||{}).value||(window._taskModalCtx||{}).expId||'').trim();
  if(typeof sstFileStagingReset==='function'&&expId){
    const ctxKey=typeof sstFileCtxKeyPqrsRespAnexos==='function'?sstFileCtxKeyPqrsRespAnexos(expId):('pqrs-resp-anexos:'+expId);
    sstFileStagingReset(ctxKey);
    if(typeof sstFileInitPick==='function')sstFileInitPick('pqrs-resp-anexos-file');
  }
  const inp=document.getElementById('pqrs-resp-anexos-file');
  if(inp)inp.value='';
  const box=document.getElementById('pqrs-resp-anexos-list');
  if(box&&!box.classList.contains('sst-file-slot-list'))box.innerHTML='';
  const cb=document.getElementById('pqrs-resp-tiene-anexos');
  if(cb&&!cb.checked){
    const wrap=document.getElementById('pqrs-resp-anexos-box');
    if(wrap)wrap.style.display='none';
  }
}
function collectPqrsRespAnexos(){
  const expId=String((document.getElementById('gmail-resp-pqrs-hid')||{}).value||(window._taskModalCtx||{}).expId||'').trim();
  const tiene=!!(document.getElementById('pqrs-resp-tiene-anexos')||{}).checked;
  if(!tiene)return[];
  if(typeof sstFileCollect==='function'&&expId){
    const ctxKey=typeof sstFileCtxKeyPqrsRespAnexos==='function'?sstFileCtxKeyPqrsRespAnexos(expId):('pqrs-resp-anexos:'+expId);
    const col=sstFileCollect(ctxKey);
    const out=[];
    (col.anexos||[]).forEach(function(r){if(r&&r.blob)out.push(r.blob);});
    return out;
  }
  const inp=document.getElementById('pqrs-resp-anexos-file');
  if(!inp||!inp.files||!inp.files.length)return[];
  return Array.from(inp.files).filter(Boolean);
}
function collectPqrsRespAdjuntos(boxId){
  const expId=String((document.getElementById('gmail-resp-pqrs-hid')||{}).value||(window._taskModalCtx||{}).expId||'').trim();
  const sel=(boxId||'pqrs-resp-adj-rows');
  const links=[];
  document.querySelectorAll('#'+sel+' [data-adj="link"]').forEach(el=>{
    const v=el.value.trim();if(v)links.push(v);
  });
  const files=[];
  const preUploaded=[];
  if(typeof sstFileCollect==='function'&&expId&&(!boxId||boxId==='pqrs-resp-adj-rows')){
    const ctxKey=typeof sstFileCtxKeyPqrsRespAdj==='function'?sstFileCtxKeyPqrsRespAdj(expId):('pqrs-resp-adj:'+expId);
    const col=sstFileCollect(ctxKey);
    (col.files||[]).forEach(function(r){
      if(r&&r.blob)files.push({file:r.blob,statusEl:null});
    });
    (col.preUploaded||[]).forEach(function(up){preUploaded.push(up);});
  }else{
    document.querySelectorAll('#'+sel+' .pqrs-adj-file-row').forEach(row=>{
      if(row._adjFile)files.push({file:row._adjFile,statusEl:row.querySelector('.adj-upload-status')});
    });
  }
  return{links,files,anexos:collectPqrsRespAnexos(),preUploaded:preUploaded};
}
/**
 * Oficinas (RN/OAP/Admin/Secretaría/NCA): oficio + anexos → «Por firmar» del Director
 * (como NCA). Sin plantilla de correo aquí; la plantilla aparece al notificar.
 * Mensaje simple = atajo enviar correo y cerrar (submitPqrsRespuestaPorCorreo).
 */
async function submitPqrsRespuestaParaFirma(expId){
  if(typeof guardMantenimientoSoloConsulta==='function'&&guardMantenimientoSoloConsulta())return;
  const e=exps.find(x=>String(x._exp||'').trim()===String(expId||'').trim());
  if(!e||!puedeMarcarPqrsRespondida(e)){notif('No puede registrar respuesta','err');return;}
  if(!(typeof pqrsPuedeAtajoParaFirma==='function'&&pqrsPuedeAtajoParaFirma())){
    notif('No puede enviar a firma del Director desde esta sesión','err');return;
  }
  const fechaResp=String((document.getElementById('pqrs-resp-fecha')||{}).value||'').trim();
  const oficioExt=String((document.getElementById('pqrs-resp-oficio')||{}).value||'').trim();
  const tipoResp=String((document.getElementById('pqrs-resp-tipo')||{}).value||PQRS_WF_TIPO.MENSAJE).trim();
  const canal=String((document.getElementById('pqrs-resp-canal')||{}).value||PQRS_WF_CANAL.CORREO).trim();
  const cuerpoTxt=String((document.getElementById('pqrs-resp-cuerpo')||{}).value||'').trim();
  const cuerpo=(!_pqrsEsPlantillaRespuesta(cuerpoTxt)?cuerpoTxt:'');
  const notaInterna=String((document.getElementById('pqrs-resp-nota')||{}).value||'').trim();
  if(tipoResp!==PQRS_WF_TIPO.OFICIO){notif('Seleccione «Oficio para firma»','err');return;}
  if(!fechaResp){notif('Indique la fecha de la respuesta','err');return;}
  if(!pqrsValidateOficioRespuesta(tipoResp,{requireAdj:true,adjMsg:'Adjunte el PDF del oficio',skipDupCheck:false}))return;

  const adj=collectPqrsRespAdjuntos();
  const oficioFiles=(adj.files||[]).map(function(x){return x&&x.file;}).filter(Boolean);
  const anexosFiles=adj.anexos||[];
  const preOficio=(adj.preUploaded||[]).filter(function(up){return up&&!up.esAnexo;});
  const tieneAnexos=!!(document.getElementById('pqrs-resp-tiene-anexos')||{}).checked;
  if(tieneAnexos&&!anexosFiles.length){
    notif('Marcó que hay anexos: adjunte al menos un archivo de anexo','err');return;
  }
  if(!oficioFiles.length&&!preOficio.length){
    notif('Adjunte el PDF del oficio para firma del Director','err');return;
  }

  const firmaBtn=document.getElementById('pqrs-resp-firma-btn');
  const emailBtn=document.getElementById('pqrs-resp-email-send-btn');
  const submitBtn=document.getElementById('pqrs-resp-submit-btn');
  if(firmaBtn){firmaBtn.disabled=true;firmaBtn.textContent='Subiendo…';}
  if(emailBtn)emailBtn.disabled=true;
  if(submitBtn)submitBtn.disabled=true;

  const documentos=[];
  const usaDriveInst=typeof DRIVE_INST_DEPTOS!=='undefined'&&DRIVE_INST_DEPTOS.has(deptoActivo||deptoCfg||'');
  const nombreCarpeta=(e._qd_nombre||e._nombre||e._pn_nombre||expId);
  try{
    if(!usaDriveInst){
      notif('Se requiere Drive institucional para enviar a firma','err');
      throw new Error('Sin Drive institucional');
    }
    const driveOk=typeof sstSolicitarDriveParaPqrs==='function'?await sstSolicitarDriveParaPqrs(e):(typeof sstSolicitarGmailParaAdjuntar==='function'?await sstSolicitarGmailParaAdjuntar():Promise.resolve(true));
    if(!driveOk){
      if(firmaBtn){firmaBtn.disabled=false;firmaBtn.textContent='🖊 Enviar a firma del Director';}
      if(emailBtn)emailBtn.disabled=false;
      if(submitBtn)submitBtn.disabled=false;
      return;
    }
    const allUp=[];
    (adj.preUploaded||[]).forEach(function(up){
      if(up)allUp.push({preUp:up,esAnexo:!!up.esAnexo});
    });
    oficioFiles.forEach(function(f){allUp.push({file:f,esAnexo:false});});
    anexosFiles.forEach(function(f){allUp.push({file:f,esAnexo:true});});
    if(typeof sstCargaShow==='function')sstCargaShow({title:'Enviando a firma',message:'Subiendo oficio y anexos al Drive…',pct:10,sub:(oficioFiles[0]&&oficioFiles[0].name)||((adj.preUploaded[0]||{}).nombre||'')});
    let anexoSeq=0;
    for(let i=0;i<allUp.length;i++){
      const item=allUp[i];
      const esAnexo=!!item.esAnexo;
      if(esAnexo)anexoSeq++;
      let res=null;
      if(item.preUp){
        res=item.preUp;
        if(typeof sstCargaProgress==='function')sstCargaProgress(Math.round(15+(i/allUp.length)*70),'Usando «'+(res.nombre||res.driveFilename||'archivo')+'» en Drive…');
      }else{
        const file=item.file;
        const pref=esAnexo
          ?('por_firmar-anexo-'+anexoSeq+'-'+file.name)
          :('por_firmar-'+file.name);
        if(typeof sstCargaProgress==='function')sstCargaProgress(Math.round(15+(i/allUp.length)*70),'Subiendo «'+file.name+'»…');
        res=await driveUploadInstitutional(file,pref,file.type||'application/pdf','respuesta_aprobada',expId,nombreCarpeta,e._fecha||e._fecha_solicitud||'',{expediente:e,uploadTarget:'respuesta'});
      }
      if(esAnexo){
        documentos.push({
          nombre:'Anexo '+anexoSeq,
          labelAnexo:'Anexo '+anexoSeq,
          driveLink:res.driveLink,
          previewLink:res.previewLink||res.driveLink,
          fileId:res.fileId||res.driveFileId||'',
          tipo:'anexo_respuesta',
          es_anexo:true,
          anexo_n:anexoSeq,
          mime:(item.file&&item.file.type)||res.mime||'',
          driveEstado:'por_firmar'
        });
      }else{
        documentos.push({
          nombre:res.driveFilename||res.nombre||(item.file?('por_firmar-'+item.file.name):'por_firmar-oficio.pdf'),
          driveLink:res.driveLink,
          previewLink:res.previewLink||res.driveLink,
          fileId:res.fileId||res.driveFileId||'',
          tipo:'oficio_firmado',
          mime:(item.file&&item.file.type)||res.mime||'',
          driveEstado:'por_firmar'
        });
      }
    }
    if(!documentos.length){
      notif('No se pudo preparar el documento para firma','err');
      throw new Error('Sin documentos');
    }

    const wf=getPqrsWorkflow(e);
    const docsFinal=documentos;
    // Oficinas: notificador = misma oficina (encargado / quien envía). VITAL solo en flujo NCA.
    let notifPor=pqrsAplicarReglaNotificadorCanal(e,canal,wf.notificar_por||wf.notificar_por_propuesto||responsableActivo||'');
    if(typeof pqrsAsegurarNotificadorSegunOficina==='function'){
      notifPor=pqrsAsegurarNotificadorSegunOficina(e,notifPor||responsableActivo||'');
    }
    const por=responsableActivo||labelOficina(deptoActivo)||rolSesion||'';
    const correosCiud=typeof pqrsCorreosCiudadano==='function'?pqrsCorreosCiudadano(e):[];
    const patchWf={
      fase:PQRS_WF.POR_FIRMAR,
      tipo:PQRS_WF_TIPO.OFICIO,
      canal:canal,
      cuerpo:cuerpo||('Oficio '+oficioExt+' enviado a firma'),
      oficio:oficioExt,
      fecha_respuesta:fechaResp,
      documentos:docsFinal,
      email_to:String(wf.email_to||correosCiud.join(', ')||'').trim(),
      email_cc:String(wf.email_cc||'').trim(),
      email_bcc:String(wf.email_bcc||'').trim(),
      revision_nca:{aprobado:true,tipo:'oficio',comentario:'Atajo oficina → firma Director',por:por,en:new Date().toISOString(),atajo_firma:true},
      listo_firma:{por:por,en:new Date().toISOString(),atajo_digital:true},
      impreso:null,
      firma_fisica:null,
      firma_director:null
    };
    if(notifPor){
      patchWf.notificar_por=notifPor;
      patchWf.notificar_por_propuesto=notifPor;
    }
    if(typeof _pqrsRenombrarDocsDriveWf==='function'){
      try{await _pqrsRenombrarDocsDriveWf(Object.assign({},wf,{documentos:docsFinal}),'por_firmar');}catch(errR){console.warn('submitPqrsRespuestaParaFirma rename:',errR);}
    }
    setPqrsWorkflow(e,patchWf);
    if(notaInterna)e._pqrs_notas_internas=notaInterna;
    e._pqrs_respuesta_oficio=oficioExt;
    e._pqrs_respuesta_fecha=fechaResp;
    e._pqrs_respuesta_nota=patchWf.cuerpo;
    if(!Array.isArray(e._pqrs_historial))e._pqrs_historial=[];
    e._pqrs_historial.push({
      tipo:'oficina_atajo_firma',
      fecha:hoy(),
      nota:'Oficio enviado a firma del Director'+(anexoSeq?' · '+anexoSeq+' anexo(s)':'')+(notifPor?' · Notificará: '+notifPor:''),
      oficina:e._pqrs_oficina||deptoActivo,
      por:por
    });
    if(typeof pqrsSincronizarParticipacionPostAprobacion==='function')pqrsSincronizarParticipacionPostAprobacion(e);
    if(typeof sstCargaDone==='function'&&window._confirmRadicacionLoading)sstCargaDone({holdMs:200});
    persistExpedienteGranular(e);
    closeTaskModal();
    renderPqrsOficinaInbox();
    renderSecretariaPqrs();
    if(typeof renderActividades==='function')renderActividades();
    refreshPqrsDetalleViews(expId);
    notif('🖊 Oficio en «Por firmar» — el Director lo verá en su bandeja'+(anexoSeq?' · '+anexoSeq+' anexo(s)':'')+(notifPor?' · Notificará: '+notifPor:''),'ok');
  }catch(err){
    if(typeof sstCargaHide==='function')sstCargaHide();
    console.error('submitPqrsRespuestaParaFirma:',err);
    notif('No se pudo enviar a firma: '+String(err.message||err).slice(0,90),'err');
    if(firmaBtn){firmaBtn.disabled=false;firmaBtn.textContent='🖊 Enviar a firma del Director';}
    if(emailBtn)emailBtn.disabled=false;
    if(submitBtn)submitBtn.disabled=false;
  }
}
async function submitPqrsRespuesta(expId){
  const e=exps.find(x=>String(x._exp||'').trim()===String(expId||'').trim());
  if(!e||!puedeMarcarPqrsRespondida(e)){notif('No puede registrar respuesta','err');return;}
  const fechaResp=String((document.getElementById('pqrs-resp-fecha')||{}).value||'').trim();
  const oficioExt=String((document.getElementById('pqrs-resp-oficio')||{}).value||'').trim();
  const tipoResp=String((document.getElementById('pqrs-resp-tipo')||{}).value||PQRS_WF_TIPO.MENSAJE).trim();
  const canal=String((document.getElementById('pqrs-resp-canal')||{}).value||'').trim();
  const cuerpo=String((document.getElementById('pqrs-resp-cuerpo')||{}).value||'').trim();
  const notaInterna=String((document.getElementById('pqrs-resp-nota')||{}).value||'').trim();
  const adj=collectPqrsRespAdjuntos();
  const isPersonal=pqrsEsCanalNotifPersonal(canal);
  if(!fechaResp){notif(isPersonal?'Indique la fecha de notificación':'Indique la fecha de la respuesta','err');return;}
  if(!pqrsValidateOficioRespuesta(tipoResp,{requireAdj:tipoResp===PQRS_WF_TIPO.OFICIO&&isPersonal}))return;
  if(!pqrsValidateAdjuntosPorCanal(tipoResp,canal))return;
  if(tipoResp===PQRS_WF_TIPO.INFORMATIVA){
    // Descripción pública obligatoria (consulta ciudadana)
    const descInfo=String(cuerpo||notaInterna||'').trim();
    if(!descInfo){
      notif('La descripción informativa es obligatoria y será visible en consulta ciudadana','err');
      const cEl=document.getElementById('pqrs-resp-cuerpo');
      if(cEl){cEl.focus();cEl.classList.add('fld-invalid');}
      return;
    }
    e._pqrs_informativa=true;
    setPqrsWorkflow(e,{fase:PQRS_WF.CERRADA,tipo:PQRS_WF_TIPO.INFORMATIVA,canal:'',cuerpo:descInfo,oficio:'',fecha_respuesta:fechaResp,cerrado_por:responsableActivo||labelOficina(deptoActivo)||rolSesion||'',cerrado_en:new Date().toISOString()});
    if(!Array.isArray(e._pqrs_historial))e._pqrs_historial=[];
    e._pqrs_historial.push({tipo:'informativa',fecha:hoy(),nota:descInfo+' — '+pqrsComentarioAutor(),oficina:e._pqrs_oficina,por:pqrsComentarioAutor()});
    e._pqrs_respuesta_nota=descInfo;
    if(notaInterna&&notaInterna!==descInfo)e._pqrs_notas_internas=notaInterna;
    e._pqrs_estado_oficina='cerrado';e._estado='Atendido';e._fecha_res=fechaResp;e._pqrs_respuesta_fecha=fechaResp;
    if(typeof completarTareasAtenderPqrs==='function')completarTareasAtenderPqrs(e,descInfo);
    if(typeof finalizarTareasPqrsAlCerrar==='function')finalizarTareasPqrsAlCerrar(e,'PQRSD cerrada — respuesta informativa');
    persistExpedienteGranular(e);
    closeTaskModal();
    notif('PQRSD marcada como informativa y cerrada','ok');
    refreshPqrsDetalleViews(expId);renderPqrsOficinaInbox();renderSecretariaPqrs();
    if(typeof renderActividades==='function')renderActividades();
    return;
  }

  const btn=document.getElementById('pqrs-resp-submit-btn');
  if(btn){btn.disabled=true;btn.textContent='Subiendo archivos…';}
  const documentos=[];
  const usaDriveInst=typeof DRIVE_INST_DEPTOS!=='undefined'&&DRIVE_INST_DEPTOS.has(deptoActivo||deptoCfg||'');
  const nombreCarpeta=(e._qd_nombre||e._nombre||e._pn_nombre||expId);
  if(usaDriveInst&&adj.files&&adj.files.length){
    const driveOk=typeof sstSolicitarDriveParaPqrs==='function'?await sstSolicitarDriveParaPqrs(e):(typeof sstSolicitarGmailParaAdjuntar==='function'?await sstSolicitarGmailParaAdjuntar():Promise.resolve(true));
    if(!driveOk){
      if(btn){btn.disabled=false;btn.textContent='✅ Confirmar y cerrar PQRSD';}
      return;
    }
    const totFiles=adj.files.length;
    if(typeof sstCargaShow==='function')sstCargaShow({title:'Cargando respuesta',message:'Subiendo documentos al Drive…',pct:0,sub:'0 de '+totFiles});
    let idxFile=0;
    for(const {file,statusEl} of adj.files){
      try{
        if(statusEl)statusEl.textContent='⬆ Subiendo…';
        if(typeof sstCargaProgress==='function')sstCargaProgress(Math.round((idxFile/totFiles)*90),'Subiendo «'+file.name+'»…');
        const res=await driveUploadInstitutional(file,file.name,file.type||'application/octet-stream','respuesta_aprobada',expId,nombreCarpeta,e._fecha||e._fecha_solicitud||'',{expediente:e,uploadTarget:'respuesta'});
        if(statusEl)statusEl.textContent='✅ Subido';
        const esOficioDoc=tipoResp===PQRS_WF_TIPO.OFICIO&&idxFile===0;
        const esSoporteNotif=isPersonal&&(tipoResp!==PQRS_WF_TIPO.OFICIO||idxFile>0);
        documentos.push({
          nombre:file.name,
          driveLink:res.driveLink,
          previewLink:res.previewLink,
          fileId:res.fileId,
          tipo:esOficioDoc?'oficio_firmado':(esSoporteNotif?'soporte_notificacion':'archivo'),
          mime:file.type||''
        });
        idxFile++;
      }catch(err){
        if(statusEl)statusEl.textContent='❌ Error';
        console.error('Drive upload error:',err);
        if(typeof sstCargaHide==='function')sstCargaHide();
        notif('Error al subir '+file.name+': '+String(err.message||err).slice(0,80),'err');
      }
    }
    if(typeof sstCargaProgress==='function'&&window._confirmRadicacionLoading)sstCargaProgress(92,'Finalizando registro…');
  }
  adj.links.forEach(lnk=>documentos.push({nombre:'Link Drive',driveLink:lnk,tipo:'link'}));

  const histNotaCanal=isPersonal
    ?('Notificación '+medioNotificacionRespLabel(canal)+' el '+fechaResp+(oficioExt?' · Oficio '+oficioExt:''))
    :(cuerpo||'Respuesta registrada');
  const wfPatch={
    fase:PQRS_WF.CERRADA,
    tipo:tipoResp,
    canal,
    cuerpo:cuerpo||histNotaCanal,
    oficio:oficioExt,
    fecha_respuesta:fechaResp,
    fecha_notificacion:isPersonal?fechaResp:fechaResp,
    documentos,
    cerrado_por:responsableActivo||labelOficina(deptoActivo)||rolSesion||'',
    cerrado_en:new Date().toISOString()
  };
  // Generar y subir soporte PDF de respuesta antes de persistir
  if(btn)btn.textContent='Generando soporte…';
  const soporteRes=await _pqrsSubirSoporteRespuesta(e,{fechaResp,cuerpo:wfPatch.cuerpo,documentos,cerradoPor:wfPatch.cerrado_por});
  if(soporteRes&&soporteRes.driveLink){
    documentos.push({nombre:'Soporte de respuesta',driveLink:soporteRes.driveLink,previewLink:soporteRes.previewLink||'',fileId:soporteRes.fileId||'',tipo:'soporte_respuesta'});
    wfPatch.documentos=documentos;
  }
  setPqrsWorkflow(e,wfPatch);
  registrarPqrsRespuestaCore(e,{fechaResp,oficioExt,medioResp:canal,cuerpo:wfPatch.cuerpo,tipo:tipoResp,canal,notaInterna,esNotaPublica:false,adj:{links:adj.links,files:[]},archivos:documentos});
  if(isPersonal){
    if(!Array.isArray(e._pqrs_historial))e._pqrs_historial=[];
    e._pqrs_historial.push({
      tipo:'notificacion_'+canal,
      fecha:fechaResp,
      nota:histNotaCanal+' — '+pqrsComentarioAutor(),
      oficina:e._pqrs_oficina,
      por:pqrsComentarioAutor()
    });
  }
  persistExpedienteGranular(e);
  if(btn){btn.disabled=false;btn.textContent='✅ Confirmar y cerrar PQRSD';}
  if(typeof sstCargaDone==='function'&&window._confirmRadicacionLoading)sstCargaDone({holdMs:200});
  closeTaskModal();
  notif(isPersonal?'✅ Notificación registrada — PQRSD atendida':'✅ Respuesta PQRSD registrada — expediente Atendido','ok');
  refreshPqrsDetalleViews(expId);
  renderPqrsOficinaInbox();
  renderSecretariaPqrs();

  // Canal correo por este submit solo si no usó el compose (caso raro); los personales ya cargaron soporte
  if(pqrsEsCanalCorreo(canal)){
    const todosCorreos=pqrsCorreosCiudadano(e);
    const tokSec=typeof gmailIsTokenValid==='function'&&gmailIsTokenValid();
    const tokOfi=typeof gmailOfiIsTokenValid==='function'&&gmailOfiIsTokenValid();
    const destinos=todosCorreos.length?todosCorreos:[];
    if(destinos.length&&(tokSec||tokOfi)){
      if(typeof confirmarEnvioRespuestaEmailPqrs==='function')confirmarEnvioRespuestaEmailPqrs(e,destinos.join(', '),cuerpo,documentos);
    }
  }
}
async function submitPqrsRespuestaPorCorreo(expId){
  const e=exps.find(x=>String(x._exp||'').trim()===String(expId||'').trim());
  if(!e||!puedeMarcarPqrsRespondida(e)){notif('No puede registrar respuesta','err');return;}
  const fechaResp=String((document.getElementById('pqrs-resp-fecha')||{}).value||'').trim();
  const oficioExt=String((document.getElementById('pqrs-resp-oficio')||{}).value||'').trim();
  const tipoResp=String((document.getElementById('pqrs-resp-tipo')||{}).value||PQRS_WF_TIPO.MENSAJE).trim();
  const toRaw=String((document.getElementById('pqrs-compose-to')||{}).value||'').trim();
  const ccRaw=String((document.getElementById('pqrs-compose-cc')||{}).value||'').trim();
  const bccRaw=String((document.getElementById('pqrs-compose-bcc')||{}).value||'').trim();
  const subject=String((document.getElementById('pqrs-compose-subject')||{}).value||'').trim();
  const body=String((document.getElementById('pqrs-compose-body')||{}).value||'').trim();
  const notaInterna=String((document.getElementById('pqrs-resp-nota')||{}).value||'').trim();
  // Unir correos digitados + todos los asociados a la PQRSD
  const asociados=pqrsCorreosCiudadano(e);
  const digitados=toRaw.split(/[,;\s]+/).map(function(s){return s.trim().toLowerCase();}).filter(function(s){return s&&s.includes('@');});
  const toSet=new Set(asociados.concat(digitados));
  const toList=Array.from(toSet);
  const to=toList.join(', ');
  if(!fechaResp){notif('Indique la fecha de la respuesta','err');return;}
  // Oficio firmado: PDF desde zona de documento; mensaje: adjuntos del compose
  let atts=(window._pqrsComposeAttachments||[]).slice();
  if(tipoResp===PQRS_WF_TIPO.OFICIO){
    if(!pqrsValidateOficioRespuesta(tipoResp,{requireAdj:true,adjMsg:'Adjunte el PDF del oficio firmado'}))return;
    const adj=collectPqrsRespAdjuntos();
    (adj.files||[]).forEach(function(x){if(x&&x.file)atts.push(x.file);});
    (adj.anexos||[]).forEach(function(f){if(f)atts.push(f);});
  }else if(!pqrsValidateOficioRespuesta(tipoResp,{requireComposeAtt:false}))return;
  if(!toList.length){notif('Indique al menos un correo del ciudadano','err');return;}
  if(!body.trim()){notif('Escriba el mensaje de respuesta','err');return;}
  const tokOk=(typeof gmailOfiIsTokenValid==='function'&&gmailOfiIsTokenValid())||(typeof gmailIsTokenValid==='function'&&gmailIsTokenValid())||(typeof _gmailOfiTokenValid==='function'&&_gmailOfiTokenValid());
  if(!tokOk){notif('Conecte el correo de la oficina para enviar','err');return;}
  // Sincronizar campo Para con la lista completa
  const toEl=document.getElementById('pqrs-compose-to');
  if(toEl)toEl.value=to;
  const btn=document.getElementById('pqrs-resp-email-send-btn');
  if(btn){btn.disabled=true;btn.textContent='⏳ Enviando…';}
  try{
    if(typeof gmailOfiSendPqrsRespuestaInline!=='function')throw new Error('Módulo de correo no disponible');
    await gmailOfiSendPqrsRespuestaInline({
      expId:expId,
      to:to,
      cc:ccRaw,
      bcc:bccRaw,
      subject:subject,
      body:body,
      attachments:atts,
      tipo:tipoResp,
      oficio:oficioExt,
      fechaResp:fechaResp,
      notaInterna:notaInterna
    });
    closeTaskModal();
    refreshPqrsDetalleViews(expId);
    renderPqrsOficinaInbox();
    renderSecretariaPqrs();
  }catch(err){
    notif('Error al enviar: '+String(err.message||err).slice(0,100),'err');
  }
  if(btn){btn.disabled=false;btn.textContent='📤 Enviar correo y cerrar';}
}
function htmlPqrsNotasInternasHtml(e){
  if(!e||!e._pqrs_notas_internas||typeof esModoCiudadano==='function'&&esModoCiudadano())return'';
  return '<div class="pqrs-det-sec pqrs-notas-internas"><div class="pqrs-det-k">Notas internas</div><div class="pqrs-det-v" style="font-size:12px;color:var(--tx2)">'+escAttr(e._pqrs_notas_internas)+'</div></div>';
}
function pqrsMedioNotificacionFlagHtml(e,compact){return medioNotificacionFlagHtml(e&&e._medio_notificacion,compact);}
function pqrsHistorialEventoLabel(h){
  if(!h)return'Actualización';
  if(h.tipo==='radicacion')return 'Radicación de la solicitud';
  if(h.tipo==='traslado_oficina'){
    const dest=labelOficina(h.oficina||h.a||'');
    const orig=h.oficinaAnterior?labelOficina(h.oficinaAnterior):'';
    return orig?'Traslado: '+orig+' → '+dest:'Traslado a '+dest;
  }
  if(h.tipo==='asignacion_oficina')return 'Asignación a responsable de la oficina';
  if(h.tipo==='respuesta_oficina')return 'Respuesta registrada';
  if(h.tipo==='entrega_respuesta')return 'Entrega con datos de respuesta';
  if(h.tipo==='recepcion_nca')return 'Recibido en NCA DEGUV';
  if(h.tipo==='informativa')return 'Marcada como informativa';
  if(h.tipo==='asociacion_exp')return 'Asociada a expediente de trámite';
  if(h.tipo==='asociacion_pqrs')return 'Asociada a otra PQRSD';
  if(h.tipo==='ajuste_fecha_solicitud')return 'Ajuste fecha de solicitud del ciudadano';
  if(h.tipo==='notificacion_radicacion')return 'Notificación de radicación al ciudadano (correo)';
  if(h.tipo==='notificacion_correo')return 'Notificación de respuesta al ciudadano (correo)';
  if(h.tipo==='notificacion_excepcion')return 'Excepción — notificación por correo no enviada';
  if(h.tipo==='notificacion_personal_pendiente')return 'Notificación física/presencial — soporte pendiente';
  if(h.tipo==='aviso_informativo_correo')return 'Aviso simple enviado al ciudadano (correo)';
  if(h.tipo==='vital_firma_completada')return 'VITAL — oficio firmado subido al Drive institucional';
  return 'Actualización';
}
function renderPqrsTrazabilidadHtml(e){
  e=normalizePqrsOficinaFields(e);
  const medio=medioNotificacionFlagHtml(e._medio_notificacion,false);
  let items=[];
  const hist=(e._pqrs_historial||[]).slice().sort((a,b)=>String(a.fecha||'').localeCompare(String(b.fecha||'')));
  if(!hist.some(h=>h.tipo==='radicacion')&&e._fecha){
    items.push({tipo:'radicacion',fecha:e._fecha,nota:'Radicado por Secretaría DEGUV',oficina:''});
  }
  hist.forEach(h=>items.push(h));
  if(!items.length)return'';
  const tl=items.map(h=>{
    const lbl=pqrsHistorialEventoLabel(h);
    const nota=String(h.nota||'').trim();
    const esTrasl=h.tipo==='traslado_oficina';
    const motivoHtml=esTrasl&&nota?('<div class="tl-motivo"><strong>Motivo:</strong> '+escAttr(nota)+'</div>'):'';
    const extra=(!esTrasl&&nota)?(': '+escAttr(nota)):'';
    const por=h.por?('<div class="tl-motivo">Por: '+escAttr(h.por)+'</div>'):'';
    return '<div class="pqrs-tl-item"><div class="tl-fecha">'+fmtF(h.fecha||e._fecha)+'</div><div class="tl-nota"><strong>'+escAttr(lbl)+'</strong>'+extra+'</div>'+motivoHtml+por+'</div>';
  }).join('');
  return '<div class="pqrs-det-sec"><div class="pqrs-det-k">Trazabilidad</div>'+
    (medio?('<div class="fx" style="gap:6px;flex-wrap:wrap;margin-bottom:10px"><span style="font-size:11px;color:var(--tx2);align-self:center">Medio de notificación:</span>'+medio+'</div>'):'')+
    tl+'</div>';
}
function htmlPqrsRespuestaRegistrada(e){
  if(!pqrsEstaCerrada(e))return'';
  if(e._pqrs_informativa){
    const wf=typeof getPqrsWorkflow==='function'?getPqrsWorkflow(e):{};
    const desc=String(wf.cuerpo||e._pqrs_respuesta_nota||'').trim();
    return '<div class="pqrs-det-sec"><div class="pqrs-det-k">Respuesta</div><div class="pqrs-det-v" style="color:var(--gn);font-weight:600">ℹ Informativa — atendida sin respuesta formal al ciudadano</div>'+
      (desc?'<div style="margin-top:6px;font-size:13px;white-space:pre-wrap">'+escAttr(desc)+'</div>':'')+'</div>';
  }
  const respNota=(e._pqrs_historial||[]).filter(h=>h.tipo==='respuesta_oficina').pop();
  const enTerm=pqrsRespuestaEnTermino(e);
  let h='<div class="pqrs-det-sec"><div class="pqrs-det-k">Respuesta</div><div class="pqrs-det-v" style="color:'+(enTerm?'var(--gn)':'var(--or)')+';font-weight:600">✓ '+(enTerm?'Atendida en término':'Atendido extemporáneo')+(respNota&&respNota.fecha?' · '+fmtF(e._pqrs_respuesta_fecha||respNota.fecha):'')+'</div>';
  if(e._pqrs_respuesta_oficio)h+='<div style="margin-top:4px;font-size:12px"><strong>Oficio:</strong> '+escAttr(e._pqrs_respuesta_oficio)+'</div>';
  if(e._pqrs_respuesta_medio)h+='<div style="margin-top:4px;font-size:12px"><strong>Notificación:</strong> '+escAttr(medioNotificacionRespLabel(e._pqrs_respuesta_medio))+'</div>';
  if(e._pqrs_respuesta_nota)h+='<div style="margin-top:6px;font-size:13px">'+escAttr(e._pqrs_respuesta_nota)+'</div>';
  // Ciudadano / público: solo documentos definitivos (no versiones por corregir ni en firma)
  const soportesPub=(e._pqrs_respuesta_soportes||[]).filter(function(s){
    return _pqrsDocEsVisibleCiudadano(s,e,{tipo:'respuesta'});
  });
  const linkPub=e._pqrs_respuesta_link&&!_pqrsDocEsBorradorInterno({url:e._pqrs_respuesta_link,label:'',driveEstado:''})&&!esUrlCarpetaDrive(e._pqrs_respuesta_link)
    ?e._pqrs_respuesta_link:'';
  if(soportesPub.length){
    soportesPub.forEach(function(s){
      if(s.url||s.preview)h+='<div style="margin-top:4px"><button type="button" class="btn bsm" onclick="openPqrsDocViewer(\''+escAttr(s.preview||s.url)+'\',\''+escAttr(s.label||'Adjunto')+'\')">📄 '+escAttr(String(s.label||'Adjunto').replace(/\s*·\s*(por corregir|entrega v\d+)/ig,'').trim()||'Adjunto')+'</button></div>';
    });
  }else if(linkPub){
    h+='<div style="margin-top:6px"><button type="button" class="btn bsm" onclick="openPqrsDocViewer(\''+escAttr(linkPub)+'\',\'Respuesta PQRSD\')">📎 Ver respuesta</button></div>';
  }
  return h+'</div>';
}
function abrirVisorAdjunto(urlView,nombreArchivo){
  let ov=document.getElementById('adj-viewer-ov');
  if(!ov){
    ov=document.createElement('div');
    ov.id='adj-viewer-ov';
    ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.72);display:flex;align-items:center;justify-content:center';
    ov.onclick=function(ev){if(ev.target===ov){resetOverlayElevation(ov);ov.remove();}};
    document.body.appendChild(ov);
  }
  elevateOverlayAboveModals(ov);
  const isBlob=String(urlView||'').startsWith('blob:');
  const previewUrl=isBlob?String(urlView||''):String(urlView||'').replace(/\/view(\?.*)?$/,'/preview');
  const driveView=String(urlView||'').replace(/\/preview(\?.*)?$/,'/view');
  const extraLink=isBlob
    ?'<a href="'+escAttr(String(urlView||''))+'" download="'+escAttr(nombreArchivo||'adjunto')+'" style="font-size:12px;color:var(--bl,#185fa5);white-space:nowrap;text-decoration:none;margin-right:8px">⬇ Descargar</a>'
    :'<button type="button" class="btn bsm" style="font-size:12px;padding:2px 8px;margin-right:8px" onclick="openDriveVentanaEmergente(\''+escAttr(driveView)+'\')">↗ Abrir en ventana</button>'+
      '<button type="button" class="btn bsm" style="font-size:12px;padding:2px 8px;margin-right:8px;color:#1a7a4a" onclick="openDriveVentanaEmergente(\''+escAttr(driveView)+'\')" title="En Drive puede seleccionar párrafos y dejar comentarios visibles para los responsables">💬 Comentar en Drive</button>';
  ov.innerHTML=
    '<div style="background:var(--sf,#fff);border-radius:10px;box-shadow:0 8px 40px rgba(0,0,0,.45);display:flex;flex-direction:column;width:min(900px,96vw);height:min(720px,90vh);overflow:hidden">'+
    '<div style="padding:10px 14px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--bd,#e2e8f0);gap:8px">'+
    '<span style="font-size:13px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1">'+escAttr(nombreArchivo||'Adjunto')+'</span>'+
    extraLink+
    '<button type="button" onclick="(function(){var o=document.getElementById(\'adj-viewer-ov\');if(o){if(typeof resetOverlayElevation===\'function\')resetOverlayElevation(o);o.remove();}})()" style="background:none;border:none;cursor:pointer;font-size:18px;line-height:1;padding:2px 6px;color:var(--tx2,#666)" title="Cerrar">✕</button>'+
    '</div>'+
    (isBlob?'':'')+
    '<iframe src="'+escAttr(previewUrl)+'" style="flex:1;width:100%;border:none" allowfullscreen></iframe>'+
    '</div>';
  ov.style.display='flex';
}
function htmlPqrsCorreoOrigenHtml(e){
  const d=e&&e._gmail_email_data;
  if(!d||typeof d!=='object')return'';
  const driveAtts=Array.isArray(e._pqrs_gmail_attachments)?e._pqrs_gmail_attachments:[];
  const adjInfo=Array.isArray(d.adjuntosInfo)?d.adjuntosInfo:[];
  let attsHtml='';
  let hayAnexoSinLink=false;
  if(adjInfo.length){
    attsHtml=adjInfo.map(function(a,i){
      // Solo enlazar si existe una subida a Drive que coincide por NOMBRE con el anexo.
      // (Ya no se suben los anexos originales al Drive: el fallback posicional apuntaba
      //  por error al PDF de soporte. Los originales están en el correo reenviado.)
      const drv=driveAtts.find(x=>x&&x.nombre===a.nombre&&x.driveLink)||null;
      const ico=(a.mimeType||'').startsWith('image/')?'🖼️':(a.mimeType||'').includes('pdf')?'📄':(a.mimeType||'').includes('word')||(a.nombre||'').match(/\.docx?$/i)?'📝':(a.mimeType||'').includes('sheet')||(a.mimeType||'').includes('excel')||(a.nombre||'').match(/\.xlsx?$/i)?'📊':'📎';
      if(drv&&drv.driveLink){
        const onclick='event.stopPropagation();abrirVisorAdjunto(\''+jsStr(drv.driveLink)+'\',\''+jsStr(a.nombre||'Adjunto')+'\');return false;';
        return'<a href="'+escAttr(drv.driveLink)+'" class="gmail-att-chip" style="text-decoration:none" onclick="'+escAttr(onclick)+'" title="Ver '+escAttr(a.nombre||'adjunto')+'"><span class="att-ico">'+ico+'</span><span class="att-name">'+escAttr(a.nombre||'Adjunto')+'</span></a>';
      }
      hayAnexoSinLink=true;
      return'<span class="gmail-att-chip" style="opacity:.85" title="Este anexo está en el correo reenviado a su oficina"><span class="att-ico">'+ico+'</span><span class="att-name">'+escAttr(a.nombre||'Adjunto')+'</span></span>';
    }).join('');
  }
  const notaAnexos=hayAnexoSinLink
    ?'<div style="font-size:11px;color:var(--tx2);margin-bottom:8px;display:flex;gap:5px;align-items:flex-start"><span>📥</span><span>Los anexos originales se conservan en el <strong>correo reenviado a su oficina</strong> (revise su bandeja de Gmail). El PDF de soporte está en «Documento de la solicitud».</span></div>'
    :'';
  const bodyHtml=d.cuerpoHtml||(d.cuerpoTxt?'<pre style="white-space:pre-wrap;font-size:12px;margin:0">'+escAttr(d.cuerpoTxt)+'</pre>':'');
  const fechaStr=d.fecha?' · '+escAttr(d.fecha):'';
  return'<details class="pqrs-email-origen"><summary>📧 Correo de origen <span style="font-weight:400;color:var(--tx3)">(clic para ver)</span></summary>'+
    '<div style="padding:8px 0 4px">'+
    (d.remitente||d.fecha?'<div style="font-size:11px;color:var(--tx2);margin-bottom:3px">De: <strong>'+escAttr(d.remitente||'')+fechaStr+'</strong></div>':'')  +
    (d.asunto?'<div style="font-size:12px;font-weight:600;margin-bottom:6px">'+escAttr(d.asunto)+'</div>':'')+
    (attsHtml?'<div class="gmail-att-chips" style="margin-bottom:8px;display:flex;flex-wrap:wrap;gap:4px">'+attsHtml+'</div>':'')+
    notaAnexos+
    (bodyHtml?'<div class="pqrs-email-body">'+bodyHtml+'</div>':'')+
    '</div></details>';
}
