// agendaNorm → js/utils.js
function getAgendaResponsableActivo(){
  if(esModoResponsable())return String(responsableActivo||'').trim();
  if(esVistaActividadesDepto())return String(getEncargadoDepto(deptoActivo)||'').trim();
  return String(responsableActivo||getEncargadoDepto(deptoActivo)||'').trim();
}
function getAgendaEventoById(id){
  const local=(agendaEventos||[]).find(x=>x.id===id);
  if(local)return local;
  return (window._agendaGcalEvents||[]).find(x=>x.id===id)||null;
}
function puedeEditarAgendaEvento(ev){
  ev=normalizeAgendaEvento(ev);
  if(ev.tipo==='gcal')return false;
  const resp=getAgendaResponsableActivo();
  if(esModoResponsable()){
    const r=String(responsableActivo||'').trim();
    if(!r||agendaNorm(ev.responsable)!==agendaNorm(r))return false;
    if(ev.tipo==='asignado')return false;
    return ev.tipo==='personal';
  }
  if(resp&&agendaNorm(ev.responsable)===agendaNorm(resp))return true;
  if(ev.tipo==='asignado'&&esVistaActividadesDepto()){
    return agendaNorm(ev.creadoPor)===agendaNorm(getEncargadoDepto(deptoActivo));
  }
  const autor=taskComentarioAutor();
  if(ev.creadoPor&&autor&&agendaNorm(ev.creadoPor)===agendaNorm(autor))return true;
  return false;
}
function puedeEliminarAgendaEvento(ev){
  ev=normalizeAgendaEvento(ev);
  if(ev.tipo==='gcal')return false;
  if(esModoResponsable()){
    const r=String(responsableActivo||'').trim();
    if(!r||agendaNorm(ev.responsable)!==agendaNorm(r))return false;
    return ev.tipo==='personal';
  }
  return puedeEditarAgendaEvento(ev);
}
function agendaUiPrefix(){
  if(window._agendaRenderTarget==='modal')return'agenda-cal-modal-';
  if(window._agendaRenderTarget==='dock')return'act-agenda-dock-';
  return'agenda-';
}
function agendaEl(id){return document.getElementById(agendaUiPrefix()+id);}
function agendaIsModalOpen(){const ov=document.getElementById('agenda-cal-overlay');return !!(ov&&ov.classList.contains('on'));}
function agendaIsDockOpen(){
  const cal=document.getElementById('act-agenda-cal-panel');
  return !!(cal&&!cal.hidden);
}
function agendaShouldPaint(){
  if(window._agendaRenderTarget==='modal')return agendaIsModalOpen();
  if(window._agendaRenderTarget==='dock')return agendaIsDockOpen();
  const pg=document.getElementById('pg-agenda');
  return !!(pg&&pg.classList.contains('on'));
}
function agendaDrawerEls(){
  if(window._agendaRenderTarget==='modal'){
    return{tit:document.getElementById('agenda-cal-modal-drawer-tit'),body:document.getElementById('agenda-cal-modal-drawer-body'),wrap:document.getElementById('agenda-cal-modal-drawer')};
  }
  if(window._agendaRenderTarget==='dock'){
  return{tit:document.getElementById('act-agenda-dock-drawer-tit'),body:document.getElementById('act-agenda-dock-drawer-body'),wrap:document.getElementById('act-agenda-dock-drawer')};
  }
  return{tit:document.getElementById('agenda-drawer-tit'),body:document.getElementById('agenda-drawer-body'),wrap:document.getElementById('agenda-drawer')};
}
function syncActAgendaPanelLeftOffset(){
  const nav=document.getElementById('sst-nav');
  const dock=document.getElementById('act-agenda-dock');
  const navW=nav?(nav.offsetWidth||56):56;
  if(!dock)return;
  if(dock.classList.contains('act-agenda-dock-left'))dock.style.left=navW+'px';
  else if(dock.classList.contains('act-agenda-dock-right')&&dock.classList.contains('act-agenda-dock-with-cal'))dock.style.left=navW+'px';
}
function updateActAgendaCalToggleUi(show){
  show=!!(show!=null?show:window._actAgendaShowCal);
  const dock=document.getElementById('act-agenda-dock');
  const fromRight=!!(dock&&dock.classList.contains('act-agenda-dock-right'));
  const ico=document.getElementById('act-agenda-cal-toggle-ico');
  const btn=document.getElementById('act-agenda-cal-toggle');
  // Izquierda: › expandir / ‹ contraer · Derecha (espejo): ‹ expandir / › contraer
  if(ico)ico.textContent=fromRight?(show?'›':'‹'):(show?'‹':'›');
  if(btn){
    btn.title=show?'Contraer calendario':'Expandir calendario';
    btn.setAttribute('aria-label',btn.title);
    btn.classList.toggle('on',show);
  }
}
function applyActAgendaDockSide(side,showCal,opts){
  opts=opts||{};
  const dock=document.getElementById('act-agenda-dock');
  const toggle=document.getElementById('act-agenda-cal-toggle');
  if(!dock)return;
  const wasOn=opts.keepOn&&dock.classList.contains('on');
  dock.classList.remove('act-agenda-dock-left','act-agenda-dock-right','act-agenda-dock-tasks-only','act-agenda-dock-with-cal','act-agenda-closing');
  if(!opts.keepOn)dock.classList.remove('on');
  dock.style.width='';
  dock.style.right='';
  dock.style.left='';
  if(side==='left'){
    dock.classList.add('act-agenda-dock-left');
    if(showCal){
      dock.classList.add('act-agenda-dock-with-cal');
      dock.style.right='0';
    }else{
      dock.style.right='auto';
    }
    syncActAgendaPanelLeftOffset();
  }else{
    dock.classList.add('act-agenda-dock-right');
    dock.style.right='0';
    if(showCal){
      dock.classList.add('act-agenda-dock-with-cal');
      syncActAgendaPanelLeftOffset();
    }else{
      dock.style.left='auto';
    }
  }
  if(toggle)toggle.style.display='';
  if(wasOn)dock.classList.add('on');
  updateActAgendaCalToggleUi(!!showCal);
}
function syncActAgendaCalPane(show){
  const cal=document.getElementById('act-agenda-cal-panel');
  const dock=document.getElementById('act-agenda-dock');
  const btnCal=document.getElementById('btn-tasks-calendario');
  const on=!!show;
  if(btnCal)btnCal.style.display='none';
  if(cal)cal.hidden=!on;
  if(dock&&(dock.classList.contains('act-agenda-dock-left')||dock.classList.contains('act-agenda-dock-right'))){
    dock.classList.toggle('act-agenda-dock-with-cal',on);
    if(dock.classList.contains('act-agenda-dock-left')){
      if(on){dock.style.width='';dock.style.right='0';}
      else{dock.style.width='';dock.style.right='auto';}
      syncActAgendaPanelLeftOffset();
    }else if(dock.classList.contains('act-agenda-dock-right')){
      dock.style.right='0';
      if(on){dock.style.width='';syncActAgendaPanelLeftOffset();}
      else{dock.style.width='';dock.style.left='auto';}
    }
  }
  if(on){
    window._agendaRenderTarget='dock';
    if(!window._agendaMes)window._agendaMes=new Date();
    if(!window._agendaDiaSel)window._agendaDiaSel=window._actAgendaDiaSel||hoy();
    if(!window._agendaVista||window._agendaVista==='dia')window._agendaVista='mes';
    agendaCerrarDrawer();
    if(typeof renderAgenda==='function')renderAgenda();
  }else if(window._agendaRenderTarget==='dock'){
    window._agendaRenderTarget='page';
  }
  updateActAgendaCalToggleUi(on);
}
function toggleActAgendaCalDock(){
  const dock=document.getElementById('act-agenda-dock');
  if(!dock||!dock.classList.contains('on'))return;
  const side=dock.classList.contains('act-agenda-dock-right')?'right'
    :(dock.classList.contains('act-agenda-dock-left')?'left':null);
  if(!side)return;
  const show=!window._actAgendaShowCal;
  window._actAgendaShowCal=show;
  try{localStorage.setItem('sstTasksCalOpen',show?'1':'0');}catch(e){}
  syncActAgendaCalPane(show);
  applyActAgendaDockSide(side,show,{keepOn:true});
}
function applyActAgendaPanelSide(side){
  applyActAgendaDockSide(side,!!window._actAgendaShowCal);
}
function openAgendaCalModal(){if(!puedeVerTabAgenda()){notif('Tasks está disponible en modo Responsables o como encargado del departamento','err');return;}const resp=getAgendaResponsableActivo();if(!resp){notif(esModoResponsable()?'Seleccione su nombre como responsable':'Seleccione encargado del departamento','err');return;}window._agendaRenderTarget='modal';if(!window._agendaMes)window._agendaMes=new Date();if(!window._agendaDiaSel)window._agendaDiaSel=hoy();if(!window._agendaVista||window._agendaVista==='dia')window._agendaVista='mes';const ov=document.getElementById('agenda-cal-overlay');if(ov)ov.classList.add('on');agendaCerrarDrawer();renderAgenda();}
function cerrarAgendaCalModal(){const ov=document.getElementById('agenda-cal-overlay');if(ov)ov.classList.remove('on');window._agendaRenderTarget='page';agendaCerrarDrawer();}
function getAgendaPrintCss(){
  return '@page{size:A4;margin:12mm 10mm}*{box-sizing:border-box}body{font-family:Segoe UI,Calibri,Arial,sans-serif;font-size:10pt;color:#1a1a1a;line-height:1.4;margin:0;padding:0;background:#fff}.print-doc{width:100%}.print-hdr{border-bottom:2px solid #1a4a2e;padding-bottom:8px;margin-bottom:16px}.print-hdr h1{font-size:17pt;font-weight:700;margin:0 0 3px;color:#1a4a2e}.print-meta{font-size:9pt;color:#555;margin:0}.print-section{margin-bottom:20px;page-break-inside:avoid}.print-section-hdr{font-size:12pt;font-weight:700;color:#1a4a2e;margin:0 0 8px;padding-bottom:3px;border-bottom:1px solid #bbb}.print-legend{display:flex;flex-wrap:wrap;gap:8px 14px;font-size:8pt;color:#444;margin:0 0 8px}.print-leg{display:inline-flex;align-items:center;gap:4px}.print-leg-dot{width:9px;height:9px;border-radius:2px;display:inline-block;border:1px solid rgba(0,0,0,.12)}.print-leg-dot.pers{background:#deeaf8}.print-leg-dot.asig{background:#f0eafa}.print-leg-dot.act{background:#fdecd8}.print-leg-dot.gcal{background:#e8f0fe}.print-task-group{margin-bottom:12px;page-break-inside:avoid}.print-task-group-hdr{font-size:10.5pt;font-weight:700;margin:0 0 6px;padding-left:8px;border-left:4px solid #1a4a2e}.print-cnt{font-weight:500;color:#666;font-size:9pt}.print-empty,.print-empty-cell{color:#888;font-size:9pt;font-style:italic}.print-task-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-bottom:4px}.print-task-tbl th,.print-task-tbl td{border:1px solid #ccc;padding:5px 7px;text-align:left;vertical-align:top}.print-task-tbl th{background:#eef2ee;color:#1a4a2e;font-size:8.5pt;text-transform:uppercase;letter-spacing:.03em}.print-task-tbl .print-date{white-space:nowrap;width:88px;color:#333}.print-task-tbl .print-notes{color:#555;font-size:9pt}.print-cal-month,.print-cal-week{width:100%;border-collapse:collapse;table-layout:fixed;font-size:8.5pt}.print-cal-month th,.print-cal-week th{background:#eef2ee;color:#1a4a2e;font-weight:700;text-align:center;padding:5px 3px;border:1px solid #aaa;font-size:8pt}.print-cal-month td,.print-cal-week td{border:1px solid #bbb;vertical-align:top;padding:3px 4px;height:78px;width:14.28%}.print-cal-week td{height:120px}.print-day.other{background:#f7f7f5;color:#999}.print-day.today,.print-week-cell.today,.print-cal-week th.today{background:#f0f7ff}.print-day-num{font-weight:700;font-size:9pt;margin-bottom:3px;color:#222}.print-day.other .print-day-num{color:#aaa}.print-week-daynum{font-size:11pt;font-weight:700;display:block;margin-top:2px}.print-day-evs{list-style:none;margin:0;padding:0}.print-ev{margin:0 0 2px;padding:2px 3px;border-radius:2px;font-size:7.5pt;line-height:1.25;word-break:break-word;background:#eef4fb;color:#0c447c}.print-ev.asig{background:#f3ecfb;color:#5b21b6}.print-ev.act{background:#fef3e6;color:#9a3412}.print-ev.gcal{background:#e8f0fe;color:#1a56db}.print-ev-time{font-weight:700;margin-right:2px}.print-ev-more{font-size:7pt;color:#888;font-style:italic;padding:1px 3px}.print-section-week{page-break-before:auto}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}.print-section{page-break-inside:avoid}}';
}
function agendaPrintTipoClass(ev){
  if(ev.tipo==='asignado')return 'asig';
  if(ev.tipo==='desde_actividad')return 'act';
  if(ev.tipo==='gcal')return 'gcal';
  return 'pers';
}
function renderAgendaPrintLegend(){
  return '<span class="print-leg"><i class="print-leg-dot pers"></i>Personal</span>'+
    '<span class="print-leg"><i class="print-leg-dot act"></i>Actividad</span>'+
    '<span class="print-leg"><i class="print-leg-dot asig"></i>Asignado</span>'+
    '<span class="print-leg"><i class="print-leg-dot gcal"></i>Gmail</span>';
}
function renderAgendaPrintMonthTable(eventos,mesRef){
  const y=mesRef.getFullYear(),mo=mesRef.getMonth();
  const first=new Date(y,mo,1);
  const start=new Date(y,mo,1-(first.getDay()+6)%7);
  const hdrs=['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];
  const todayStr=hoy();
  let h='<table class="print-cal-month"><thead><tr>';
  hdrs.forEach(x=>{h+='<th>'+x+'</th>';});
  h+='</tr></thead><tbody>';
  for(let w=0;w<6;w++){
    h+='<tr>';
    for(let d=0;d<7;d++){
      const i=w*7+d;
      const dt=new Date(start);dt.setDate(start.getDate()+i);
      const fs=dt.toISOString().slice(0,10);
      const inMonth=dt.getMonth()===mo;
      const dayEv=eventos.filter(ev=>(ev.fecha||'').slice(0,10)===fs).sort((a,b)=>(a.hora||'').localeCompare(b.hora||''));
      let cls='print-day';
      if(!inMonth)cls+=' other';
      if(fs===todayStr)cls+=' today';
      h+='<td class="'+cls+'"><div class="print-day-num">'+dt.getDate()+'</div>';
      if(dayEv.length){
        h+='<ul class="print-day-evs">';
        dayEv.slice(0,4).forEach(ev=>{
          h+='<li class="print-ev '+agendaPrintTipoClass(ev)+'">';
          if(ev.hora)h+='<span class="print-ev-time">'+escAttr(ev.hora)+'</span> ';
          h+=escAttr(ev.titulo||'')+'</li>';
        });
        if(dayEv.length>4)h+='<li class="print-ev-more">+'+(dayEv.length-4)+' más</li>';
        h+='</ul>';
      }
      h+='</td>';
    }
    h+='</tr>';
  }
  return h+'</tbody></table>';
}
function renderAgendaPrintWeekTable(eventos,mesRef,diaSel){
  const start=agendaSemanaInicio(mesRef,diaSel);
  const hdrs=['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];
  const todayStr=hoy();
  let h='<table class="print-cal-week"><thead><tr>';
  for(let i=0;i<7;i++){
    const d=new Date(start);d.setDate(start.getDate()+i);
    const fs=d.toISOString().slice(0,10);
    h+='<th class="'+(fs===todayStr?' today':'')+'">'+hdrs[i]+'<span class="print-week-daynum">'+d.getDate()+'</span></th>';
  }
  h+='</tr></thead><tbody><tr>';
  for(let i=0;i<7;i++){
    const d=new Date(start);d.setDate(start.getDate()+i);
    const fs=d.toISOString().slice(0,10);
    const dayEv=eventos.filter(ev=>(ev.fecha||'').slice(0,10)===fs).sort((a,b)=>(a.hora||'99:99').localeCompare(b.hora||'99:99'));
    h+='<td class="print-week-cell'+(fs===todayStr?' today':'')+'">';
    if(!dayEv.length)h+='<span class="print-empty-cell">Sin eventos</span>';
    else{
      h+='<ul class="print-day-evs">';
      dayEv.forEach(ev=>{
        h+='<li class="print-ev '+agendaPrintTipoClass(ev)+'">';
        if(ev.hora)h+='<span class="print-ev-time">'+escAttr(ev.hora)+'</span> ';
        h+=escAttr(ev.titulo||'')+'</li>';
      });
      h+='</ul>';
    }
    h+='</td>';
  }
  return h+'</tr></tbody></table>';
}
function renderPrintTaskSection(title,items,opts){
  opts=opts||{};
  const accent=opts.accent||'#1a4a2e';
  let h='<div class="print-task-group">';
  h+='<h3 class="print-task-group-hdr" style="border-left-color:'+accent+'">'+escAttr(title)+' <span class="print-cnt">('+items.length+')</span></h3>';
  if(!items.length)return h+'<p class="print-empty">Sin tareas en esta sección.</p></div>';
  h+='<table class="print-task-tbl"><thead><tr><th>Fecha</th><th>Tarea</th><th>Detalle</th></tr></thead><tbody>';
  items.forEach(ev=>{
    const det=String(ev.notas||'').trim()||String(ev.detalle||'').trim()||'—';
    h+='<tr><td class="print-date">'+escAttr(ev.fecha?fmtF(ev.fecha):'—')+'</td>';
    h+='<td><strong>'+escAttr(ev.titulo||'')+'</strong></td>';
    h+='<td class="print-notes">'+escAttr(det)+'</td></tr>';
  });
  return h+'</tbody></table></div>';
}
function buildMiDiaTasksPrintSection(resp){
  return '<section class="print-section"><h2 class="print-section-hdr">Mis tareas</h2>'+
    renderPrintTaskSection('Para hoy',getAgendaPlanesDelDia(resp,hoy()),{accent:'#185FA5'})+
    renderPrintTaskSection('Próximos',getAgendaPlanesProximos(resp),{accent:'#1a7a4a'})+
    renderPrintTaskSection('Vencidos',getAgendaPlanesVencidos(resp),{accent:'#a32d2d'})+
    '</section>';
}
function buildAgendaPrintHtml(resp){
  const mesRef=window._agendaMes||new Date();
  const diaSel=window._agendaDiaSel||hoy();
  const eventos=getAgendaEventosResponsable(resp).concat(Array.isArray(window._agendaGcalEvents)?window._agendaGcalEvents:[]);
  const now=new Date().toLocaleString('es-CO',{dateStyle:'long',timeStyle:'short'});
  const ws=agendaSemanaInicio(mesRef,diaSel);
  const we=new Date(ws);we.setDate(ws.getDate()+6);
  const weekStr=fmtF(ws.toISOString().slice(0,10))+' — '+fmtF(we.toISOString().slice(0,10));
  return '<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Agenda · '+escAttr(resp)+'</title><style>'+getAgendaPrintCss()+'</style></head><body>'+
    '<div class="print-doc">'+
    '<header class="print-hdr"><h1>Agenda · '+escAttr(resp)+'</h1><p class="print-meta">CDA Guaviare · Sistema de Trazabilidad · Impreso '+escAttr(now)+'</p></header>'+
    buildMiDiaTasksPrintSection(resp)+
    '<section class="print-section"><h2 class="print-section-hdr">Calendario mensual · '+escAttr(agendaMesLabel(mesRef))+'</h2>'+
    '<div class="print-legend">'+renderAgendaPrintLegend()+'</div>'+
    renderAgendaPrintMonthTable(eventos,mesRef)+
    '</section>'+
    '<section class="print-section print-section-week"><h2 class="print-section-hdr">Vista semanal · '+escAttr(weekStr)+'</h2>'+
    '<div class="print-legend">'+renderAgendaPrintLegend()+'</div>'+
    renderAgendaPrintWeekTable(eventos,mesRef,diaSel)+
    '</section>'+
    '</div></body></html>';
}
function imprimirAgendaPanorama(){
  const resp=getAgendaResponsableActivo();
  if(!resp){notif('Seleccione responsable','err');return;}
  const html=buildAgendaPrintHtml(resp);
  const w=window.open('','_blank');
  if(!w){notif('Permita ventanas emergentes para imprimir','err');return;}
  w.document.open();
  w.document.write(html);
  w.document.close();
  w.focus();
  setTimeout(function(){try{w.print();}catch(e){}},600);
}
function imprimirMiAgendaCompleta(){imprimirAgendaPanorama();}
function agendaSelEvento(id){
  window._agendaSelEvId=id;
  const ev=getAgendaEventoById(id);
  if(ev&&ev.fecha)window._agendaDiaSel=(ev.fecha||'').slice(0,10);
  renderAgenda();
  if(ev)agendaMostrarDrawerEvento(ev);
}
function agendaCerrarDrawer(){
  window._agendaSelEvId=null;
  window._agendaDrawerMode=null;
  const dr=agendaDrawerEls();
  if(dr.tit)dr.tit.textContent='Evento';
  const hint=window._agendaRenderTarget==='modal'?'Seleccione un evento del calendario.':'Seleccione un evento del calendario o pulse «+ Evento personal».';
  if(dr.body)dr.body.innerHTML='<div style="font-size:12px;color:var(--tx3)">'+hint+'</div>';
  renderAgenda();
}
function agendaFormHtml(ev,prefill){
  prefill=prefill||{};
  ev=ev||{};
  const titulo=ev.titulo!=null?ev.titulo:(prefill.titulo||'');
  const detalle=ev.detalle!=null?ev.detalle:(prefill.detalle||'');
  const fecha=(ev.fecha||prefill.fecha||window._agendaDiaSel||hoy()).slice(0,10);
  const hora=ev.hora!=null?ev.hora:(prefill.hora||'');
  const canGcal=typeof gmailIsTokenValid==='function'&&gmailIsTokenValid()&&typeof gmailHasCalendarScope==='function'&&gmailHasCalendarScope()&&!window._gmailCalendarDenied;
  const gcalChk=(!ev.id&&canGcal)
    ?('<label style="display:flex;align-items:center;gap:6px;font-size:12px;margin-bottom:8px"><input type="checkbox" id="agenda-f-gcal" checked> También crear en Google Calendar</label>')
    :'';
  return '<div class="fld" style="margin-bottom:8px"><label>Título</label><input type="text" id="agenda-f-titulo" value="'+escAttr(titulo)+'" style="width:100%;padding:8px;border:1px solid var(--bd);border-radius:var(--r)"></div>'+
    '<div class="fld" style="margin-bottom:8px"><label>Detalle (opcional)</label><textarea id="agenda-f-detalle" style="width:100%;min-height:64px;padding:8px;border:1px solid var(--bd);border-radius:var(--r);font-family:\'DM Sans\',sans-serif">'+escAttr(detalle)+'</textarea></div>'+
    '<div class="fg" style="margin-bottom:8px"><div class="fld"><label>Fecha</label><input type="date" id="agenda-f-fecha" value="'+escAttr(fecha)+'" style="width:100%;padding:8px;border:1px solid var(--bd);border-radius:var(--r)"></div>'+
    '<div class="fld"><label>Hora (opcional)</label><input type="time" id="agenda-f-hora" value="'+escAttr(hora)+'" style="width:100%;padding:8px;border:1px solid var(--bd);border-radius:var(--r)"></div></div>'+
    gcalChk;
}
function agendaMostrarDrawerCrear(prefill){
  prefill=prefill||{};
  const resp=getAgendaResponsableActivo();
  if(!resp){notif('Seleccione responsable','err');return;}
  window._agendaDrawerMode='create';
  window._agendaSelEvId=null;
  window._agendaPrefillTask=prefill.taskRef||null;
  const dr=agendaDrawerEls();
  const tit=dr.tit;
  const body=dr.body;
  if(tit)tit.textContent='Nuevo evento';
  if(body)body.innerHTML='<div style="font-size:12px;color:var(--tx2);margin-bottom:10px">Para: <strong>'+escAttr(resp)+'</strong></div>'+
    agendaFormHtml(null,prefill)+
    '<div class="fx" style="gap:8px;margin-top:8px"><button type="button" class="btn bsm bp" onclick="agendaGuardarForm()">Guardar</button><button type="button" class="btn bsm" onclick="agendaCerrarDrawer()">Cancelar</button></div>';
  setTimeout(()=>{const inp=document.getElementById('agenda-f-titulo');if(inp)inp.focus();},60);
}
function agendaMostrarDrawerEditar(ev){
  ev=normalizeAgendaEvento(ev);
  if(!puedeEditarAgendaEvento(ev)){notif('No puede editar este evento','err');return;}
  window._agendaDrawerMode='edit';
  window._agendaSelEvId=ev.id;
  const dr=agendaDrawerEls();
  const tit=dr.tit;
  const body=dr.body;
  const batchChk=ev.tipo==='asignado'&&ev.batch?'<label style="display:flex;align-items:center;gap:6px;font-size:12px;margin-bottom:8px"><input type="checkbox" id="agenda-f-batch" checked> Aplicar a todos los responsables del envío</label>':'';
  if(tit)tit.textContent='Editar evento';
  if(body)body.innerHTML=(ev.tipo==='asignado'?'<div style="font-size:11px;color:var(--tx2);margin-bottom:8px">Responsable: '+escAttr(ev.responsable)+'</div>':'')+
    agendaFormHtml(ev)+batchChk+
    '<div class="fx" style="gap:8px;margin-top:8px"><button type="button" class="btn bsm bp" onclick="agendaGuardarForm()">Guardar cambios</button>'+
    (puedeEliminarAgendaEvento(ev)?'<button type="button" class="btn bsm bd2" onclick="agendaEliminarSel()">Eliminar</button>':'')+
    '<button type="button" class="btn bsm" onclick="agendaMostrarDrawerEvento(getAgendaEventoById(\''+escAttr(ev.id)+'\'))">Cancelar</button></div>';
}
function agendaMostrarDrawerEvento(ev){
  ev=normalizeAgendaEvento(ev);
  window._agendaSelEvId=ev.id;
  window._agendaDrawerMode='view';
  const dr=agendaDrawerEls();
  const tit=dr.tit;
  const body=dr.body;
  let tag='<span class="bdg" style="background:var(--bll);color:var(--bl);font-size:10px">Personal</span>';
  if(ev.tipo==='asignado')tag='<span class="bdg" style="background:var(--pul);color:var(--pu);font-size:10px">Asignado</span>';
  else if(ev.tipo==='desde_actividad')tag='<span class="bdg" style="background:var(--orl);color:var(--or);font-size:10px">Desde actividad</span>';
  else if(ev.tipo==='gcal')tag='<span class="bdg" style="background:#e8f0fe;color:#1a73e8;font-size:10px">Gmail</span>';
  const canEdit=ev.tipo!=='gcal'&&puedeEditarAgendaEvento(ev);
  const canDel=ev.tipo!=='gcal'&&puedeEliminarAgendaEvento(ev);
  if(tit)tit.textContent=ev.titulo||'Evento';
  if(body)body.innerHTML=tag+
    '<div style="font-size:13px;font-weight:600;margin:.5rem 0">'+escAttr(ev.titulo)+'</div>'+
    '<div style="font-size:12px;color:var(--tx2);margin-bottom:6px">📅 '+fmtF(ev.fecha)+(ev.hora?' · 🕐 '+escAttr(ev.hora):'')+'</div>'+
    (ev.detalle?'<div style="font-size:12px;margin-bottom:8px;white-space:pre-wrap">'+escAttr(ev.detalle)+'</div>':'')+
    (ev.creadoPor&&ev.tipo!=='gcal'?'<div style="font-size:10px;color:var(--tx3);margin-bottom:8px">Creado por: '+escAttr(ev.creadoPor)+'</div>':'')+
    (ev.taskRef&&ev.taskRef.taskId?'<button type="button" class="btn bsm" style="margin-bottom:8px" onclick="openTaskCommentsModal(\''+escAttr(ev.taskRef.expId||ev.taskRef.exp||'')+'\',\''+escAttr(ev.taskRef.taskId)+'\')">Ver actividad vinculada</button>':'')+
    '<div class="fx" style="gap:8px;flex-wrap:wrap">'+
    (ev.tipo==='gcal'&&ev.htmlLink?'<a class="btn bsm bp" href="'+escAttr(ev.htmlLink)+'" target="_blank" rel="noopener">Abrir en Google Calendar</a>':'')+
    (canEdit?'<button type="button" class="btn bsm bp" onclick="agendaMostrarDrawerEditar(getAgendaEventoById(\''+escAttr(ev.id)+'\'))">✏️ Editar</button>':'')+
    (canDel?'<button type="button" class="btn bsm bd2" onclick="agendaEliminarSel()">Eliminar</button>':'')+
    '</div>';
}
function agendaLeerForm(){
  return{
    titulo:(document.getElementById('agenda-f-titulo')||{}).value,
    detalle:(document.getElementById('agenda-f-detalle')||{}).value,
    fecha:(document.getElementById('agenda-f-fecha')||{}).value,
    hora:(document.getElementById('agenda-f-hora')||{}).value
  };
}
function agendaGuardarForm(){
  const f=agendaLeerForm();
  const mode=window._agendaDrawerMode;
  if(mode==='edit'&&window._agendaSelEvId){
    const batchEl=document.getElementById('agenda-f-batch');
    if(actualizarAgendaEvento(window._agendaSelEvId,{...f,aplicarBatch:!!(batchEl&&batchEl.checked)})){
      notif('Evento actualizado','ok');
      const ev=getAgendaEventoById(window._agendaSelEvId);
      if(ev)agendaMostrarDrawerEvento(ev);
    }
    return;
  }
  const resp=getAgendaResponsableActivo();
  const tipo=window._agendaPrefillTask?'desde_actividad':'personal';
  const ev=crearAgendaEvento({...f,responsable:resp,tipo,taskRef:window._agendaPrefillTask||null,depto:esModoResponsable()?'responsables':deptoActivo});
  if(ev){
    window._agendaPrefillTask=null;
    window._agendaDiaSel=(f.fecha||'').slice(0,10);
    notif('Evento guardado','ok');
    agendaMostrarDrawerEvento(ev);
  }
}
function agendaEliminarSel(){
  const id=window._agendaSelEvId;
  if(!id)return;
  eliminarAgendaEvento(id);
  agendaCerrarDrawer();
}
function genAgendaId(){return 'ag_'+Date.now()+'_'+Math.random().toString(36).slice(2,6);}
/** Campos libres de organización personal (sin categorías fijas de acción). */
function normalizeAgendaEvento(ev){
  if(!ev)return ev;
  if(!ev.id)ev.id=genAgendaId();
  if(!ev.fecha)ev.fecha=hoy();
  if(!ev.tipo)ev.tipo='personal';
  if(ev.leido==null)ev.leido=ev.tipo==='asignado'?false:true;
  if(ev.orden==null||isNaN(+ev.orden))ev.orden=0;
  else ev.orden=+ev.orden;
  if(ev.criterio==null)ev.criterio='';
  if(ev.notas==null)ev.notas='';
  if(ev.hecho==null)ev.hecho=false;
  return ev;
}
function getTaskRefEstado(expId,taskId){
  const t=getTaskAny(expId,taskId);
  return t?estadoTask(t):'';
}
function agendaEventoVisible(ev){
  ev=normalizeAgendaEvento(ev);
  if(ev.taskRef&&ev.taskRef.taskId){
    const est=getTaskRefEstado(ev.taskRef.expId||ev.taskRef.exp, ev.taskRef.taskId);
    if(est==='Atendida')return false;
  }
  return true;
}
function getAgendaEventosResponsable(nombre,deptoId){
  const n=String(nombre||'').trim();
  if(!n)return [];
  const depto=deptoId||deptoActivo;
  const nNorm=agendaNorm(n);
  return (agendaEventos||[]).map(normalizeAgendaEvento).filter(ev=>{
    if(depto!=='responsables'&&ev.depto&&ev.depto!==depto&&ev.depto!=='responsables')return false;
    if(agendaNorm(ev.responsable)!==nNorm)return false;
    return agendaEventoVisible(ev);
  });
}
function marcarAgendaLeido(id){
  const ev=(agendaEventos||[]).find(x=>x.id===id);
  if(ev){ev.leido=true;saveLS();renderBandejaDepto();}
}
function crearAgendaEvento(data){
  const ev=normalizeAgendaEvento({
    id:genAgendaId(),
    titulo:String(data.titulo||'').trim(),
    detalle:String(data.detalle||'').trim(),
    fecha:data.fecha||hoy(),
    hora:String(data.hora||'').trim(),
    responsable:String(data.responsable||'').trim(),
    depto:data.depto||deptoActivo,
    creadoPor:data.creadoPor||getAgendaResponsableActivo()||taskComentarioAutor(),
    tipo:data.tipo||'personal',
    taskRef:data.taskRef||null,
    criterio:String(data.criterio||'').trim(),
    notas:String(data.notas||'').trim(),
    orden:data.orden!=null?+data.orden:Date.now(),
    leido:data.tipo==='asignado'?false:true,
    creado:new Date().toISOString()
  });
  if(!ev.titulo||!ev.responsable){notif('Indique título y responsable','err');return null;}
  agendaEventos.push(ev);
  saveLS();
  renderBandejaDepto();
  if(document.getElementById('pg-agenda').classList.contains('on'))renderAgenda();
  const syncGcal=data.syncGcal!==false&&(data.syncGcal===true||(document.getElementById('agenda-f-gcal')&&document.getElementById('agenda-f-gcal').checked));
  if(syncGcal&&(ev.tipo==='personal'||ev.tipo==='desde_actividad')&&typeof gmailCalendarCreateEvent==='function'&&typeof gmailHasCalendarScope==='function'&&gmailHasCalendarScope()&&typeof gmailIsTokenValid==='function'&&gmailIsTokenValid()){
    gmailCalendarCreateEvent(ev).then(function(gEv){
      if(gEv&&gEv.htmlLink){
        ev.gcalId=gEv.gcalId;
        ev.gcalHtmlLink=gEv.htmlLink;
        try{saveLS();}catch(e){}
        notif('También creado en Google Calendar','ok');
        window._agendaGcalCacheKey='';
        if(document.getElementById('pg-agenda')&&document.getElementById('pg-agenda').classList.contains('on'))renderAgenda();
      }
    }).catch(function(err){
      console.warn('GCal create:',err);
      if(err&&err.code==='NO_CALENDAR_SCOPE')return;
      notif('Evento SST guardado; no se pudo crear en Gmail Calendar','warn');
    });
  }
  return ev;
}
function crearAgendaEventosAsignados(data,nombres){
  const list=(nombres||[]).filter(Boolean);
  if(!list.length){notif('Seleccione al menos un responsable','err');return 0;}
  const batch='batch_'+Date.now();
  list.forEach(n=>{
    crearAgendaEvento({...data,responsable:n,tipo:'asignado',leido:false,batch});
  });
  notif('Evento enviado a '+list.length+' responsable(s) — aparecerá en su campanita','ok');
  return list.length;
}
function agendaMesDelta(d){
  const v=window._agendaVista||'mes';
  const m=window._agendaMes||new Date();
  if(v==='dia'){
    const ds=window._agendaDiaSel||hoy();
    const dd=new Date(ds+'T12:00:00');dd.setDate(dd.getDate()+d);
    window._agendaDiaSel=dd.toISOString().slice(0,10);
    window._agendaMes=new Date(dd.getFullYear(),dd.getMonth(),1);
  }else if(v==='semana'){
    const start=agendaSemanaInicio(m,window._agendaDiaSel);
    start.setDate(start.getDate()+d*7);
    window._agendaMes=new Date(start.getFullYear(),start.getMonth(),1);
    window._agendaDiaSel=start.toISOString().slice(0,10);
  }else{
    window._agendaMes=new Date(m.getFullYear(),m.getMonth()+d,1);
    window._agendaDiaSel=window._agendaMes.toISOString().slice(0,10);
  }
  renderAgenda();
}
function agendaNav(d){agendaMesDelta(d);}
function agendaSetVista(v){
  v=v||'mes';
  if((window._agendaRenderTarget==='modal'||window._agendaRenderTarget==='dock')&&v==='dia')v='mes';
  window._agendaVista=v;
  const pfx=agendaUiPrefix();
  const vs=(window._agendaRenderTarget==='modal'||window._agendaRenderTarget==='dock')?['mes','semana']:['mes','semana','dia'];
  document.querySelectorAll('#'+pfx+'view-tabs button').forEach((b,i)=>b.classList.toggle('on',vs[i]===window._agendaVista));
  renderAgenda();
}
function agendaSemanaInicio(mesRef,diaSel){
  const ref=diaSel?new Date(diaSel+'T12:00:00'):new Date((mesRef||new Date()).getFullYear(),(mesRef||new Date()).getMonth(),1);
  const start=new Date(ref);
  start.setDate(ref.getDate()-(ref.getDay()+6)%7);
  return start;
}
function agendaIrHoy(){
  window._agendaMes=new Date();
  window._agendaDiaSel=hoy();
  if(agendaIsDockOpen()&&typeof actAgendaSetDia==='function')actAgendaSetDia(hoy());
  renderAgenda();
}
function agendaSelDia(f){
  window._agendaDiaSel=f;
  if(agendaIsDockOpen()&&typeof actAgendaSetDia==='function')actAgendaSetDia(f);
  renderAgenda();
}
function agendaPeriodoLabel(){
  const v=window._agendaVista||'mes';
  const mesRef=window._agendaMes||new Date();
  const diaSel=window._agendaDiaSel||hoy();
  if(v==='dia'){
    const d=new Date(diaSel+'T12:00:00');
    return d.toLocaleDateString('es-CO',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
  }
  if(v==='semana'){
    const s=agendaSemanaInicio(mesRef,diaSel);
    const e=new Date(s);e.setDate(s.getDate()+6);
    return fmtF(s.toISOString().slice(0,10))+' — '+fmtF(e.toISOString().slice(0,10));
  }
  return agendaMesLabel(mesRef);
}
function renderAgendaSemanaGrid(eventos,mesRef,diaSel){
  const start=agendaSemanaInicio(mesRef,diaSel);
  const todayStr=hoy();
  const hdrs=['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];
  let h='<div class="agenda-week">';
  for(let i=0;i<7;i++){
    const d=new Date(start);d.setDate(start.getDate()+i);
    const fs=d.toISOString().slice(0,10);
    const dayEv=eventos.filter(ev=>(ev.fecha||'').slice(0,10)===fs).sort((a,b)=>(a.hora||'99:99').localeCompare(b.hora||'99:99'));
    h+='<div class="agenda-week-col'+(fs===todayStr?' today':'')+'">'+
      '<div class="agenda-week-col-hdr'+(fs===todayStr?' today':'')+'" onclick="agendaSelDia(\''+fs+'\')">'+hdrs[i]+'<br><span style="font-size:15px">'+d.getDate()+'</span></div>'+
      '<div class="agenda-week-col-body">'+dayEv.map(ev=>{
        const dc=ev.tipo==='asignado'?' asig':ev.tipo==='desde_actividad'?' act':ev.tipo==='gcal'?' gcal':'';
        return '<div class="agenda-cal-ev'+dc+'" style="margin-bottom:3px" onclick="agendaSelEvento(\''+escAttr(ev.id)+'\')">'+(ev.tipo==='gcal'?'✉ ':'')+(ev.hora?escAttr(ev.hora)+' ':'')+escAttr(ev.titulo)+'</div>';
      }).join('')+(dayEv.length?'':'<span style="color:var(--tx3);font-size:10px">—</span>')+'</div></div>';
  }
  return h+'</div>';
}
function renderAgendaDiaView(eventos,diaSel){
  const list=eventos.filter(ev=>(ev.fecha||'').slice(0,10)===diaSel).sort((a,b)=>(a.hora||'99:99').localeCompare(b.hora||'99:99'));
  const selEv=window._agendaSelEvId;
  const d=new Date(diaSel+'T12:00:00');
  let h='<div class="agenda-day-view"><div class="agenda-day-view-hdr">'+d.toLocaleDateString('es-CO',{weekday:'long',day:'numeric',month:'long',year:'numeric'})+'</div>';
  if(!list.length)h+='<div style="font-size:13px;color:var(--tx3);padding:1rem 0">Sin eventos. Pulse «+ Evento personal» para agendar.</div>';
  else h+=list.map(ev=>{
    const dc=ev.tipo==='asignado'?'border-left:3px solid var(--pu)':ev.tipo==='desde_actividad'?'border-left:3px solid var(--or)':ev.tipo==='gcal'?'border-left:3px solid #1a73e8':'border-left:3px solid var(--bl)';
    return '<div class="agenda-day-slot'+(ev.id===selEv?' sel':'')+'" style="'+dc+'" onclick="agendaSelEvento(\''+escAttr(ev.id)+'\')">'+
      '<div class="agenda-day-slot-time">'+(ev.hora||'—')+'</div>'+
      '<div style="flex:1"><div style="font-weight:600;font-size:14px">'+(ev.tipo==='gcal'?'<span class="bdg" style="background:#e8f0fe;color:#1a73e8;font-size:9px;margin-right:4px">Gmail</span>':'')+escAttr(ev.titulo)+'</div>'+
      (ev.detalle?'<div style="font-size:12px;color:var(--tx2);margin-top:2px">'+escAttr(ev.detalle)+'</div>':'')+'</div></div>';
  }).join('');
  return h+'</div>';
}
function agendaMesLabel(d){
  return d.toLocaleDateString('es-CO',{month:'long',year:'numeric'});
}
function renderAgendaCalGrid(eventos,mesRef,diaSel){
  const y=mesRef.getFullYear(),mo=mesRef.getMonth();
  const first=new Date(y,mo,1);
  const start=new Date(y,mo,1-(first.getDay()+6)%7);
  const hdrs=['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'];
  let h=hdrs.map(x=>'<div class="agenda-cal-hdr">'+x+'</div>').join('');
  const todayStr=hoy();
  const selEv=window._agendaSelEvId;
  for(let i=0;i<42;i++){
    const d=new Date(start);d.setDate(start.getDate()+i);
    const fs=d.toISOString().slice(0,10);
    const inMonth=d.getMonth()===mo;
    const dayEv=eventos.filter(ev=>(ev.fecha||'').slice(0,10)===fs);
    const cls='agenda-day'+(inMonth?'':' other')+(fs===todayStr?' today':'')+(fs===diaSel?' sel':'');
    h+='<div class="'+cls+'" onclick="agendaSelDia(\''+fs+'\')">'+
      '<div class="agenda-day-num">'+d.getDate()+'</div>'+
      '<div class="agenda-day-events">'+dayEv.slice(0,4).map(ev=>{
        const dc=ev.tipo==='asignado'?' asig':ev.tipo==='desde_actividad'?' act':ev.tipo==='gcal'?' gcal':'';
        return '<div class="agenda-cal-ev'+dc+'" onclick="event.stopPropagation();agendaSelEvento(\''+escAttr(ev.id)+'\')" title="'+escAttr(ev.titulo)+'">'+(ev.tipo==='gcal'?'✉ ':'')+escAttr(ev.titulo)+'</div>';
      }).join('')+(dayEv.length>4?'<div style="font-size:9px;color:var(--tx3)">+'+(dayEv.length-4)+' más</div>':'')+'</div></div>';
  }
  return h;
}
function renderAgendaListaHtml(eventos,diaSel){
  const list=eventos.filter(ev=>(ev.fecha||'').slice(0,10)===diaSel).sort((a,b)=>(a.hora||'99:99').localeCompare(b.hora||'99:99'));
  if(!list.length)return '<div style="font-size:12px;color:var(--tx3);padding:8px">Sin eventos este día. Pulse «+ Evento personal» para crear uno.</div>';
  const selEv=window._agendaSelEvId;
  return list.map(ev=>{
    const horaLbl=ev.hora?('<span style="font-family:\'DM Mono\',monospace;font-size:12px;color:var(--bl);min-width:52px">'+escAttr(ev.hora)+'</span>'):('<span style="font-size:12px;color:var(--tx3);min-width:52px">—</span>');
    return '<div class="agenda-ev-row'+(ev.id===selEv?' sel':'')+'" onclick="agendaSelEvento(\''+escAttr(ev.id)+'\')">'+horaLbl+
      (ev.tipo==='gcal'?'<span class="bdg" style="background:#e8f0fe;color:#1a73e8;font-size:9px;margin-right:4px">Gmail</span>':'')+
      '<span style="font-weight:600;font-size:13px;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+escAttr(ev.titulo)+'</span></div>';
  }).join('');
}
function getAgendaEventosCreadosPorEncargado(){
  const enc=getEncargadoDepto(deptoActivo);
  if(!enc)return [];
  return (agendaEventos||[]).map(normalizeAgendaEvento).filter(ev=>
    ev.tipo==='asignado'&&agendaNorm(ev.creadoPor)===agendaNorm(enc)&&(ev.depto||deptoActivo)===deptoActivo
  ).sort((a,b)=>(b.fecha||'').localeCompare(a.fecha||''));
}
function renderAgendaAsignadosGestHtml(){
  const list=getAgendaEventosCreadosPorEncargado();
  if(!list.length)return '<div style="font-size:12px;color:var(--tx3)">Sin eventos asignados a responsables.</div>';
  const byBatch={};
  list.forEach(ev=>{
    const k=ev.batch||ev.id;
    if(!byBatch[k])byBatch[k]={ev,dest:[]};
    if(!byBatch[k].dest.includes(ev.responsable))byBatch[k].dest.push(ev.responsable);
  });
  return Object.values(byBatch).map(({ev,dest})=>{
    return '<div class="agenda-item asig" style="margin-bottom:8px"><div class="agenda-item-hdr"><strong>'+escAttr(ev.titulo)+'</strong>'+
      '<span class="bdg" style="background:var(--pul);color:var(--pu);font-size:10px">Asignado</span></div>'+
      '<div style="font-size:11px;color:var(--tx2)">'+fmtF(ev.fecha)+(ev.hora?' · '+escAttr(ev.hora):'')+' · '+dest.length+' responsable(s)</div>'+
      (ev.detalle?'<div style="margin-top:3px;font-size:12px">'+escAttr(ev.detalle)+'</div>':'')+
      '<div style="font-size:10px;color:var(--tx3);margin-top:2px">'+escAttr(dest.join(', '))+'</div>'+
      '<button type="button" class="btn bsm bic" style="margin-top:4px" title="Editar evento asignado" onclick="agendaSelEvento(\''+escAttr(ev.id)+'\')">✏️ Editar</button></div>';
  }).join('');
}
function actualizarAgendaEvento(id,data){
  const ev=(agendaEventos||[]).find(x=>x.id===id);
  if(!ev){notif('Evento no encontrado','err');return false;}
  if(!puedeEditarAgendaEvento(ev)){notif('No puede editar este evento','err');return false;}
  const upd={
    titulo:String(data.titulo!=null?data.titulo:ev.titulo||'').trim(),
    detalle:String(data.detalle!=null?data.detalle:ev.detalle||'').trim(),
    fecha:data.fecha||ev.fecha,
    hora:String(data.hora!=null?data.hora:ev.hora||'').trim()
  };
  if(data.criterio!=null)upd.criterio=String(data.criterio||'').trim();
  if(data.notas!=null)upd.notas=String(data.notas||'').trim();
  if(data.orden!=null&&!isNaN(+data.orden))upd.orden=+data.orden;
  if(!upd.titulo){notif('Indique título','err');return false;}
  if(data.aplicarBatch&&ev.batch){
    (agendaEventos||[]).forEach(e=>{if(e.batch===ev.batch)Object.assign(e,upd);});
  }else Object.assign(ev,upd);
  saveLS();renderAgenda();renderBandejaDepto();
  return true;
}
function openAgendaEditModal(id){
  const ev=getAgendaEventoById(id);
  if(ev)agendaSelEvento(id);
}
function submitAgendaEditar(){
  agendaGuardarForm();
}
function eliminarAgendaEvento(id){
  const ev=(agendaEventos||[]).find(x=>x.id===id);
  if(ev&&!puedeEliminarAgendaEvento(ev)){notif('No puede eliminar este evento','err');return;}
  confirmEliminar({message:'¿Eliminar este evento de la agenda?',detail:ev?('«'+ev.titulo+'»'):''},()=>{
    agendaEventos=(agendaEventos||[]).filter(x=>x.id!==id);
    saveLS();renderAgenda();renderBandejaDepto();notif('Evento eliminado','ok');
  });
}
function renderAgenda(){
  if(!puedeVerTabAgenda())return;
  if(!agendaShouldPaint())return;
  const resp=getAgendaResponsableActivo();
  const tit=agendaEl('titulo');
  const sub=agendaEl('subtitulo');
  const btnAsig=document.getElementById('btn-agenda-asignar');
  const banner=agendaEl('gcal-banner');
  if(!resp){
    if(tit)tit.textContent='Mi agenda';
    if(sub)sub.textContent='Seleccione su nombre como responsable para ver su calendario.';
    if(agendaEl('cal-grid'))agendaEl('cal-grid').innerHTML='';
    if(agendaEl('lista'))agendaEl('lista').innerHTML='<div style="font-size:12px;color:var(--tx3);padding:8px">Sin responsable seleccionado.</div>';
    if(banner)banner.innerHTML='';
    return;
  }
  if(tit)tit.textContent=(window._agendaRenderTarget==='modal'||window._agendaRenderTarget==='dock'?'Calendario':'Agenda')+' · '+resp;
  if(sub)sub.textContent='Vista '+({mes:'mensual',semana:'semanal',dia:'diaria'}[window._agendaVista||'mes']||'mensual');
  if(btnAsig)btnAsig.style.display=(window._agendaRenderTarget!=='modal'&&window._agendaRenderTarget!=='dock'&&puedeAsignarEventoAgendaResponsables())?'inline-flex':'none';
  if(banner){
    const gmailOk=typeof gmailIsTokenValid==='function'&&gmailIsTokenValid();
    const calOk=gmailOk&&typeof gmailHasCalendarScope==='function'&&gmailHasCalendarScope()&&!window._gmailCalendarDenied;
    if(gmailOk&&!calOk){
      banner.innerHTML='<div style="font-size:12px;padding:8px 10px;margin-bottom:8px;border-radius:var(--r);background:#fff7ed;border:1px solid var(--or);color:var(--tx)">Conecte Gmail con permiso de <strong>Calendar</strong> para ver y crear eventos de su cuenta.'+
        ' <button type="button" class="btn bsm bp" style="margin-left:6px" onclick="gmailReconnectForCalendar()">Conceder Calendar</button></div>';
    }else if(!gmailOk){
      banner.innerHTML='<div style="font-size:11px;padding:6px 10px;margin-bottom:8px;border-radius:var(--r);background:var(--sf2);border:1px solid var(--bd);color:var(--tx2)">Agenda interna SST activa. Conecte Gmail (con Calendar) para ver eventos de su correo.</div>';
    }else{
      banner.innerHTML='<div style="font-size:11px;padding:4px 0;margin-bottom:6px;color:var(--tx3)">Eventos Gmail (calendario primario) aparecen con etiqueta <span class="bdg" style="background:#e8f0fe;color:#1a73e8;font-size:9px">Gmail</span>.</div>';
    }
  }
  const mesRef=window._agendaMes||new Date();
  const diaSel=window._agendaDiaSel||hoy();
  const sstEv=getAgendaEventosResponsable(resp);
  const gcalEv=Array.isArray(window._agendaGcalEvents)?window._agendaGcalEvents:[];
  const eventos=sstEv.concat(gcalEv);
  const vista=window._agendaVista||'mes';
  const pfx=agendaUiPrefix();
  document.querySelectorAll('#'+pfx+'view-tabs button').forEach((b,i)=>{const vs=(window._agendaRenderTarget==='modal'||window._agendaRenderTarget==='dock')?['mes','semana']:['mes','semana','dia'];b.classList.toggle('on',vs[i]===vista);});
  const lbl=agendaEl('mes-label');
  if(lbl)lbl.textContent=agendaPeriodoLabel();
  const wrap=agendaEl('cal-wrap');
  const grid=agendaEl('cal-grid');
  if(wrap&&grid){
    if(vista==='mes'){
      wrap.style.display='';
      grid.className='agenda-cal';
      grid.innerHTML=renderAgendaCalGrid(eventos,mesRef,diaSel);
    }else if(vista==='semana'){
      wrap.style.display='';
      grid.className='';
      grid.innerHTML=renderAgendaSemanaGrid(eventos,mesRef,diaSel);
    }else{
      wrap.style.display='';
      grid.className='';
      grid.innerHTML=renderAgendaDiaView(eventos,diaSel);
    }
  }
  const lt=agendaEl('lista-titulo');
  const lista=agendaEl('lista');
  const showBottom=vista==='mes'||vista==='semana';
  if(lt){
    lt.style.display=showBottom?'':'none';
    if(showBottom)lt.textContent='Eventos · '+fmtF(diaSel);
  }
  if(lista){
    lista.style.display=showBottom?'':'none';
    if(showBottom)lista.innerHTML=renderAgendaListaHtml(eventos,diaSel);
  }
  const gest=document.getElementById('agenda-asig-gest');
  if(gest&&window._agendaRenderTarget!=='modal'&&window._agendaRenderTarget!=='dock'){
    if(esVistaActividadesDepto()){
      gest.style.display='';
      gest.innerHTML='<details class="con-fold"><summary>Eventos asignados a responsables (editar)</summary><div class="item-fold-body">'+renderAgendaAsignadosGestHtml()+'</div></details>';
    }else gest.style.display='none';
  }
  agendaFetchGcalForVista(mesRef,diaSel,vista);
}
function agendaVisibleRangeIso(mesRef,diaSel,vista){
  vista=vista||'mes';
  let start,end;
  if(vista==='dia'){
    start=new Date((diaSel||hoy())+'T00:00:00');
    end=new Date((diaSel||hoy())+'T23:59:59');
  }else if(vista==='semana'){
    start=agendaSemanaInicio(mesRef,diaSel);
    end=new Date(start);end.setDate(start.getDate()+7);end.setHours(0,0,0,0);
  }else{
    const y=mesRef.getFullYear(),mo=mesRef.getMonth();
    const first=new Date(y,mo,1);
    start=new Date(y,mo,1-(first.getDay()+6)%7);
    end=new Date(start);end.setDate(start.getDate()+42);
  }
  return{min:start.toISOString(),max:end.toISOString(),key:start.toISOString().slice(0,10)+'_'+end.toISOString().slice(0,10)};
}
function agendaFetchGcalForVista(mesRef,diaSel,vista){
  if(typeof gmailIsTokenValid!=='function'||!gmailIsTokenValid()){
    window._agendaGcalEvents=[];
    return;
  }
  if(typeof gmailHasCalendarScope!=='function'||!gmailHasCalendarScope()||window._gmailCalendarDenied){
    window._agendaGcalEvents=[];
    return;
  }
  if(typeof gmailCalendarListEvents!=='function')return;
  const range=agendaVisibleRangeIso(mesRef,diaSel,vista);
  if(window._agendaGcalCacheKey===range.key&&Array.isArray(window._agendaGcalEvents))return;
  if(window._agendaGcalFetchKey===range.key)return;
  window._agendaGcalFetchKey=range.key;
  gmailCalendarListEvents(range.min,range.max).then(function(list){
    window._agendaGcalCacheKey=range.key;
    window._agendaGcalFetchKey='';
    window._agendaGcalEvents=Array.isArray(list)?list:[];
    // Re-pintar solo si sigue en agenda y mismo rango
    const cur=agendaVisibleRangeIso(window._agendaMes||new Date(),window._agendaDiaSel||hoy(),window._agendaVista||'mes');
    if(cur.key===range.key&&agendaShouldPaint()){
      _renderAgendaPaintOnly();
    }
  }).catch(function(err){
    window._agendaGcalFetchKey='';
    console.warn('Agenda GCal:',err);
    window._agendaGcalEvents=[];
    const ban=agendaEl('gcal-banner');
    if(ban&&(err&&err.code==='NO_CALENDAR_SCOPE'||window._gmailCalendarDenied)){
      ban.innerHTML='<div style="font-size:12px;padding:8px 10px;margin-bottom:8px;border-radius:var(--r);background:#fff7ed;border:1px solid var(--or);color:var(--tx)">Conecte Gmail con permiso de <strong>Calendar</strong> para ver eventos de su cuenta.'+
        ' <button type="button" class="btn bsm bp" style="margin-left:6px" onclick="gmailReconnectForCalendar()">Conceder Calendar</button></div>';
    }
  });
}
/** Re-pinta grid/lista sin relanzar fetch (tras cargar GCal). */
function _renderAgendaPaintOnly(){
  const resp=getAgendaResponsableActivo();
  if(!resp)return;
  const mesRef=window._agendaMes||new Date();
  const diaSel=window._agendaDiaSel||hoy();
  const eventos=getAgendaEventosResponsable(resp).concat(Array.isArray(window._agendaGcalEvents)?window._agendaGcalEvents:[]);
  const vista=window._agendaVista||'mes';
  const wrap=agendaEl('cal-wrap');
  const grid=agendaEl('cal-grid');
  if(wrap&&grid){
    if(vista==='mes'){grid.className='agenda-cal';grid.innerHTML=renderAgendaCalGrid(eventos,mesRef,diaSel);}
    else if(vista==='semana'){grid.className='';grid.innerHTML=renderAgendaSemanaGrid(eventos,mesRef,diaSel);}
    else{grid.className='';grid.innerHTML=renderAgendaDiaView(eventos,diaSel);}
  }
  const lista=agendaEl('lista');
  if(lista&&(vista==='mes'||vista==='semana'))lista.innerHTML=renderAgendaListaHtml(eventos,diaSel);
}
