function openAgendaDesdeActividad(expId,taskId){
  const t=getTaskAny(expId,taskId);
  if(!t)return;
  if(t.sinExpediente)expId=t.codigo;
  const resp=getAgendaResponsableActivo()||t.responsable;
  if(!resp){notif('Seleccione responsable','err');return;}
  const fechaBase=t.vence&&t.vence>=hoy()?t.vence:hoy();
  const prefill={
    titulo:t.desc||t.actividad||'Actividad',
    detalle:(t.exp?'Ref. '+t.exp:'')+(t.vence?' · Vence '+fmtF(t.vence):''),
    fecha:fechaBase,
    responsable:resp,
    taskRef:{expId,taskId},
    vence:t.vence||''
  };
  window._agendaPrefillTask=prefill.taskRef;
  window._actAgendaPrefillBase=prefill;
  window._actAgendaExpId=expId;
  window._actAgendaTaskId=taskId;
  window._actAgendaDrawerMode='create';
  window._actAgendaSelEvId=null;
  window._actAgendaDiaSel=hoy();
  window._actAgendaResp=resp;
  window._actAgendaOtroPlan=null;
  window._actAgendaNotasOpen=window._actAgendaNotasOpen||{};
  window._actAgendaPersonalAdd=false;
  window._actAgendaActAdd=false;
  const existentes=getAgendaEventosForTask(expId,taskId);
  const planHoy=existentes.find(e=>(e.fecha||'').slice(0,10)===hoy());
  if(planHoy){
    window._actAgendaSelEvId=planHoy.id;
    window._actAgendaDrawerMode='edit';
  }else{
    window._actAgendaOtroPlan=existentes.slice().sort((a,b)=>(b.fecha||'').localeCompare(a.fecha||''))[0]||null;
  }
  window._actAgendaPanelSide='right';
  window._actAgendaShowCal=false;
  actAgendaAbrirPanelUi();
}
function actAgendaAbrirPanelUi(){
  const dock=document.getElementById('act-agenda-dock');
  const overlay=document.getElementById('act-agenda-overlay');
  const body=document.getElementById('act-agenda-body');
  const tit=document.getElementById('act-agenda-tit');
  const sub=document.getElementById('act-agenda-sub');
  const side=window._actAgendaPanelSide||'right';
  const showCal=!!window._actAgendaShowCal;
  if(tit)tit.textContent='Tasks';
  if(sub)sub.textContent='Mi día';
  if(body)body.innerHTML=renderMiDiaPanelHtml();
  refreshActAgendaPanelTools();
  if(overlay)overlay.classList.add('on');
  syncActAgendaCalPane(showCal);
  if(!dock){
    setNavTasksActive(true);
    return;
  }
  dock.style.transition='none';
  applyActAgendaDockSide(side,showCal);
  dock.setAttribute('aria-hidden','true');
  void dock.offsetWidth;
  requestAnimationFrame(function(){
    dock.style.transition='';
    requestAnimationFrame(function(){
      dock.classList.remove('act-agenda-closing');
      dock.classList.add('on');
      dock.setAttribute('aria-hidden','false');
      updateActAgendaCalToggleUi(showCal);
      setNavTasksActive(true);
    });
  });
}
function getAgendaPlanesActivos(resp){
  const nNorm=agendaNorm(resp);
  return (agendaEventos||[]).map(normalizeAgendaEvento).filter(ev=>{
    if(agendaNorm(ev.responsable)!==nNorm)return false;
    if(ev.hecho)return false;
    if(ev.tipo==='asignado')return false;
    return agendaEventoVisible(ev);
  });
}
function getAgendaPlanesDelDia(resp,fecha){
  const f=(fecha||hoy()).slice(0,10);
  return getAgendaPlanesActivos(resp).filter(ev=>(ev.fecha||'').slice(0,10)===f).sort(actAgendaSortPlanes);
}
function getAgendaPlanesProximos(resp){
  const h=hoy();
  return getAgendaPlanesActivos(resp).filter(ev=>(ev.fecha||'').slice(0,10)>h).sort((a,b)=>{
    const da=(a.fecha||'').localeCompare(b.fecha||'');
    if(da)return da;
    return actAgendaSortPlanes(a,b);
  });
}
function getAgendaPlanesVencidos(resp){
  const h=hoy();
  return getAgendaPlanesActivos(resp).filter(ev=>(ev.fecha||'').slice(0,10)<h).sort((a,b)=>(b.fecha||'').localeCompare(a.fecha||''));
}
function actAgendaSortPlanes(a,b){
  if(a.orden!==b.orden)return a.orden-b.orden;
  return (a.titulo||'').localeCompare(b.titulo||'','es');
}
function getActAgendaPlanVinculado(){
  const expId=window._actAgendaExpId;
  const taskId=window._actAgendaTaskId;
  if(!expId||!taskId)return null;
  const dia=(window._actAgendaDiaSel||hoy()).slice(0,10);
  return getAgendaEventosForTask(expId,taskId).find(e=>(e.fecha||'').slice(0,10)===dia&&!e.hecho)||null;
}
function actAgendaShiftDia(delta){
  const base=window._actAgendaDiaSel||hoy();
  const d=new Date(base+'T12:00:00');
  d.setDate(d.getDate()+(delta||0));
  actAgendaSetDia(d.toISOString().slice(0,10));
}
function actAgendaSetDia(f){
  if(!f)return;
  window._actAgendaDiaSel=f.slice(0,10);
  const plan=getActAgendaPlanVinculado();
  if(plan){
    window._actAgendaSelEvId=plan.id;
    window._actAgendaDrawerMode='edit';
  }else{
    window._actAgendaSelEvId=null;
    window._actAgendaDrawerMode='create';
  }
  refreshMiDiaPanel();
}
function actAgendaLeerFechaForm(prefix,def){
  const el=document.getElementById(prefix+'-fecha');
  return(el&&el.value?el.value:def||hoy()).slice(0,10);
}
function actAgendaLeerNotasForm(prefix){
  const el=document.getElementById(prefix+'-notas');
  return el?String(el.value||'').trim():'';
}
function actAgendaTienePlanActividad(){
  const expId=window._actAgendaExpId,taskId=window._actAgendaTaskId;
  if(!expId||!taskId)return false;
  return getAgendaEventosForTask(expId,taskId).some(e=>!e.hecho);
}
function actAgendaToggleActAdd(on){
  window._actAgendaActAdd=on==null?!window._actAgendaActAdd:!!on;
  if(window._actAgendaActAdd)window._actAgendaPersonalAdd=false;
  refreshMiDiaPanel();
}
function actAgendaTogglePersonalAdd(on){
  window._actAgendaPersonalAdd=on==null?!window._actAgendaPersonalAdd:!!on;
  if(window._actAgendaPersonalAdd)window._actAgendaActAdd=false;
  refreshMiDiaPanel();
  if(window._actAgendaPersonalAdd){
    setTimeout(function(){
      const inp=document.getElementById('gt-personal-titulo');
      if(inp)inp.focus();
    },50);
  }
}
function actAgendaCrearPersonal(){
  const resp=window._actAgendaResp||getAgendaResponsableActivo();
  if(!resp){notif('Seleccione responsable','err');return;}
  const inp=document.getElementById('gt-personal-titulo');
  const titulo=inp?String(inp.value||'').trim():'';
  if(!titulo){notif('Escriba la tarea personal','err');return;}
  const fecha=actAgendaLeerFechaForm('gt-personal',hoy());
  const notas=actAgendaLeerNotasForm('gt-personal');
  const ev=crearAgendaEvento({
    titulo:titulo,detalle:'',fecha:fecha,hora:'',notas:notas,
    responsable:resp,tipo:'personal',taskRef:null,orden:Date.now(),
    depto:esModoResponsable()?'responsables':deptoActivo,syncGcal:false
  });
  if(ev){
    window._actAgendaPersonalAdd=false;
    if(!window._actAgendaNotasOpen)window._actAgendaNotasOpen={};
    if(notas)window._actAgendaNotasOpen[ev.id]=true;
    refreshMiDiaPanel();
  }
}
function actAgendaProgramar(){
  const resp=window._actAgendaResp||getAgendaResponsableActivo();
  if(!resp){notif('Seleccione responsable','err');return;}
  const prefill=window._actAgendaPrefillBase||{};
  if(!prefill.taskRef&&!window._actAgendaExpId)return;
  const fecha=actAgendaLeerFechaForm('gt-act',hoy());
  const notas=actAgendaLeerNotasForm('gt-act');
  let plan=getActAgendaPlanVinculado();
  if(!plan&&window._actAgendaSelEvId)plan=getAgendaEventoById(window._actAgendaSelEvId);
  if(!plan&&window._actAgendaOtroPlan)plan=getAgendaEventoById(window._actAgendaOtroPlan.id)||window._actAgendaOtroPlan;
  const payload={
    titulo:prefill.titulo||'Actividad',detalle:prefill.detalle||'',
    fecha:fecha,hora:'',notas:notas,
    orden:plan&&plan.orden!=null?plan.orden:Date.now()
  };
  if(plan&&puedeEditarAgendaEvento(plan)){
    plan.hecho=false;
    if(actualizarAgendaEvento(plan.id,payload)){
      window._actAgendaSelEvId=plan.id;
      window._actAgendaDrawerMode='edit';
      window._actAgendaOtroPlan=null;
      window._actAgendaActAdd=false;
      if(!window._actAgendaNotasOpen)window._actAgendaNotasOpen={};
      if(notas)window._actAgendaNotasOpen[plan.id]=true;
      refreshMiDiaPanel();
      refreshVistasTrasAgendar();
    }
    return;
  }
  const ev=crearAgendaEvento({
    ...payload,responsable:resp,tipo:'desde_actividad',
    taskRef:window._agendaPrefillTask||prefill.taskRef||null,
    depto:esModoResponsable()?'responsables':deptoActivo,syncGcal:false
  });
  if(ev){
    window._actAgendaSelEvId=ev.id;
    window._actAgendaDrawerMode='edit';
    window._actAgendaOtroPlan=null;
    window._actAgendaActAdd=false;
    if(!window._actAgendaNotasOpen)window._actAgendaNotasOpen={};
    if(notas)window._actAgendaNotasOpen[ev.id]=true;
    refreshMiDiaPanel();
    refreshVistasTrasAgendar();
  }
}
function actAgendaReagendar(id,fecha){
  id=String(id||'').trim();
  fecha=String(fecha||'').slice(0,10);
  if(!id||!fecha)return;
  const ev=getAgendaEventoById(id);
  if(!ev||!puedeEditarAgendaEvento(ev))return;
  if(actualizarAgendaEvento(id,{
    titulo:ev.titulo,detalle:ev.detalle,fecha:fecha,hora:ev.hora||'',
    notas:ev.notas||'',orden:Date.now()
  })){
    notif('Reagendado · '+fmtF(fecha),'ok');
    refreshMiDiaPanel();
    refreshVistasTrasAgendar();
  }
}
function actAgendaGuardarItemCampos(id){
  const ev=getAgendaEventoById(id);
  if(!ev||!puedeEditarAgendaEvento(ev))return;
  const notasEl=document.getElementById('mi-dia-notas-'+id);
  const notas=notasEl?String(notasEl.value||'').trim():(ev.notas||'');
  if(notas===(ev.notas||''))return;
  ev.notas=notas;
  saveLS();
}
function actAgendaToggleNotas(id){
  if(!window._actAgendaNotasOpen)window._actAgendaNotasOpen={};
  window._actAgendaNotasOpen[id]=!window._actAgendaNotasOpen[id];
  refreshMiDiaPanel();
}
function actAgendaMarcarHecho(id){
  const ev=getAgendaEventoById(id);
  if(!ev||!puedeEditarAgendaEvento(ev))return;
  ev.hecho=true;
  saveLS();
  if(window._actAgendaSelEvId===id){
    window._actAgendaSelEvId=null;
    window._actAgendaDrawerMode='create';
  }
  refreshMiDiaPanel();
  refreshVistasTrasAgendar();
}
function actAgendaMoverOrden(id,dir){
  const ev=getAgendaEventoById(id);
  if(!ev||!puedeEditarAgendaEvento(ev))return;
  const dia=(ev.fecha||hoy()).slice(0,10);
  const list=getAgendaPlanesDelDia(ev.responsable,dia);
  const idx=list.findIndex(e=>e.id===id);
  if(idx<0)return;
  const swap=list[idx+(dir<0?-1:1)];
  if(!swap)return;
  const oA=ev.orden,oB=swap.orden;
  ev.orden=oB;swap.orden=oA;
  if(ev.orden===swap.orden){ev.orden=idx;swap.orden=idx+(dir<0?-1:1);}
  saveLS();
  refreshMiDiaPanel();
}
function actAgendaQuitarPlan(id){
  id=id||window._actAgendaSelEvId;
  if(!id)return;
  const ev=getAgendaEventoById(id);
  if(ev&&!puedeEliminarAgendaEvento(ev)){notif('No puede quitar este ítem','err');return;}
  confirmEliminar({message:'¿Quitar de mi día?',detail:ev?('«'+ev.titulo+'»'):''},()=>{
    agendaEventos=(agendaEventos||[]).filter(x=>x.id!==id);
    saveLS();
    if(document.getElementById('pg-agenda')&&document.getElementById('pg-agenda').classList.contains('on'))renderAgenda();
    renderBandejaDepto();
    if(window._actAgendaSelEvId===id){
      window._actAgendaSelEvId=null;
      window._actAgendaDrawerMode='create';
    }
    refreshMiDiaPanel();
    refreshVistasTrasAgendar();
  });
}
