function openActividadesAsignadasDesdeRevision(ref,taskId){
  ref=String(ref||'').trim();
  taskId=String(taskId||'').trim();
  const t=typeof getTaskAny==='function'?getTaskAny(ref,taskId):null;
  if(t&&t.sinExpediente){
    notif('En actividades sin expediente use ✏️ Editar','err');
    return;
  }
  if(typeof esModoResponsable==='function'&&esModoResponsable()){
    notif('Solo el encargado puede añadir actividades','err');
    return;
  }
  const fromReview=typeof taskModalIsReviewOpen==='function'&&taskModalIsReviewOpen();
  if(fromReview&&typeof reviewPanelPrepOpen==='function')reviewPanelPrepOpen();
  window._conPanelFocusActividades=true;
  if(typeof editarExpDesdeAct==='function')editarExpDesdeAct(ref,taskId);
  else if(typeof editarExp==='function')editarExp(ref);
  if(fromReview&&typeof reviewPanelElevateConSide==='function')setTimeout(reviewPanelElevateConSide,60);
  setTimeout(function(){
    if(typeof conPanelFocusActividadesAsignadas==='function')conPanelFocusActividadesAsignadas();
    window._conPanelFocusActividades=false;
  },220);
}
function taskReviewObsToggleHtml(open){
  open=!!open;
  return '<button type="button" class="task-review-obs-toggle" id="soporte-obs-toggle" onclick="toggleSoporteObsPanel()" title="'+(open?'Ocultar observaciones':'Observaciones del documento')+'" aria-expanded="'+(open?'true':'false')+'">'+
    '<span class="soporte-obs-toggle-ico">'+(open?'▲':'▼')+'</span>'+
    '<span class="task-review-obs-lbl">Obs.</span></button>';
}
function openTaskArchivosFromAct(ref,taskId){
  ref=String(ref||'').trim();
  taskId=String(taskId||'').trim();
  const t=typeof getTaskAny==='function'?getTaskAny(ref,taskId):null;
  const libre=t?!!t.sinExpediente:(typeof isActLibreRef==='function'&&isActLibreRef(ref,taskId));
  if(taskModalIsReviewOpen())pushTaskModalLayer('archivos');
  if(typeof openConsultaArchivos==='function')openConsultaArchivos(ref,taskId,{forceModal:true,libre:libre});
  else if(typeof openConsultaArchivosModal==='function'&&!libre)openConsultaArchivosModal(ref);
  else notif('Módulo de archivos no disponible','err');
  if(taskModalIsReviewOpen()&&typeof reviewStackEnsureTaskModalFront==='function')reviewStackEnsureTaskModalFront();
  else if(taskModalIsReviewOpen()&&typeof reviewElevateTaskModal==='function')reviewElevateTaskModal();
}
function openAsociarActividadModal(ref,taskId){
  ref=String(ref||'').trim();
  taskId=String(taskId||'').trim();
  const t=typeof getTaskAny==='function'?getTaskAny(ref,taskId):null;
  if(taskModalIsReviewOpen()&&typeof openReviewAsocPickPanel==='function'){
    openReviewAsocPickPanel({ref:ref,taskId:taskId,task:t});
    return;
  }
  if(t&&!t.sinExpediente){
    const expId=t.exp||ref;
    const e=getExpById(expId);
    if(e&&typeof esPqrsSecretaria==='function'&&esPqrsSecretaria(e)&&typeof puedeGestionarPqrsAsociacion==='function'&&puedeGestionarPqrsAsociacion(e)){
      if(typeof SST!=='undefined'&&typeof SST.openAsociarUnificadoModal==='function')SST.openAsociarUnificadoModal(expId);
      else if(typeof openAsociarUnificadoModal==='function')openAsociarUnificadoModal(expId);
      return;
    }
    if(typeof editarExpDesdeAct==='function')editarExpDesdeAct(expId,taskId);
    setTimeout(function(){if(typeof conPanelFocusExpAsoc==='function')conPanelFocusExpAsoc();},280);
    return;
  }
  const cod=t?(t.codigo||ref):ref;
  const ov=document.getElementById('task-modal-overlay');
  const tit=document.getElementById('task-modal-title');
  const body=document.getElementById('task-modal-body');
  const modal=ov?ov.querySelector('.task-modal'):null;
  if(!ov||!body){notif('No se pudo abrir el formulario de asociación','err');return;}
  if(tit)tit.textContent='🖇️ Asociar · '+(cod||'actividad');
  if(modal){modal.classList.remove('task-modal-wide');modal.classList.add('enviar-modal-only');}
  body.innerHTML=(typeof renderActLibreVincularHtml==='function'?renderActLibreVincularHtml(cod,taskId):'<div style="font-size:12px;color:var(--tx2)">Formulario no disponible.</div>')+
    '<div style="margin-top:10px"><button type="button" class="btn bsm" onclick="closeTaskModal()">Cerrar</button></div>';
  ov.classList.add('on');
  window._taskModalCtx={mode:'actLibreVinc',expId:cod,taskId:taskId};
}
function getActLibreById(id){
  const sid=String(id||'').trim();
  if(!sid)return null;
  let found=(actividadesLibres||[]).find(t=>String(t&&t.id||'').trim()===sid)||null;
  // Recuperar si el sync remoto pisó una entrega recién creada
  if(!found&&window._pendingActLibreEntrega&&String(window._pendingActLibreEntrega.id||'')===sid){
    found=window._pendingActLibreEntrega.t||null;
    if(found){
      if(!Array.isArray(actividadesLibres))actividadesLibres=[];
      if(!actividadesLibres.some(t=>String(t&&t.id||'')===sid))actividadesLibres.push(found);
    }
  }
  return found;
}
function getActLibreByCodigo(cod){
  const sc=String(cod||'').trim();
  if(!sc)return null;
  let found=(actividadesLibres||[]).find(t=>String(t&&t.codigo||'').trim()===sc)||null;
  if(!found&&window._pendingActLibreEntrega&&String(window._pendingActLibreEntrega.codigo||'')===sc){
    found=window._pendingActLibreEntrega.t||null;
    if(found){
      if(!Array.isArray(actividadesLibres))actividadesLibres=[];
      const sid=String(found.id||'');
      if(sid&&!actividadesLibres.some(t=>String(t&&t.id||'')===sid))actividadesLibres.push(found);
    }
  }
  return found;
}
function getActividadesLibresDepto(deptoId){
  const d=resolveDeptoActLibre(deptoId||deptoActivo);
  return (actividadesLibres||[]).map(normalizeActLibre).filter(t=>!t.eliminada&&deptoEfectivoActLibre(t)===d);
}
function isActLibreRef(expId,taskId){
  if(taskId&&getActLibreById(taskId))return true;
  if(expId&&getActLibreByCodigo(expId))return true;
  return false;
}
function poblarActDeptRespSel(){
  const sel=document.getElementById('act-dept-resp-sel');if(!sel)return;
  const enc=getEncargadoDepto(deptoActivo);
  let cv=sel.value;
  let names;
  if(esVistaActividadesOficinaPqrs()){
    names=getResponsablesOficinaPqrs(deptoActivo).filter(Boolean);
    if(!cv||cv===enc)cv='__all__';
  }else{
    if(!cv&&enc)cv=enc;
    names=esNcaDeguv()?getResponsablesNcaDeguv():getContratistasAsignables(deptoActivo);
    if(enc&&!names.includes(enc))names.unshift(enc);
  }
  sel.innerHTML=names.map(n=>'<option value="'+escAttr(n)+'"'+(cv===n?' selected':'')+'>'+escAttr(n)+(n===enc?' · Encargado':'')+'</option>').join('')+
    '<option value="__all__"'+(cv==='__all__'?' selected':'')+'>Todos los responsables</option>';
  if(cv&&[...sel.options].some(o=>o.value===cv))sel.value=cv;
  else if(esVistaActividadesOficinaPqrs())sel.value='__all__';
  else if(enc)sel.value=enc;
}
function poblarSelResponsable(){
  const sel=document.getElementById('sel-responsable');if(!sel)return;
  if(esResponsableIdentidadFija()){
    fijarResponsableSesion();
    return;
  }
  const cv=responsableActivo||sel.value;
  const names=esModoResponsable()?getAllResponsables():[];
  sel.innerHTML='<option value="">— Seleccione —</option>'+names.map(n=>'<option value="'+escAttr(n)+'"'+(cv===n?' selected':'')+'>'+escAttr(n)+'</option>').join('');
  if(cv)sel.value=cv;
  const lbl=document.getElementById('resp-global-label');
  if(lbl)lbl.textContent='Responsable:';
}
function onResponsableChange(){
  if(!puedeMostrarSelectorResponsable()){
    if(esResponsableIdentidadFija())fijarResponsableSesion();
    updateDeptoUI();
    return;
  }
  const sel=document.getElementById('sel-responsable');
  responsableActivo=sel?sel.value:'';
  try{localStorage.setItem('sst_responsable',responsableActivo||'');}catch(e){}
  const hint=document.getElementById('resp-global-hint');
  if(hint)hint.textContent=responsableActivo?(esModoResponsable()?(responsablePuedeVerRegistro()?'Conectado como: '+responsableActivo+' — edición en Registro según secciones habilitadas.':'Sin acceso a Registro — use Consulta y Actividades.'):''):esModoResponsable()?'Seleccione su nombre para ver sus actividades asignadas.':'';
  updateDeptoUI();
  renderResponsableRegistro();
  if(document.getElementById('pg-reg').classList.contains('on'))renderTabla();
  if(document.getElementById('pg-act').classList.contains('on'))renderActividades();
  if(document.getElementById('pg-agenda').classList.contains('on'))renderAgenda();
  if(document.getElementById('pg-con').classList.contains('on')){poblarFiltrosCon();renderConsulta();}
  if(document.getElementById('pg-cons').classList.contains('on'))renderConsolidado();
  renderBandejaDepto();
}
function cambiarResponsable(){
  if(!puedeMostrarSelectorResponsable()){
    if(esResponsableIdentidadFija())notif('Su sesión está vinculada a su cuenta de Google','err');
    else notif('Solo el administrador puede cambiar de responsable','err');
    if(esResponsableIdentidadFija())fijarResponsableSesion();
    return;
  }
  responsableActivo='';
  try{localStorage.setItem('sst_responsable','');}catch(e){}
  const sel=document.getElementById('sel-responsable');
  if(sel){sel.value='';sel.focus();}
  onResponsableChange();
  if(esModoResponsable())showTab('act');
}
function getTareasResponsableActivo(){
  if(!responsableActivo)return [];
  const out=[];
  exps.forEach(e=>{
    if(typeof expEstaEnPapelera==='function'?expEstaEnPapelera(e):e._eliminado)return;
    (e.tasks||[]).forEach(t=>{
      t=normalizeTask(t);
      if(t.eliminada)return;
      if(!pqrsTaskVisibleEnActividades(t,e,responsableActivo))return;
      if(!taskUsuarioEsAsignado(t,responsableActivo))return;
      out.push({
        ...normalizeTask(t),
        exp:e._exp,
        nombre:getNom(e),
        tram:(getTram(e._tramite,e)||{}).nombre||'',
        depto:e._depto,
        sinExpediente:false
      });
    });
  });
  (actividadesLibres||[]).forEach(t=>{
    t=normalizeActLibre(t);
    if(t.eliminada||!taskUsuarioEsAsignado(t,responsableActivo))return;
    out.push(actLibreActividadListRow(t));
  });
  return out;
}
function getTareasOficinaPqrsActividades(respFilter){
  const list=[];
  const ofi=deptoActivo;
  exps.filter(e=>esPqrsSecretaria(e)&&e._pqrs_oficina===ofi).forEach(e=>{
    (e.tasks||[]).forEach(t=>{
      t=normalizeTask(t);
      if(t.eliminada||!taskEsAtenderPqrs(t,e))return;
      if(!pqrsTaskVisibleEnActividades(t,e,respFilter))return;
      if(respFilter&&!taskUsuarioEsAsignado(t,respFilter))return;
      list.push({...t,exp:e._exp,depto:e._depto,nombre:getNom(e),tram:'PQRSD',sinExpediente:false,esPqrs:true,prioritaria:!!(t.prioritaria||e._pqrs_prioritaria)});
    });
  });
  return list;
}
function getTareasDeptActividades(respFilter){
  const list=[];
  if(esVistaActividadesOficinaPqrs())return getTareasOficinaPqrsActividades(respFilter);
  const depto=deptoActivo;
  exps.filter(e=>(e._depto||'guaviare')===depto).forEach(e=>{
    if(typeof expEstaEnPapelera==='function'?expEstaEnPapelera(e):e._eliminado)return;
    (e.tasks||[]).forEach(t=>{
      t=normalizeTask(t);
      if(t.eliminada)return;
      if(!pqrsTaskVisibleEnActividades(t,e,respFilter))return;
      // Mismo criterio que oficina PQRSD: el filtro por responsable aplica a todas las tareas
      if(respFilter&&!taskUsuarioEsAsignado(t,respFilter))return;
      const tramObj=getTram(e._tramite,e);
      list.push({...t,exp:e._exp,depto:e._depto,nombre:getNom(e),tram:tramObj?tramObj.nombre:(esTramitePqrs(e._tramite)?'PQRSD':''),sinExpediente:false,esPqrs:esTramitePqrs(e._tramite),prioritaria:!!(t.prioritaria||(esTramitePqrs(e._tramite)&&e._pqrs_prioritaria))});
    });
  });
  getActividadesLibresDepto(depto).forEach(t=>{
    if(respFilter&&!taskUsuarioEsAsignado(t,respFilter))return;
    list.push(actLibreActividadListRow(t));
  });
  return list;
}
function puedeTrasladarPqrs(e){
  if(!e||!esPqrsSecretaria(e))return false;
  if(pqrsPendienteTraslado(e))return false;
  if(pqrsEstaCerrada(e))return false;
  if(esSecretaria())return true;
  if(esModoOficinaDeguv())return e._pqrs_oficina===deptoActivo;
  if(esOficinaPqrsNca()&&e._pqrs_oficina==='guaviare')return true;
  return false;
}
function pqrsOficinasSelectOpts(selId,inclSecretaria){
  const list=inclSecretaria?OFICINAS_DEGUV:OFICINAS_DEGUV.filter(o=>o.id!=='secretaria');
  return list.map(o=>'<option value="'+escAttr(o.id)+'"'+(selId===o.id?' selected':'')+'>'+escAttr(o.nombre)+'</option>').join('');
}
function taskEsAtenderPqrs(t,e){
  return !!(t&&String(t.actividad||'').startsWith('Atender PQRSD')&&e&&esPqrsSecretaria(e));
}
function guardarPqrsRespuestaDatos(e,opts,cerrar){
  if(!e)return;
  opts=opts||{};
  const fechaResp=opts.fechaResp||'';
  const oficioExt=opts.oficioExt||'';
  const medioResp=opts.medioResp||'';
  const nota=opts.nota||'';
  const cuerpo=opts.cuerpo||'';
  const adj=opts.adj||{links:[],files:[]};
  const archivos=opts.archivos||[];
  if(fechaResp)e._pqrs_respuesta_fecha=fechaResp;
  if(oficioExt!==undefined)e._pqrs_respuesta_oficio=oficioExt;
  if(medioResp!==undefined)e._pqrs_respuesta_medio=medioResp;
  if(opts.notaInterna!==undefined)e._pqrs_notas_internas=opts.notaInterna;
  else if((nota||cuerpo)&&opts.esNotaPublica!==false)e._pqrs_respuesta_nota=nota||cuerpo;
  if(archivos.length){
    const mapSop=function(a,i,ver){
      const url=a.driveLink||a.url||a.data||a.previewLink||'';
      const preview=a.previewLink||a.preview||a.driveLink||a.url||a.data||'';
      const baseLbl=a.nombre||a.name||a.label||('Respuesta '+(i+1));
      const estTag=_pqrsDocEsPorCorregir(a)?' · por corregir':(ver?' · entrega v'+ver:'');
      return {label:baseLbl+estTag,url:url,mime:a.mime||'',preview:preview,version:ver||a.entrega_n||null,activo:!_pqrsDocEsPorCorregir(a),driveEstado:a.driveEstado||''};
    };
    if(cerrar){
      e._pqrs_respuesta_soportes=archivos.map(function(a,i){return mapSop(a,i,null);});
    }else{
      // Conservar soportes de versiones anteriores (por corregir) para comparar
      const prev=Array.isArray(e._pqrs_respuesta_soportes)?e._pqrs_respuesta_soportes.slice():[];
      prev.forEach(function(s){if(s)s.activo=false;});
      const wfPrev=getPqrsWorkflow(e);
      const entregaN=(Number(wfPrev.entrega_n)||prev.filter(function(s){return s&&s.activo!==false;}).length||0)+1;
      const nuevos=archivos.map(function(a,i){return mapSop(Object.assign({},a,{driveEstado:a.driveEstado||'revision'}),i,entregaN);});
      const seen=new Set(prev.map(function(s){return String((s&&(s.url||s.preview))||'').toLowerCase();}).filter(Boolean));
      nuevos.forEach(function(s){
        const k=String((s.url||s.preview)||'').toLowerCase();
        if(k&&seen.has(k))return;
        if(k)seen.add(k);
        prev.push(s);
      });
      e._pqrs_respuesta_soportes=prev;
    }
  }else{
    if(adj.links.length)e._pqrs_respuesta_link=adj.links[0];
    if(adj.links.length>1)e._pqrs_respuesta_links=adj.links;
  }
  if(!Array.isArray(e._pqrs_historial))e._pqrs_historial=[];
  const tipo=opts.tipo||PQRS_WF_TIPO.MENSAJE;
  const canal=opts.canal||medioResp||'';
  if(cerrar){
    // Full closure (offices + NCA encargado direct)
    finalizarTareasPqrsAlCerrar(e,'PQRSD cerrada — respuesta registrada');
    e._pqrs_estado_oficina='cerrado';
    const fAt=fechaResp||hoy();
    e._estado='Atendido';
    e._fecha_res=fAt;
    const fe=getFechasEstado(e);
    fe.Atendido=fAt;
    if(!fe['En trámite'])fe['En trámite']=fe.Solicitud||e._fecha||fAt;
    e._fechas_estado=JSON.stringify(fe);
    e.historial=rebuildHistorial(e,e.historial||[]);
    const histNota=[nota||cuerpo||'Respuesta registrada',oficioExt?'Oficio '+oficioExt:'',canal?medioNotificacionRespLabel(canal):''].filter(Boolean).join(' · ')+' — '+pqrsComentarioAutor();
    e._pqrs_historial.push({tipo:'respuesta_oficina',fecha:fechaResp||hoy(),nota:histNota,oficina:e._pqrs_oficina});
  }else if(fechaResp){
    // Responsable NCA delivery: sets pending_revision — conserva docs «por corregir» previos
    const wfPrev=getPqrsWorkflow(e);
    const entregaN=(Number(wfPrev.entrega_n)||0)+1;
    const docsMerged=_pqrsMergeDocumentosEntrega(wfPrev.documentos||[],archivos||[],entregaN);
    const wfPatch={
      fase:PQRS_WF.PENDIENTE_REVISION,
      tipo,canal,cuerpo,
      oficio:oficioExt,
      fecha_respuesta:fechaResp,
      documentos:docsMerged,
      entrega_n:entregaN,
      entregado_por:responsableActivo||'',
      entregado_en:new Date().toISOString()
    };
    if(opts.emailTo!==undefined)wfPatch.email_to=opts.emailTo;
    if(opts.emailCc!==undefined)wfPatch.email_cc=opts.emailCc;
    if(opts.emailBcc!==undefined)wfPatch.email_bcc=opts.emailBcc;
    if(opts.emailSubject!==undefined)wfPatch.email_subject=opts.emailSubject;
    if(tipo===PQRS_WF_TIPO.OFICIO&&opts.notificarPor){
      wfPatch.notificar_por=String(opts.notificarPor).trim();
      wfPatch.notificar_por_propuesto=String(opts.notificarPor).trim();
    }
    setPqrsWorkflow(e,wfPatch);
    e._pqrs_historial.push({tipo:'entrega_respuesta_nca',fecha:fechaResp,nota:'Entrega de respuesta para revisión NCA (v'+entregaN+')'+(oficioExt?' · Oficio '+oficioExt:'')+' — '+pqrsComentarioAutor(),oficina:e._pqrs_oficina,responsable:responsableActivo||''});
  }
}
function registrarPqrsRespuestaCore(e,opts){
  guardarPqrsRespuestaDatos(e,opts||{},true);
}
function getPqrsRespuestaDocPreview(e,t){
  if(!e)return null;
  if(e._pqrs_respuesta_link){
    const p=parseDrivePreviewUrl(e._pqrs_respuesta_link);
    return{url:p.url||e._pqrs_respuesta_link,preview:p.preview||p.url||e._pqrs_respuesta_link,label:'Respuesta al ciudadano'};
  }
  if(t){
    const activo=getSoporteActivo(t);
    if(activo&&(activo.preview||activo.url)){
      return{url:activo.url||activo.preview,preview:activo.preview||activo.url,label:activo.label||'Documento de respuesta'};
    }
  }
  return null;
}
