function _pqrsEsErrorPermisoDrive(err){
  const msg=String((err&&err.message)||err||'').toLowerCase();
  return /insufficient permissions|permission|no se pudo crear carpeta|access denied|403|forbidden|no tiene acceso|drive/i.test(msg)
    &&(/permission|permiso|forbidden|403|insufficient|crear carpeta|parent/i.test(msg)||/drive/i.test(msg));
}
function alertErrorDriveAdjunto(err){
  const raw=String((err&&err.message)||err||'').trim();
  const esPerm=_pqrsEsErrorPermisoDrive(err)||/insufficient permissions|crear carpeta|403|forbidden|no tiene acceso|sin_acceso_drive/i.test(raw);
  const msg=esPerm
    ?'No se puede cargar el archivo: no tiene permisos de Drive. Contacte con el administrador.'
    :('No se pudo subir el archivo al Drive institucional. Intente de nuevo o contacte al administrador.');
  // Solo notificación al fallar la carga (sin modal de «carpeta raíz»).
  if(typeof notif==='function')notif(msg,'err');
  else if(typeof confirmPrecaucion==='function'){
    confirmPrecaucion({
      title:esPerm?'Sin permisos de Drive':'Error al subir a Drive',
      message:msg,
      detail:raw&&!esPerm?raw.slice(0,180):'',
      confirmLabel:'Entendido',
      hideCancel:true,
      tone:'warn'
    },function(){});
  }
}

/** Tras guardar/activar usuario: intenta compartir carpetas raíz Drive como editor. */
async function syncDriveEditorTrasUsuarioAutorizado(email,uLike,opts){
  opts=opts||{};
  email=String(email||'').trim().toLowerCase();
  if(!email)return;
  const u=uLike||(typeof getUsuarioAutorizadoByEmail==='function'?getUsuarioAutorizadoByEmail(email):null)||{email:email,activo:true,rol:'responsables'};
  if(typeof driveUsuarioNecesitaEditorRaiz==='function'&&!driveUsuarioNecesitaEditorRaiz(u))return;
  if(typeof driveGrantEditorRootsForEmail!=='function')return;
  try{
    const r=await driveGrantEditorRootsForEmail(email);
    if(r&&r.ok){
      if(!opts.silent&&typeof notif==='function')
        notif('Drive: acceso editor en carpetas raíz otorgado a '+email,'ok');
      return;
    }
    if(r&&r.reason==='sin_token_owner'){
      if(!opts.silent&&typeof confirmPrecaucion==='function'){
        confirmPrecaucion({
          title:'Permiso Drive no automático',
          message:'Usuario guardado. No se pudo compartir Drive automáticamente. Conecte Gmail de Secretaría o comparta la carpeta raíz a mano.',
          confirmLabel:'Entendido',
          hideCancel:true,
          requireAck:true,
          tone:'warn'
        },function(){});
      }else if(!opts.silent&&typeof notif==='function')
        notif('Usuario guardado. No se pudo compartir Drive automáticamente (conecte Gmail de Secretaría o hágalo a mano en la carpeta raíz).','warn');
      return;
    }
    if(!opts.silent&&typeof confirmPrecaucion==='function'){
      confirmPrecaucion({
        title:'Permiso Drive no automático',
        message:'Usuario guardado. Falló el permiso automático en Drive. El administrador debe compartir la carpeta raíz a mano.',
        confirmLabel:'Entendido',
        hideCancel:true,
        requireAck:true,
        tone:'warn'
      },function(){});
    }else if(!opts.silent&&typeof notif==='function')
      notif('Usuario guardado. Falló el permiso automático en Drive — el administrador debe compartir la carpeta raíz a mano.','warn');
  }catch(err){
    console.warn('syncDriveEditorTrasUsuarioAutorizado:',err);
    if(!opts.silent&&typeof notif==='function')
      notif('Usuario guardado. No se pudo sincronizar permisos Drive automáticamente.','warn');
  }
}

async function syncDriveRevokeTrasUsuarioAutorizado(email,opts){
  opts=opts||{};
  email=String(email||'').trim().toLowerCase();
  if(!email||typeof driveRevokeEditorRootsForEmail!=='function')return;
  try{
    const r=await driveRevokeEditorRootsForEmail(email);
    if(r&&r.ok){
      if(!opts.silent&&typeof notif==='function')
        notif('Drive: permisos de carpeta raíz revocados para '+email,'ok');
      return;
    }
    if(r&&r.reason==='sin_token_owner'&&!opts.silent&&typeof notif==='function')
      notif('Usuario actualizado. Revogue a mano el acceso Drive en la carpeta raíz si aplica (conecte Gmail de Secretaría para automatizarlo).','warn');
  }catch(err){
    console.warn('syncDriveRevokeTrasUsuarioAutorizado:',err);
  }
}
function submitEnviarSoporteVerificacion(expId,taskId){
  const cmt=String((document.getElementById('enviar-cmt-opcional')||{}).value||'').trim();
  const adj=collectEnviarAdjuntos();
  const reqEl=document.getElementById('enviar-requiere-link');
  const requiereLink=reqEl&&reqEl.value==='1';
  let e=getExpById(expId);
  let t=e?getTaskFromExp(e,taskId):null;
  if(!t&&typeof getActLibreById==='function')t=getActLibreById(taskId);
  if(!t&&typeof getActLibreByCodigo==='function')t=getActLibreByCodigo(expId);
  if(t&&t.sinExpediente){
    expId=t.codigo||expId;
    e=null;
  }
  // Proxy mínimo para Drive cuando es actividad sin expediente
  const eDrive=e||(t&&t.sinExpediente?{
    _exp:t.codigo||expId,
    _fecha:typeof hoy==='function'?hoy():new Date().toISOString().slice(0,10),
    _depto:t.depto||'guaviare',
    _sin_expediente:true,
    _pn_nombre:'Sin expediente',
    _drive_folder_id:t._drive_folder_id||'',
    _drive_folder_link:t._drive_folder_link||''
  }:null);
  // Flujo PQRSD: por tipo de expediente o por actividad «Atender PQRSD…»
  const esPqrsExp=!!(e&&typeof esPqrsSecretaria==='function'&&esPqrsSecretaria(e));
  const esPqrs=esPqrsExp||!!(e&&t&&taskEsAtenderPqrs(t,e));
  let pq=null;
  if(esPqrs){
    pq=collectPqrsEntregaDatos(expId);
    if(!pq)return;
  }
  const runSubmit=function(driveArchivos){
    if(!enviarTaskPorVerificar(expId,taskId,adj.links,cmt,requiereLink,driveArchivos||[]))return;
    if(esPqrs&&pq){
      if(!pq.adj.links.length){
        const t2=getTaskFromExp(e,taskId)||t;
        const activo=getSoporteActivo(t2);
        if(activo&&(activo.url||activo.preview)&&!activo.local)pq.adj.links=[activo.url||activo.preview];
      }
      const adjDocumentos=pq.adj.links.map(lnk=>({nombre:'Link Drive',driveLink:lnk,tipo:'link'}));
      // Include Drive-uploaded files with fileId for later renaming by NCA
      (driveArchivos||[]).forEach(function(da){
        if(da&&da.driveLink&&!adjDocumentos.find(function(x){return x.driveLink===da.driveLink;})){
          const esAnexo=!!(da.esAnexo||da.tipo==='anexo_respuesta');
          adjDocumentos.push({
            nombre:esAnexo?('Anexo '+(da.anexo_n||da.nombre||'')):('Proyección de respuesta'),
            driveLink:da.driveLink,
            previewLink:da.previewLink||da.driveLink||'',
            fileId:da.fileId||da.driveFileId||'',
            tipo:esAnexo?'anexo_respuesta':'drive',
            es_anexo:esAnexo,
            anexo_n:esAnexo?(da.anexo_n||null):null,
            driveFilename:da.driveFilename||da.nombre||'',
            driveEstado:da.driveEstado||'revision'
          });
        }
      });
      const canalFinal=pq.tipo===PQRS_WF_TIPO.INFORMATIVA?'':pq.canal;
      guardarPqrsRespuestaDatos(e,{fechaResp:pq.fechaResp,oficioExt:pq.oficioExt,cuerpo:pq.cuerpo,tipo:pq.tipo,canal:canalFinal,nota:cmt,adj:pq.adj,archivos:adjDocumentos,emailTo:pq.emailTo,emailCc:pq.emailCc,emailBcc:pq.emailBcc,emailSubject:pq.emailSubject,notificarPor:pq.notificarPor},false);
      persistExpedienteGranular(e,false);
      renderPqrsOficinaInbox();
      renderSecretariaPqrs();
      notif(pq.tipo===PQRS_WF_TIPO.INFORMATIVA?'ℹ️ Respuesta informativa enviada a revisión del encargado':'📤 Respuesta enviada a revisión del encargado NCA','ok');
    }
    closeTaskModal();
  };
  const allUpload=[].concat(adj.files||[],adj.anexos||[]);
  const preUploaded=adj.preUploaded||[];
  const canUploadPqrs=esPqrs&&typeof driveUploadPqrsExpediente==='function';
  const canUploadExp=!esPqrs&&eDrive&&typeof _driveExpedienteEsGuaviare==='function'&&_driveExpedienteEsGuaviare(eDrive)&&typeof driveUploadExpedienteActividad==='function';
  if(!allUpload.length&&preUploaded.length){
    runSubmit(preUploaded);
    return;
  }
  if(allUpload.length&&(canUploadPqrs||canUploadExp)){
    (typeof sstSolicitarGmailParaAdjuntar==='function'?sstSolicitarGmailParaAdjuntar():Promise.resolve(true)).then(function(ok){
      if(!ok)return;
      const rep=responsableActivo||taskComentarioAutor();
      const total=allUpload.length;
      if(typeof sstCargaShow==='function'){
        sstCargaShow({
          title:total>1?'Cargando documentos':'Cargando documento',
          message:esPqrs?'Subiendo a carpeta PQRSD institucional…':(eDrive&&eDrive._sin_expediente?'Subiendo a carpeta de actividad (sin expediente)…':'Subiendo al Drive de expedientes…'),
          sub:total>1?('0 de '+total+' archivos'):'Preparando envío…',
          pct:0
        });
      }
      (async function(){
      try{
        // PQRSD: no borrar versiones anteriores en Drive — se conservan para comparar con la nueva entrega
        if(t&&typeof drivePurgeTaskInstitutionalSoportes==='function'&&!esPqrs)await drivePurgeTaskInstitutionalSoportes(t);
        const uploaded=[];
        let anexoSeq=0;
        for(let i=0;i<allUpload.length;i++){
          const f=allUpload[i];
          let pref=f.nombre;
          if(f.esAnexo){
            anexoSeq++;
            pref='anexo-'+anexoSeq+'-'+(f.nombre||'doc');
          }
          if(typeof sstCargaProgress==='function'){
            sstCargaProgress(Math.round((i/total)*90), 'Subiendo «'+(f.nombre||'archivo')+'» ('+(i+1)+' de '+total+')…');
          }
          // PQRSD → árbol PQRSD; trámites / sin expediente → Drive expedientes (ACT- o EXP-)
          const up=esPqrs
            ?await driveUploadPqrsExpediente(f.blob,pref,f.tipo,e,{
                label:f.esAnexo?('Anexo '+anexoSeq):'Respuesta',
                uploadTarget:'respuesta',
                driveName:undefined
              })
            :await driveUploadExpedienteActividad(f.blob,pref,f.tipo,eDrive,t,rep,'revision');
          if(up){
            if(!up.driveFileId&&up.fileId)up.driveFileId=up.fileId;
            if(!up.driveFilename&&up.nombre)up.driveFilename=up.nombre;
            if(!up.driveEstado)up.driveEstado='revision';
            if(up.driveInstitutional==null)up.driveInstitutional=true;
            up.esAnexo=!!f.esAnexo;
            if(f.esAnexo){
              up.tipo='anexo_respuesta';
              up.es_anexo=true;
              up.anexo_n=anexoSeq;
              up.nombre='Anexo '+anexoSeq;
              up.labelAnexo='Anexo '+anexoSeq;
            }else{
              up.nombre=up.nombre||'Proyección de respuesta';
              up.labelProyeccion='Proyección de respuesta';
            }
            uploaded.push(up);
          }
        }
        // Persistir carpeta Drive en actividad libre
        if(t&&t.sinExpediente&&eDrive&&eDrive._drive_folder_id){
          t._drive_folder_id=eDrive._drive_folder_id;
          t._drive_folder_link=eDrive._drive_folder_link||'';
        }
        if(typeof sstCargaProgress==='function')sstCargaProgress(95,'Registrando entrega…');
        if(e&&typeof persistExpedienteGranular==='function')await persistExpedienteGranular(e,false);
        else if(typeof persistExpLocal==='function')persistExpLocal();
        if(typeof sstCargaDone==='function')sstCargaDone({holdMs:220});
        runSubmit(uploaded.concat(preUploaded));
      }catch(err){
        console.warn('submitEnviarSoporteVerificacion drive:',err);
        if(typeof sstCargaHide==='function')sstCargaHide();
        alertErrorDriveAdjunto(err);
      }
    })();
    });
    return;
  }
  if(allUpload.length){
    notif(esPqrs
      ?'No se pudo subir a la carpeta PQRSD. Conecte Gmail/Drive e intente de nuevo.'
      :'La subida automática al Drive solo aplica en Guaviare. Use enlace manual o comentario.','warn');
    return;
  }
  runSubmit([]);
}
function renderEnviarPanelHtml(expId,taskId,t,modo){
  const traslado=modo==='reporteTrasladado'||taskRecibidaPorTraslado(t);
  const nuevaEntrega=modo==='nuevaEntrega'||estadoTask(t)==='Por corregir'||(typeof taskPuedeCorregirSinRevision==='function'&&taskPuedeCorregirSinRevision(t));
  const finalizarEnc=modo==='finalizarEncargado';
  const autoEnc=modo==='autoentregaEncargado';
  const eExp=getExpById(expId);
  const esPqrsEntrega=eExp&&taskEsAtenderPqrs(t,eExp);
  const corrVoluntaria=typeof taskPuedeCorregirSinRevision==='function'&&taskPuedeCorregirSinRevision(t);
  const soportes=t.soportes||[];
  const hasSop=soportes.length>0;
  const ultima=hasSop?soportes[soportes.length-1]:null;
  const sol=getTaskSolicitudPendiente(t);
  let h='<div class="task-cmt-form task-enviar-unificado" id="task-enviar-panel" style="padding:.65rem;border-radius:var(--r);background:var(--sf2)">';
  h+='<input type="hidden" id="enviar-requiere-link" value="0">';
  h+='<input type="hidden" id="enviar-modo-nueva" value="'+(nuevaEntrega?'1':'0')+'">';
  h+='<input type="hidden" id="enviar-modo-traslado" value="'+(traslado&&!nuevaEntrega?'1':'0')+'">';
  h+=renderEntregaHistorialHtml(t);
  h+='<div style="font-size:13px;font-weight:600;margin-bottom:6px">'+(autoEnc?'📤 Autoentrega (encargado)':finalizarEnc?'✓ Finalizar actividad (encargado del departamento)':corrVoluntaria?'📤 Corregir entrega (aún sin revisión)':nuevaEntrega?'📤 Nueva entrega':'📤 Entrega de actividad')+'</div>';
  if(sol){
    h+='<div style="font-size:12px;color:var(--tx2);margin-bottom:8px;padding:8px;background:var(--orl);border-radius:var(--r)">'+
      'Tiene una solicitud de <strong>'+(sol.tipo==='traslado'?'traslado':'eliminación')+'</strong> pendiente en el chat — espere respuesta del departamento.</div>';
  }else if(autoEnc){
    h+='<div style="font-size:12px;color:var(--tx2);margin-bottom:8px;padding:6px 8px;background:#0d5c2e12;border-radius:var(--r);border:1px solid #0d5c2e">Como encargado, usted se revisa a sí mismo: la entrega <strong>no pasa por «Por revisar»</strong>. Tras adjuntar el documento, elija el flujo: <strong>Por imprimir → Por firmar → Firmados → Por notificar</strong> (o cierre sin firma si no aplica).</div>';
  }else if(finalizarEnc){
    h+='<div style="font-size:12px;color:var(--tx2);margin-bottom:8px;padding:6px 8px;background:var(--sf);border-radius:var(--r);border:1px solid var(--bd)">Como encargado del departamento, al finalizar la actividad queda <strong>cerrada directamente</strong>. Puede adjuntar soporte opcional.</div>';
  }else if(corrVoluntaria){
    h+='<div style="font-size:12px;color:var(--tx2);margin-bottom:8px;padding:6px 8px;background:var(--sf);border-radius:var(--r);border:1px solid var(--bd)">'+
      '<strong>Corrección voluntaria</strong> — el encargado aún no ha revisado. Puede reemplazar el documento o ajustar el comentario. Si ya lo revisaron, esta opción se desactiva.'+
      (hasSop&&ultima?' Versión actual: v'+ultima.version+'.':'')+
    '</div>';
  }else if(nuevaEntrega){
    h+='<div style="font-size:12px;color:var(--tx2);margin-bottom:8px;padding:6px 8px;background:var(--sf);border-radius:var(--r);border:1px solid var(--bd)">'+
      '<strong>Nueva entrega</strong> — el comentario es sobre <strong>esta entrega</strong> (no el chat de la actividad). Enlace de Drive y/o comentario; sin adjunto, comentario obligatorio.'+
      (hasSop&&ultima?' Versión anterior: v'+ultima.version+'.':'')+
    '</div>';
  }else if(traslado){
    h+='<div style="font-size:12px;color:var(--tx2);margin-bottom:8px;padding:6px 8px;background:var(--sf);border-radius:var(--r);border:1px solid var(--bd)">'+
      'Entrega tras traslado — comentario sobre <strong>esta entrega</strong>. Sin enlace Drive, comentario obligatorio.'+
    '</div>';
  }else if(esPqrsEntrega){
    h+='<div style="font-size:12px;color:var(--tx2);margin-bottom:8px;padding:6px 8px;background:var(--sf);border-radius:var(--r);border:1px solid var(--bd)">'+
      'Adjunte el documento de respuesta (se sube al Drive institucional) y/o un comentario sobre esta entrega.'+
    '</div>';
  }else{
    h+='<div style="font-size:12px;color:var(--tx2);margin-bottom:8px;padding:6px 8px;background:var(--sf);border-radius:var(--r);border:1px solid var(--bd)">'+
      'Adjunte enlace de Google Drive y/o comentario sobre esta entrega.'+
    '</div>';
  }
  if(esPqrsEntrega&&!sol)h+=renderPqrsEntregaCamposHtml(eExp);
  if(!sol){
    const esLibreEnv=!!(t&&t.sinExpediente);
    const showDriveUp=(eExp&&typeof _driveExpedienteEsGuaviare==='function'&&_driveExpedienteEsGuaviare(eExp))
      ||(esLibreEnv&&typeof DRIVE_INST_DEPTOS!=='undefined'&&DRIVE_INST_DEPTOS.has(String(t.depto||'guaviare')));
    if(showDriveUp&&!esPqrsEntrega){
      const envCtx=typeof sstFileEnviarCtxKey==='function'?sstFileEnviarCtxKey(expId,taskId):('enviar-soporte:'+expId+':'+taskId);
      const getCtx=typeof sstFileUploadCtxForExpTask==='function'?sstFileUploadCtxForExpTask(expId,taskId):null;
      h+='<div style="margin-bottom:8px"><label style="font-size:11px;font-weight:600;color:var(--tx3)">Subir archivo (Drive institucional — opcional)</label>'+
        (typeof sstFilePickBlock==='function'
          ?sstFilePickBlock({inputId:'enviar-adj-file',listId:'enviar-adj-file-list',ctxKey:envCtx,label:'Seleccionar archivo',getUploadCtx:getCtx})
          :('<input type="file" id="enviar-adj-file" accept=".pdf,.doc,.docx,image/*,video/*" style="font-size:12px;width:100%;margin-top:4px">'))+
        '<div style="font-size:10px;color:var(--tx3);margin-top:2px">Documento principal. También puede pegar un enlace externo abajo.</div></div>'+
        '<div style="margin-bottom:8px"><label style="font-size:11px;font-weight:600;color:var(--tx3)">Anexos (opcionales)</label>'+
        (typeof sstFilePickBlock==='function'
          ?sstFilePickBlock({inputId:'enviar-anexos-file',listId:'enviar-anexos-list',ctxKey:envCtx,multi:true,label:'Seleccionar anexos',getUploadCtx:getCtx})
          :('<input type="file" id="enviar-anexos-file" multiple accept=".pdf,.doc,.docx,image/*,video/*" style="font-size:12px;width:100%;margin-top:4px">'))+
        '</div>';
    }
    // Los enlaces externos de Drive no aplican para entregas de PQRSD:
    // los archivos se cargan al Drive institucional y se adjuntan al enviar la respuesta.
    if(!esPqrsEntrega){
      h+='<div style="font-size:11px;font-weight:600;color:var(--tx3);margin-bottom:4px">'+(finalizarEnc||autoEnc?'Soporte (link Drive)':'Enlaces Google Drive externos (opcionales)')+'</div>'+
        '<div id="enviar-adjuntos-rows"></div>'+
        '<div class="fx" style="gap:6px;margin-bottom:8px;flex-wrap:wrap">'+
          '<button type="button" class="btn bsm" onclick="addEnviarAdjuntoRow()">+ Link Drive</button>'+
        '</div>'+
        '<div style="font-size:10px;color:var(--tx3);margin-bottom:8px">Enlace externo de Google Drive (archivos fuera del Drive institucional). También puede incluir el link en el comentario.</div>';
    }else{
      h+='<div id="enviar-adjuntos-rows" style="display:none"></div>';
    }
    h+='<textarea id="enviar-cmt-opcional" placeholder="'+(finalizarEnc?'Comentario opcional al finalizar…':autoEnc?'Comentario sobre esta autoentrega (opcional)…':esPqrsEntrega?'Comentario u observaciones sobre esta entrega…':'Comentario sobre esta entrega (obligatorio si no adjunta link Drive)…')+'" style="min-height:72px;padding:6px;border:1px solid var(--bd);border-radius:var(--r);font-size:12px;font-family:\'DM Sans\',sans-serif;margin-bottom:8px;width:100%"></textarea>';
    if(autoEnc){
      const eid=escAttr(expId),tid=escAttr(taskId);
      h+='<div style="font-size:12px;font-weight:600;margin:4px 0 6px">Tras la entrega, el flujo será:</div>'+
        '<div class="fx" style="gap:8px;flex-wrap:wrap">'+
        '<button type="button" class="btn bsm" style="background:#1a7a4a;color:#fff;border-color:#1a7a4a" onclick="submitAutoentregaEncargado(\''+eid+'\',\''+tid+'\',\'imprimir\')">🖨 Entregar → Por imprimir</button>'+
        '<button type="button" class="btn bsm" style="background:#0d5c2e;color:#fff;border-color:#0d5c2e" onclick="submitAutoentregaEncargado(\''+eid+'\',\''+tid+'\',\'firma\')">🖊 Entregar → Por firmar</button>'+
        '<button type="button" class="btn bsm" style="background:#0f766e;color:#fff;border-color:#0f766e" onclick="submitAutoentregaEncargado(\''+eid+'\',\''+tid+'\',\'notificar\')">⬆ Entregar → Por notificar</button>'+
        '<button type="button" class="btn bsm bp" onclick="submitAutoentregaEncargado(\''+eid+'\',\''+tid+'\',\'cerrar\')">✓ Entregar y cerrar (sin firma)</button>'+
        '<button type="button" class="btn bsm" onclick="closeTaskModal()">Cancelar</button></div>';
    }else{
      h+='<div class="fx" style="gap:8px"><button type="button" class="btn bsm bp" onclick="'+(finalizarEnc?'submitFinalizarEncargado':'submitEnviarSoporteVerificacion')+'(\''+escAttr(expId)+'\',\''+escAttr(taskId)+'\')">'+(finalizarEnc?'✓ Finalizar actividad':nuevaEntrega?'📤 Enviar nueva entrega':esPqrsEntrega?'📤 Enviar a revisión del encargado':'📤 Enviar para verificación')+'</button>'+
        '<button type="button" class="btn bsm" onclick="closeTaskModal()">Cancelar</button></div>';
    }
  }else{
    h+='<div class="fx" style="gap:8px"><button type="button" class="btn bsm" onclick="closeTaskModal()">Cerrar</button></div>';
  }
  h+='</div>';
  return h;
}
function openEnviarSoporteModal(expId,taskId,modo){
  let e=getExpById(expId),t=getTaskFromExp(e,taskId);
  if(!t){t=normalizeActLibre(getActLibreById(taskId));if(t){expId=t.codigo;e=null;}}
  if(!t)return;
  if(!modo)modo=resolveModoEnviar(t,null);
  const ov=document.getElementById('task-modal-overlay');
  const tit=document.getElementById('task-modal-title');
  const body=document.getElementById('task-modal-body');
  const modal=ov?ov.querySelector('.task-modal'):null;
  if(!ov||!body)return;
  if(tit)tit.textContent=(modo==='nuevaEntrega'?'Nueva entrega':modo==='reporteTrasladado'?'Reportar actividad trasladada':'Entrega')+' · '+(t.codigo||expId);
  if(modal){modal.classList.remove('task-modal-wide');modal.classList.add('enviar-modal-only');}
  const est=estadoTask(t),st=taskEstadoStyle(est);
  const eExp=e||getExpById(expId);
  const esPqrsEntrega=eExp&&taskEsAtenderPqrs(t,eExp);
  body.innerHTML='<div style="margin-bottom:.75rem"><span class="bdg" style="background:'+st.bg+';color:'+st.fg+'">'+estadoTaskLabel(t)+'</span></div>'+
    (esPqrsEntrega?'':'<div style="font-size:13px;margin-bottom:.75rem">'+escAttr(t.desc||t.actividad||'Actividad')+'</div>')+
    renderEnviarPanelHtml(expId,taskId,t,modo);
  ov.classList.add('on');
  window._taskModalCtx={expId,taskId,mode:'enviar',actLibre:!!t.sinExpediente};
  if(typeof sstFileStagingReset==='function'&&typeof sstFileEnviarCtxKey==='function'){
    sstFileStagingReset(sstFileEnviarCtxKey(expId,taskId));
    if(typeof sstFileInitPick==='function'){
      sstFileInitPick('enviar-adj-file');
      sstFileInitPick('enviar-anexos-file');
    }
  }
  if(esPqrsEntrega){
    setTimeout(function(){
      if(typeof pqrsEntregaRefreshUi==='function')pqrsEntregaRefreshUi();
      const tipo=String((document.getElementById('pqrs-resp-tipo')||{}).value||'');
      // Solo mensaje simple lleva plantilla en entrega; oficio: N° + archivo + anexos (plantilla al notificar)
      if(tipo===PQRS_WF_TIPO.MENSAJE&&typeof pqrsAplicarPlantillaSegunTipo==='function'){
        const canal=String((document.getElementById('pqrs-resp-canal')||{}).value||'');
        if(typeof pqrsEsCanalCorreo==='function'&&pqrsEsCanalCorreo(canal))pqrsAplicarPlantillaSegunTipo(tipo,false);
      }
    },40);
  }
  setTimeout(()=>{const inp=document.getElementById('enviar-cmt-opcional');if(inp)inp.focus();},80);
}
function renderCompareVersionesPanel(t,e,taskId){
  const docs=collectDocsComparables(e,taskId,t);
  if(docs.length<2)return '<div style="font-size:12px;color:var(--tx3);padding:8px">Se necesitan al menos 2 documentos del expediente o de la actividad para comparar.</div>';
  const defA=docs[Math.max(0,docs.length-2)].id;
  const defB=docs[docs.length-1].id;
  window._compareDocA=window._compareDocA||defA;
  window._compareDocB=window._compareDocB||defB;
  const opts=docs.map(function(d){
    const lab=String(d.label||d.titulo||'Documento');
    return '<option value="'+escAttr(d.id)+'">'+escAttr(lab)+(d.meta?' · '+escAttr(d.meta):'')+'</option>';
  }).join('');
  let h='<div class="compare-ver-sel">'+
    '<div class="fld compare-ver-fld"><label for="compare-ver-a">Documento izquierdo</label><select id="compare-ver-a" class="compare-ver-select" onchange="onCompareVerChange()">'+opts+'</select></div>'+
    '<div class="fld compare-ver-fld"><label for="compare-ver-b">Documento derecho</label><select id="compare-ver-b" class="compare-ver-select" onchange="onCompareVerChange()">'+opts+'</select></div>'+
    '<button type="button" class="btn bsm" onclick="setCompareUltimasDos()">Últimos dos</button>'+
    '<button type="button" class="btn bsm bp" id="compare-ver-expand-btn" onclick="toggleTaskViewportExpand()">⛶ Ampliar</button></div>';
  h+='<div id="compare-ver-stack" class="compare-ver-stack"></div>';
  return h;
}
function taskModalIsViewportExpanded(){
  return!!document.querySelector('#task-modal-overlay .task-modal.task-modal-viewport-expand');
}
function syncTaskViewportExpandBtns(on){
  const label=on?'⛶ Reducir':'⛶ Ampliar';
  ['compare-ver-expand-btn','pqrs-sol-resp-expand-btn','task-doc-expand-btn'].forEach(function(id){
    const b=document.getElementById(id);
    if(b)b.textContent=label;
  });
}
/** Amplía el modal casi al tamaño de la ventana del navegador (Documento / Solicitud·Respuesta / Comparar). */
function toggleTaskViewportExpand(){
  const modal=document.querySelector('#task-modal-overlay .task-modal');
  if(!modal)return;
  const on=modal.classList.toggle('task-modal-viewport-expand');
  modal.classList.toggle('task-modal-compare-expand',on);
  document.body.classList.toggle('compare-docs-expanded',on);
  document.body.classList.toggle('task-doc-viewport-expanded',on);
  const stack=document.getElementById('compare-ver-stack');
  if(stack)stack.classList.toggle('compare-ver-stack-expand',on);
  const pqrsStack=document.getElementById('pqrs-sol-resp-compare-stack');
  if(pqrsStack)pqrsStack.classList.toggle('compare-pqrs-stack-expand',on);
  syncTaskViewportExpandBtns(on);
  const ctx=window._taskModalCtx||{};
  const e=typeof getExpById==='function'?getExpById(ctx.expId):null;
  const t=e&&typeof getTaskFromExp==='function'?getTaskFromExp(e,ctx.taskId):null;
  if(document.getElementById('compare-ver-stack')&&typeof renderCompareVerStack==='function')renderCompareVerStack(t,e);
  if(document.getElementById('pqrs-sol-resp-compare-stack')&&typeof renderPqrsSolRespCompareStack==='function')renderPqrsSolRespCompareStack(e,t);
}
function toggleCompareVerExpand(){return toggleTaskViewportExpand();}
window.toggleTaskViewportExpand=toggleTaskViewportExpand;
window.toggleCompareVerExpand=toggleCompareVerExpand;
window.taskModalIsViewportExpanded=taskModalIsViewportExpanded;
function setCompareUltimasDos(){
  const ctx=window._taskModalCtx||{};
  const e=getExpById(ctx.expId);
  const t=getTaskFromExp(e,ctx.taskId);
  const docs=collectDocsComparables(e,ctx.taskId,t);
  if(docs.length<2)return;
  window._compareDocA=docs[docs.length-2].id;
  window._compareDocB=docs[docs.length-1].id;
  const sa=document.getElementById('compare-ver-a'),sb=document.getElementById('compare-ver-b');
  if(sa)sa.value=window._compareDocA;
  if(sb)sb.value=window._compareDocB;
  renderCompareVerStack(t,e);
}
function onCompareVerChange(){
  window._compareDocA=(document.getElementById('compare-ver-a')||{}).value;
  window._compareDocB=(document.getElementById('compare-ver-b')||{}).value;
  const ctx=window._taskModalCtx||{};
  const e=getExpById(ctx.expId);
  const t=getTaskFromExp(e,ctx.taskId);
  if(t||e)renderCompareVerStack(t,e);
}
function renderCompareNotasHtml(t,sopId){
  const notas=notasDocForSoporte(t,sopId);
  if(!notas.length)return '<div class="compare-ver-obs" style="font-size:11px;color:var(--tx3)">Sin observaciones en esta versión</div>';
  const sorted=[...notas].sort((a,b)=>(a.pin||99)-(b.pin||99));
  return '<div class="compare-ver-obs">'+sorted.map(n=>{
    const loc=n.pagina?('Pág. '+escAttr(n.pagina)+' '):'';
    const pin=n.pin?('#'+n.pin+' '):'';
    return '<div class="compare-ver-obs-item"><strong>'+pin+loc+'</strong>'+escAttr((n.texto||'').slice(0,160))+
      (n.ref?' <span style="color:var(--tx3)">('+escAttr(n.ref)+')</span>':'')+'</div>';
  }).join('')+'</div>';
}
function renderCompareDocSideHtml(doc,sideLbl,t){
  if(!doc)return'<div class="compare-ver-block"><div class="lbl">'+escAttr(sideLbl)+'</div><div style="padding:8px;font-size:12px">Sin documento</div></div>';
  const sopLike={preview:doc.preview,url:doc.url,mime:doc.mime,local:doc.local,version:''};
  const expanded=typeof taskModalIsViewportExpanded==='function'&&taskModalIsViewportExpanded();
  let vista='';
  if(soporteTieneVista(sopLike)){
    vista=soporteEsImagen(sopLike)
      ?'<img src="'+escAttr(doc.preview||doc.url)+'" alt="'+escAttr(doc.label)+'" style="width:100%;'+(expanded?'max-height:88vh':'max-height:420px')+';object-fit:contain;display:block">'
      :'<iframe sandbox="allow-scripts allow-same-origin allow-popups" src="'+escAttr(doc.preview||doc.url)+'" title="'+escAttr(doc.label)+'"'+(expanded?' class="compare-iframe-expand"':'')+'></iframe>';
  }else{
    vista='<div style="padding:12px;font-size:12px;color:var(--tx3)">Sin vista previa — <a href="'+escAttr(doc.url||'#')+'" target="_blank" rel="noopener">abrir enlace</a></div>';
  }
  const notas=doc.soporteId&&t?renderCompareNotasHtml(t,doc.soporteId):'';
  return '<div class="compare-ver-block"><div class="lbl">'+escAttr(sideLbl)+' · '+escAttr(doc.label)+(doc.meta?' · '+escAttr(doc.meta):'')+'</div>'+vista+notas+'</div>';
}
function renderCompareVerStack(t,e){
  const stack=document.getElementById('compare-ver-stack');
  if(!stack)return;
  const ctx=window._taskModalCtx||{};
  e=e||getExpById(ctx.expId);
  const docs=collectDocsComparables(e,ctx.taskId,t);
  if(docs.length<2){stack.innerHTML='';return;}
  const a=docs.find(x=>x.id===window._compareDocA)||docs[docs.length-2];
  const b=docs.find(x=>x.id===window._compareDocB)||docs[docs.length-1];
  stack.innerHTML=renderCompareDocSideHtml(a,'◀ Izquierda',t)+renderCompareDocSideHtml(b,'Derecha ▶',t);
}
function resetTaskPorCorregir(t,nota,reportadoPor){
  // Conservar el plazo/vencimiento original al devolver
  const venceOrig=t.vence||'';
  const plazoOrig=t.plazoDias;
  reportadoPor=reportadoPor||getUltimoReportadoPor(t);
  if(taskEsMultiAsignada(t)&&t.entregaModo==='individual'&&reportadoPor){
    const a=getAsignado(t,reportadoPor);
    if(a){a.fechaReportada='';a.fechaAtendida='';a.estado='por_corregir';}
    syncTaskAggregateState(t);
  }else{
    t.fechaReportada='';
    t.fechaAtendida='';
    t.estado='Por corregir';
    (t.asignados||[]).forEach(a=>{
      if(a.estado==='por_verificar'||a.estado==='atendido'){a.fechaReportada='';a.fechaAtendida='';a.estado='por_corregir';}
      else if(a.estado!=='atendido')a.estado='por_corregir';
    });
  }
  if(venceOrig)t.vence=venceOrig;
  if(plazoOrig!=null&&plazoOrig!=='')t.plazoDias=plazoOrig;
  t.ultimaRevisionDepto={tipo:'corregir',fecha:hoy(),ts:Date.now(),por:taskComentarioAutor(),nota:nota||''};
  t.historial.push({tipo:'ajuste_soporte',fecha:hoy(),ts:Date.now(),por:taskComentarioAutor(),nota:nota||'',reportadoPor:reportadoPor||''});
}
function solicitarAjusteSoporte(expId,taskId,nota){
  return mutateTask(expId,taskId,t=>resetTaskPorCorregir(t,nota||''));
}
async function driveRenombrarSoporteActivoExp(expId,taskId,newEstado){
  let t=typeof getTaskAny==='function'?getTaskAny(expId,taskId):null;
  if(!t){
    const e0=getExpById(expId);
    t=getTaskFromExp(e0,taskId);
  }
  if(!t||typeof driveRenameExpedienteSoporte!=='function')return false;
  const esLibre=!!t.sinExpediente||(typeof isActLibreRef==='function'&&isActLibreRef(expId,taskId));
  const e=esLibre
    ?(typeof tramiteFirmaExpCtx==='function'?tramiteFirmaExpCtx(t,expId):{
        _exp:t.codigo||expId,_depto:t.depto||'guaviare',_sin_expediente:true,
        _drive_folder_id:t._drive_folder_id||'',_drive_folder_link:t._drive_folder_link||''
      })
    :getExpById(expId);
  if(!e)return false;
  normalizeTask(t);
  const rep=getUltimoReportadoPor(t)||'';
  const list=(t.soportes||[]).filter(function(s){
    if(!s||!s.driveFileId||s.driveInstitutional===false)return false;
    const est=String(s.driveEstado||'').toLowerCase();
    // Renombrar borradores internos; no tocar ya aprobados/por notificar si el destino es el mismo
    if(newEstado==='aprobado')return !est||est==='revision'||est==='por_firma'||est==='por_firmar'||est==='vital_gestion'||est==='acorregir'||est==='corregir';
    return true;
  });
  if(!list.length){
    const activo=getSoporteActivo(t);
    if(activo&&activo.driveFileId)list.push(activo);
  }
  let any=false;
  for(let i=0;i<list.length;i++){
    const s=list[i];
    const ok=await driveRenameExpedienteSoporte(s,newEstado,e,t,rep||s.autor||'');
    if(ok)any=true;
  }
  if(any){
    if(esLibre){
      try{
        if(typeof persistActividadesLibresFirestore==='function')await persistActividadesLibresFirestore();
        else if(typeof saveGlobalFirestore==='function')await saveGlobalFirestore();
      }catch(err){console.warn('drive rename libre persist:',err);}
      try{persistExpLocal();}catch(err){}
    }else await persistExpedienteGranular(e,false);
  }
  return any;
}
function devolverTaskAlResponsable(expId,taskId,nota){
  // Solo marca «por corregir» en sistema (historial/campanita). No notificar por correo al responsable.
  if(solicitarAjusteSoporte(expId,taskId,nota||'Devuelta al responsable')){
    if(typeof driveRenombrarSoporteActivoExp==='function'){
      driveRenombrarSoporteActivoExp(expId,taskId,'corregir').catch(function(err){console.warn('drive rename corregir:',err);});
    }
    notif('Actividad devuelta — queda por corregir','ok');
    closeTaskModal();
    renderBandejaDepto();
    if(document.getElementById('pg-act')&&document.getElementById('pg-act').classList.contains('on'))renderActividades();
    if(window._conPanelEditMode&&document.getElementById('con-side-panel')&&document.getElementById('con-side-panel').classList.contains('on')&&window._conPanelActive===expId){
      renderConSidePanel();
    }else if(editId===expId){
      const e=getExpById(expId);
      if(e){setCfgPtr(e._depto||getDeptoOperativo());renderFormulario(e._tramite,e,'con-side-form-wrap');}
    }
    return true;
  }
  return false;
}

/** Quién puede borrar la entrega (vuelve a Por ejecutar como si no hubiera entregado). */
function puedeEliminarEntregaActividad(expId,taskId){
  const t=typeof getTaskAny==='function'?getTaskAny(expId,taskId):null;
  if(!t||t.eliminada)return false;
  if(typeof taskFirmaWfActiva==='function'&&taskFirmaWfActiva(t))return false;
  if(typeof taskEnFlujoFirmaTramite==='function'&&taskEnFlujoFirmaTramite(t))return false;
  if(typeof getTaskRevisionDepto==='function'&&getTaskRevisionDepto(t))return false;
  const e=typeof getExpById==='function'?getExpById(expId):null;
  const esPqrsRev=!!(e&&typeof taskEsAtenderPqrs==='function'&&taskEsAtenderPqrs(t,e)
    &&typeof pqrsEnRevisionNca==='function'&&pqrsEnRevisionNca(e));
  const est=estadoTask(t);
  const pend=est==='Por verificar'||(typeof taskPendienteVerificacion==='function'&&taskPendienteVerificacion(t))||esPqrsRev;
  if(!pend)return false;
  if(e&&typeof esPqrsSecretaria==='function'&&esPqrsSecretaria(e)&&typeof taskEsAtenderPqrs==='function'&&taskEsAtenderPqrs(t,e)&&!esPqrsRev){
    const f=typeof pqrsWorkflowFase==='function'?pqrsWorkflowFase(e):'';
    if(f&&f!==PQRS_WF.PENDIENTE_REVISION&&f!==PQRS_WF.SIN_RESPUESTA&&f!==PQRS_WF.RECHAZADA){
      if(!(typeof pqrsEnRevisionNca==='function'&&pqrsEnRevisionNca(e)))return false;
    }
  }
  if(typeof esJurisdiccional==='function'&&esJurisdiccional())return false;
  if(!(typeof esModoResponsable==='function'&&esModoResponsable()))return true;
  if(esPqrsRev&&typeof taskUsuarioEsAsignado==='function'&&taskUsuarioEsAsignado(t,responsableActivo))return true;
  return typeof taskPuedeCorregirSinRevision==='function'&&taskPuedeCorregirSinRevision(t);
}
function eliminarEntregaActividadConfirm(expId,taskId){
  if(!puedeEliminarEntregaActividad(expId,taskId)){notif('No puede eliminar esta entrega','err');return;}
  const t=getTaskAny(expId,taskId);
  const lbl=(t&&(t.desc||t.actividad))||'actividad';
  const fn=function(){eliminarEntregaActividad(expId,taskId);};
  if(typeof confirmEliminar==='function'){
    confirmEliminar({
      title:'Eliminar entrega',
      message:'¿Eliminar la entrega de «'+lbl+'»?',
      detail:'La actividad volverá a Por ejecutar (según su plazo: en término, vencida, urgente o prioritaria), como si no se hubiera entregado. Se borrarán del Drive los documentos y anexos de esta entrega.',
      confirmLabel:'Sí, eliminar entrega'
    },fn);
    return;
  }
  if(confirm('¿Eliminar esta entrega? La actividad volverá a Por ejecutar y se borrarán los documentos de Drive.'))fn();
}
async function eliminarEntregaActividad(expId,taskId){
  if(!puedeEliminarEntregaActividad(expId,taskId)){notif('No puede eliminar esta entrega','err');return false;}
  let t=getTaskAny(expId,taskId);
  if(!t){notif('Actividad no encontrada','err');return false;}
  const refId=t.sinExpediente?(t.codigo||expId):expId;
  const e=t.sinExpediente?null:getExpById(refId);
  const fileIds=[];
  const pushFid=function(id){
    const fid=String(id||'').trim();
    if(fid&&fileIds.indexOf(fid)<0)fileIds.push(fid);
  };
  (t.soportes||[]).forEach(function(s){
    if(!s)return;
    pushFid(s.driveFileId||s.fileId);
  });
  let wfDocsCleared=false;
  if(e&&typeof taskEsAtenderPqrs==='function'&&taskEsAtenderPqrs(t,e)&&typeof getPqrsWorkflow==='function'){
    const wf=getPqrsWorkflow(e);
    (wf.documentos||[]).forEach(function(d){
      if(!d)return;
      pushFid(d.fileId||d.driveFileId);
    });
    wfDocsCleared=true;
  }
  const ok=mutateTask(refId,taskId,function(tk){
    normalizeTask(tk);
    migrateLegacyAsignados(tk);
    tk.soportes=[];
    tk.notasDoc=[];
    tk.fechaReportada='';
    tk.fechaAtendida='';
    tk.verificadoPor='';
    tk.ultimaRevisionDepto=null;
    tk._pqrs_proyeccion_atendida=false;
    tk._firma_proyeccion_atendida=false;
    // Quitar comentarios incluidos solo en la entrega (no el chat)
    tk.comentarios=(tk.comentarios||[]).filter(function(c){return c&&!c.incluidoEnReporte;});
    (tk.asignados||[]).forEach(function(a){
      if(!a)return;
      if(a.estado==='por_verificar'||a.estado==='por_corregir'||a.fechaReportada){
        a.fechaReportada='';
        a.fechaAtendida='';
        a.estado='pendiente';
      }
    });
    tk.estado='En ejecución';
    if(typeof syncTaskAggregateState==='function')syncTaskAggregateState(tk);
    // Si sync dejó algo raro, forzar ejecución sin reporte
    if(tk.fechaReportada)tk.fechaReportada='';
    if(tk.fechaAtendida)tk.fechaAtendida='';
    if(tk.estado==='Por verificar'||tk.estado==='Por corregir'||tk.estado==='Atendida')tk.estado='En ejecución';
    if(!Array.isArray(tk.historial))tk.historial=[];
    tk.historial.push({
      tipo:'eliminar_entrega',
      fecha:hoy(),
      ts:Date.now(),
      por:typeof taskComentarioAutor==='function'?taskComentarioAutor():(responsableActivo||''),
      nota:'Entrega eliminada — actividad vuelve a Por ejecutar (sin documentos de la entrega)'
    });
  });
  if(!ok){notif('No se pudo eliminar la entrega','err');return false;}
  if(wfDocsCleared&&e&&typeof setPqrsWorkflow==='function'){
    setPqrsWorkflow(e,{
      fase:PQRS_WF.SIN_RESPUESTA,
      documentos:[],
      cuerpo:'',
      entregado_por:'',
      revision_nca:null,
      fecha_respuesta:'',
      devolucion_director:null
    });
    if(!Array.isArray(e._pqrs_historial))e._pqrs_historial=[];
    e._pqrs_historial.push({tipo:'eliminar_entrega',fecha:hoy(),nota:'Entrega eliminada — pendiente nueva entrega',oficina:e._pqrs_oficina||'guaviare',por:responsableActivo||''});
    try{persistExpedienteGranular(e);}catch(err){console.warn('eliminarEntrega pqrs:',err);}
  }
  if(fileIds.length&&typeof driveDeleteInstitutional==='function'){
    for(let i=0;i<fileIds.length;i++){
      try{await driveDeleteInstitutional(fileIds[i]);}catch(err){console.warn('eliminarEntrega drive:',err);}
    }
  }
  notif('🗑 Entrega eliminada — la actividad vuelve a Por ejecutar','ok');
  closeTaskModal();
  try{if(typeof setActFiltro==='function')setActFiltro('pend');}catch(err){}
  if(typeof renderActividades==='function')renderActividades();
  if(typeof renderBandejaDepto==='function')renderBandejaDepto();
  if(typeof renderPqrsOficinaInbox==='function')renderPqrsOficinaInbox();
  return true;
}
window.puedeEliminarEntregaActividad=puedeEliminarEntregaActividad;
window.eliminarEntregaActividadConfirm=eliminarEntregaActividadConfirm;
window.eliminarEntregaActividad=eliminarEntregaActividad;
