function renderResponsableRegistro(){}
function migrarRevisionDeptoTask(t){
  if(!t||t.ultimaRevisionDepto)return;
  const hist=t.historial||[];
  if(estadoTask(t)==='Por corregir'){
    const u=hist.filter(h=>h.tipo==='ajuste_soporte').pop();
    if(u)t.ultimaRevisionDepto={tipo:'corregir',fecha:u.fecha||'',nota:u.nota||'',por:u.por||''};
  }else if(estadoTask(t)==='Atendida'&&(t.verificadoPor||hist.some(h=>h.tipo==='verificacion'))){
    const v=hist.filter(h=>h.tipo==='verificacion').pop();
    t.ultimaRevisionDepto={tipo:'aprobada',fecha:t.fechaAtendida||(v?v.fecha:''),nota:t.verificadoPor||(v?v.nota:'')};
  }
}
function taskHuboReporteResponsable(t){
  if(!t)return false;
  return (t.historial||[]).some(h=>h.tipo==='reenvio_verificacion')||!!t.fechaReportada||!!t.ultimaRevisionDepto;
}
function getTaskRevisionDepto(t){
  if(!t||t.eliminada||esTareaDelEncargado(t))return null;
  if(estadoTask(t)==='Por verificar')return null;
  // Devolución Director / en revisión NCA: no mostrar «✓ Aprobada»
  const eRev=typeof getExpById==='function'?getExpById(t.exp||t.codigo):null;
  if(eRev&&typeof pqrsEnRevisionNca==='function'&&pqrsEnRevisionNca(eRev))return null;
  migrarRevisionDeptoTask(t);
  if(t.ultimaRevisionDepto&&t.ultimaRevisionDepto.tipo){
    if(estadoTask(t)==='Atendida'&&t.ultimaRevisionDepto.tipo==='aprobada')return t.ultimaRevisionDepto;
    if(estadoTask(t)==='Por corregir'&&t.ultimaRevisionDepto.tipo==='corregir')return t.ultimaRevisionDepto;
  }
  if(!taskHuboReporteResponsable(t))return null;
  const hist=t.historial||[];
  if(estadoTask(t)==='Por corregir'){
    const u=hist.filter(h=>h.tipo==='ajuste_soporte').pop();
    return {tipo:'corregir',fecha:u?u.fecha:'',nota:u?u.nota:''};
  }
  if(estadoTask(t)==='Atendida'){
    const v=hist.filter(h=>h.tipo==='verificacion').pop();
    return {tipo:'aprobada',fecha:t.fechaAtendida||'',nota:t.verificadoPor||(v?v.nota:'')};
  }
  return null;
}
function taskEsReentregaTrasCorreccion(t){
  if(!t)return false;
  if(estadoTask(t)!=='Por verificar')return false;
  const hist=t.historial||[];
  const huboAjuste=hist.some(h=>h&&(h.tipo==='ajuste_soporte'||h.tipo==='revision_nca_rechazado'));
  const huboReenvio=hist.some(h=>h&&h.tipo==='reenvio_verificacion');
  return huboAjuste&&huboReenvio;
}
function taskReentregaBadgeHtml(t){
  if(!taskEsReentregaTrasCorreccion(t))return'';
  const n=(t.historial||[]).filter(h=>h&&h.tipo==='reenvio_verificacion').length;
  return '<span class="bdg" style="background:#fff7ed;color:#c2410c;border:1px solid #fdba74;font-size:10px;margin-left:4px" title="Nueva entrega tras devolución a corrección">↩ Reentrega'+(n>1?' v'+n:'')+'</span>';
}
function taskEsRevisada(t){return !!getTaskRevisionDepto(t);}
function taskRevisionDeptoLabel(rev){
  if(!rev)return'';
  return rev.tipo==='aprobada'?'<span class="bdg" style="background:var(--gnl);color:var(--gn);font-size:10px;margin-left:4px" title="Revisada — aprobada">✓ Aprobada</span>':'<span class="bdg" style="background:var(--orl);color:var(--or);font-size:10px;margin-left:4px" title="Revisada — enviada a corregir">↩ A corregir</span>';
}
/** Si el Director devolvió y la tarea quedó Atendida/Aprobada, reabrir a Por verificar (una sola vez). */
function pqrsHealTaskTrasDevolucionDirector(e,t){
  if(!e||!t||typeof pqrsEnRevisionNca!=='function'||!pqrsEnRevisionNca(e))return false;
  const wf=typeof getPqrsWorkflow==='function'?getPqrsWorkflow(e):{};
  if(!(wf.devolucion_director&&wf.devolucion_director.motivo))return false;
  normalizeTask(t);
  migrateLegacyAsignados(t);
  const est=estadoTask(t);
  const stillOk=est==='Por verificar'&&!t.fechaAtendida&&!t.ultimaRevisionDepto
    &&(t.asignados||[]).every(function(a){return!a||(a.estado==='por_verificar'&&!a.fechaAtendida);});
  if(stillOk)return false;
  t._pqrs_proyeccion_atendida=false;
  t.fechaAtendida='';
  t.verificadoPor='';
  t.ultimaRevisionDepto=null;
  const fr=t.fechaReportada||hoy();
  t.fechaReportada=fr;
  (t.asignados||[]).forEach(function(a){
    if(!a)return;
    a.fechaAtendida='';
    a.fechaReportada=a.fechaReportada||fr;
    a.estado='por_verificar';
  });
  if(typeof syncTaskAggregateState==='function')syncTaskAggregateState(t);
  t.estado='Por verificar';
  t.fechaAtendida='';
  t.fechaReportada=fr;
  return true;
}
/** Botón 🖨 con ✓ cuando ya está marcado impreso (mismo patrón que agenda 📅). */
function actImpresoCheckBtnHtml(impresoObj,onclickJs,opts){
  opts=opts||{};
  const imp=!!(impresoObj&&impresoObj.en);
  const cuando=imp?String(impresoObj.en||'').slice(0,10):'';
  const tip=imp
    ?('Impreso'+(cuando&&typeof fmtF==='function'?' '+fmtF(cuando):(cuando?' '+cuando:''))+(impresoObj.por?' · '+impresoObj.por:''))
    :(opts.tipPend||'Marcar como impreso');
  if(imp){
    return '<button type="button" class="btn bsm act-ico act-impreso-btn act-impreso-on" title="'+escAttr(tip)+'" onclick="event.stopPropagation();'+onclickJs+'"><span class="act-agenda-check" aria-hidden="true">✓</span>🖨</button>';
  }
  return '<button type="button" class="btn bsm act-ico act-impreso-btn" style="background:#1a7a4a;color:#fff" title="'+escAttr(tip)+'" onclick="event.stopPropagation();'+onclickJs+'">🖨</button>';
}
function pqrsMarcarImpreso(expId){
  if(typeof guardMantenimientoSoloConsulta==='function'&&guardMantenimientoSoloConsulta())return;
  const e=exps.find(x=>String(x._exp||'').trim()===String(expId||'').trim());
  if(!e||!(typeof pqrsPuedeMarcarParaFirma==='function'&&pqrsPuedeMarcarParaFirma(e))){
    notif('No puede marcar impreso','err');return;
  }
  const wf=typeof getPqrsWorkflow==='function'?getPqrsWorkflow(e):{};
  if(wf.impreso&&wf.impreso.en){notif('Ya estaba marcado como impreso','ok');return;}
  setPqrsWorkflow(e,{impreso:{por:responsableActivo||rolSesion||'',en:new Date().toISOString()}});
  if(!Array.isArray(e._pqrs_historial))e._pqrs_historial=[];
  e._pqrs_historial.push({tipo:'impreso_oficio',fecha:hoy(),nota:'Marcado como impreso',oficina:e._pqrs_oficina||'guaviare',por:responsableActivo||''});
  try{persistExpedienteGranular(e);}catch(err){console.warn('pqrsMarcarImpreso:',err);}
  if(typeof renderActividades==='function')renderActividades();
  if(typeof renderPqrsOficinaInbox==='function')renderPqrsOficinaInbox();
  notif('✓ Marcado como impreso','ok');
}
window.pqrsMarcarImpreso=pqrsMarcarImpreso;
window.actImpresoCheckBtnHtml=actImpresoCheckBtnHtml;

function renderActRowToolbarHtml(t,expAct){
  const eid=jsStr(t.exp),tid=jsStr(t.id);
  const est=estadoTask(t);
  const yo=esModoResponsable()?taskUsuarioEsAsignado(t,responsableActivo):(esVistaActividadesDepto()&&esTareaDelEncargado(t));
  const sol=getTaskSolicitudPendiente(t);
  const esPqrs=expAct&&typeof esPqrsSecretaria==='function'&&esPqrsSecretaria(expAct);
  const esRespAsignado=esModoResponsable()&&responsableActivo&&taskUsuarioEsAsignado(t,responsableActivo);
  const miEst=esRespAsignado
    ?(taskEsMultiAsignada(t)&&t.entregaModo==='individual'?estadoTaskForAsignado(t,responsableActivo):est)
    :est;
  const enPorRevisarResp=esRespAsignado&&(
    (typeof actividadCuentaComoPorRevisar==='function'&&actividadCuentaComoPorRevisar(t))
    ||miEst==='Por verificar'
    ||est==='Por verificar'
    ||(typeof taskPuedeCorregirSinRevision==='function'&&taskPuedeCorregirSinRevision(t,responsableActivo))
  );
  const esPqrsAtender=expAct&&typeof taskEsAtenderPqrs==='function'&&taskEsAtenderPqrs(t,expAct);
  const esPqrsRev=esPqrsAtender&&typeof pqrsEnRevisionNca==='function'&&pqrsEnRevisionNca(expAct);
  // Responsable en «Por revisar»: 🔍 ver entrega, 🗑 eliminar entrega (vuelve a Por ejecutar), chat/notas
  if(enPorRevisarResp){
    let actsR='<span class="sst-act-toolbar">';
    actsR+='<button type="button" class="btn bsm bic act-ico" title="'+(esPqrsRev?'Ver entrega y solicitud PQRSD':'Ver entrega enviada')+'" onclick="event.stopPropagation();openTaskCommentsModal(\''+eid+'\',\''+tid+'\')">🔍</button>';
    if(typeof puedeEliminarEntregaActividad==='function'&&puedeEliminarEntregaActividad(t.exp,t.id)){
      actsR+='<button type="button" class="btn bsm bic act-ico" title="Eliminar entrega: vuelve a Por ejecutar y borra documentos de Drive" onclick="event.stopPropagation();eliminarEntregaActividadConfirm(\''+escAttr(t.exp)+'\',\''+escAttr(t.id)+'\')">🗑️</button>';
    }
    actsR+=taskChatBtnHtml(t.exp,t.id,t);
    actsR+=taskNotasInternasBtnHtml(t.exp,t.id);
    actsR+='</span>';
    return actsR;
  }
  let acts='<span class="sst-act-toolbar">';
  // ✏️ encargados (incl. PQRSD); nunca responsables
  if(puedeGestionarActividadesDepto()){
    if(t.sinExpediente)
      acts+='<button type="button" class="btn bsm bic act-ico" title="Editar actividad" onclick="event.stopPropagation();abrirPanelActLibre(\''+eid+'\',\''+tid+'\')">✏️</button>';
    else
      acts+='<button type="button" class="btn bsm bic act-ico" title="Editar expediente" data-sst-action="editarExpDesdeAct" data-sst-exp="'+escAttr(t.exp)+'" data-sst-task="'+escAttr(t.id)+'">✏️</button>';
  }
  // 🧐 Revisar: solo tras entrega (por verificar / revisión), no en «por ejecutar»
  const pendienteRev=taskPendienteVerificacion(t)
    ||(expAct&&typeof pqrsEnRevisionNca==='function'&&pqrsEnRevisionNca(expAct))
    ||est==='Por verificar';
  const canRevisarDept=esVistaActividadesDepto()&&!esModoResponsable()&&pendienteRev
    &&!(expAct&&typeof pqrsEnFlujoFirmaNotif==='function'&&pqrsEnFlujoFirmaNotif(expAct));
  if(pendienteRev&&(canRevisarDept||puedeGestionarActividadesDepto()||(esPqrs&&(esNcaDeguv()||esOficinaPqrsNca()||esAdministrador())))){
    acts+='<button type="button" class="btn bsm bic act-ico" title="'+(esPqrsRev?'Revisar respuesta enviada':'Revisar entrega')+'" onclick="event.stopPropagation();openTaskCommentsModal(\''+eid+'\',\''+tid+'\')">🧐</button>';
  }
  const showChat=(!esModoResponsable())||(esModoResponsable()&&taskUsuarioEsAsignado(t,responsableActivo));
  if(showChat){
    acts+=taskChatBtnHtml(t.exp,t.id,t);
    acts+=taskNotasInternasBtnHtml(t.exp,t.id);
  }
  acts+='</span>';
  if(puedeGestionarSolicitudActividad(t.exp,t.id)&&sol)
    acts+='<button type="button" class="btn bsm" style="background:var(--orl);color:var(--or);font-weight:600" title="Atender solicitud" onclick="event.stopPropagation();openGestionSolicitudModal(\''+eid+'\',\''+tid+'\')">'+(sol.tipo==='traslado'?'↔':'🗑')+'</button>';
  acts+=taskReporteBtnHtml(t.exp,t.id,yo);
  if(esModoResponsable()&&taskUsuarioEsAsignado(t,responsableActivo)){
    acts+=taskCoEjecutorBtnHtml(t.exp,t.id);
    if(sol)acts+='<span class="solicitud-pill" title="Solicitud enviada">📩</span>';
  }
  if(yo&&est!=='Atendida')acts+=taskAgendaBtnHtml(t.exp,t.id);
  // Firma / notificar solo si NO hay solicitud de traslado o eliminación pendiente
  if(!sol&&typeof taskEnFlujoFirmaTramite==='function'&&taskEnFlujoFirmaTramite(t)){
    const eidT=eid,tidT=tid;
    const wfT=typeof getTaskFirmaWf==='function'?getTaskFirmaWf(t):{};
    if(typeof taskFirmaEnParaFirma==='function'&&taskFirmaEnParaFirma(t)&&typeof pqrsPuedeFlujoPorImprimir==='function'&&pqrsPuedeFlujoPorImprimir()){
      acts+=actImpresoCheckBtnHtml(wfT.impreso,"tramiteMarcarImpreso('"+eidT+"','"+tidT+"')");
      acts+='<button type="button" class="btn bsm act-ico" style="background:#0d5c2e;color:#fff" onclick="event.stopPropagation();tramitePasarAPorFirmar(\''+eidT+'\',\''+tidT+'\')" title="Pasar a firma del Director">🖊</button>';
    }
    if(typeof taskFirmaEnPorFirmar==='function'&&taskFirmaEnPorFirmar(t)){
      if(typeof taskFirmaEsFirmadoPendiente==='function'&&taskFirmaEsFirmadoPendiente(t))
        acts+='<button type="button" class="btn bsm act-ico bp" onclick="event.stopPropagation();tramitePasarAPorNotificar(\''+eidT+'\',\''+tidT+'\')" title="Por notificar">📬</button>';
      else
        acts+='<button type="button" class="btn bsm act-ico" style="background:#0d5c2e;color:#fff" onclick="event.stopPropagation();tramiteMarcarFirmadoFisico(\''+eidT+'\',\''+tidT+'\')" title="Firmar">🖊</button>';
    }
    if(typeof taskFirmaEnPorNotificar==='function'&&taskFirmaEnPorNotificar(t)){
      if(typeof tramitePuedeNotificar==='function'&&tramitePuedeNotificar(t))
        acts+='<button type="button" class="btn bsm act-ico bp" onclick="event.stopPropagation();openTramiteNotificarModal(\''+eidT+'\',\''+tidT+'\')" title="Notificar">📬</button>';
      else{
        const quienT=String(wfT.notificar_por||'').trim();
        acts+='<span class="bdg" style="background:#185fa522;color:var(--bl);font-size:10px">📬 '+(quienT?escAttr(quienT):'')+'</span>';
      }
    }
    if(typeof taskFirmaEnRevisionFinalNotif==='function'&&taskFirmaEnRevisionFinalNotif(t)
      &&(typeof tramitePuedeNotificar==='function'?tramitePuedeNotificar(t):(esNcaDeguv()||esAdministrador()||esVistaActividadesDepto())))
      acts+='<button type="button" class="btn bsm act-ico" style="background:#6d3fa8;color:#fff" onclick="event.stopPropagation();tramiteAprobarRevisionFinalNotif(\''+eidT+'\',\''+tidT+'\')" title="Aprobar notificación">✅</button>';
  }
  if(!sol&&esPqrs&&typeof pqrsWorkflowFase==='function'){
    const peid=jsStr(expAct._exp||t.exp);
    const faseWf=pqrsWorkflowFase(expAct);
    const wfRow=typeof getPqrsWorkflow==='function'?getPqrsWorkflow(expAct):{};
    if(typeof pqrsEnParaFirma==='function'&&pqrsEnParaFirma(expAct)&&typeof pqrsPuedeMarcarParaFirma==='function'&&pqrsPuedeMarcarParaFirma(expAct)){
      acts+=_pqrsActDocsIconBtnsHtml(wfRow,{expId:expAct._exp||t.exp});
      acts+=actImpresoCheckBtnHtml(wfRow.impreso,"pqrsMarcarImpreso('"+peid+"')");
      acts+='<button type="button" class="btn bsm act-ico" style="background:#0d5c2e;color:#fff" onclick="event.stopPropagation();openPqrsParaFirmaModal(\''+peid+'\')" title="Pasar a firma">🖊</button>';
    }
    if(faseWf===PQRS_WF.POR_FIRMAR){
      const firmFis=!!(wfRow.firma_fisica&&wfRow.firma_fisica.en);
      const esDir=typeof esDirectorDsDeguv==='function'&&esDirectorDsDeguv();
      acts+=_pqrsActDocsIconBtnsHtml(wfRow,{expId:expAct._exp||t.exp});
      if(firmFis){
        if(esDir)acts+='<span class="bdg" style="background:#dcfce7;color:#15803d;font-size:10px">✓</span>';
        else if(typeof pqrsPuedeAsignarPorNotificar==='function'&&pqrsPuedeAsignarPorNotificar(expAct))
          acts+='<button type="button" class="btn bsm act-ico bp" onclick="event.stopPropagation();openPqrsDirectorFirmarModal(\''+peid+'\')" title="Gestionar firmado">📬</button>';
        else acts+='<span class="bdg" style="background:#dcfce7;color:#15803d;font-size:10px">✓</span>';
      }else if(esDir)
        acts+='<button type="button" class="btn bsm act-ico" style="background:#0d5c2e;color:#fff" onclick="event.stopPropagation();openPqrsDirectorFirmarModal(\''+peid+'\')" title="Firmar">🖊</button>';
      else if(typeof pqrsPuedeMarcarFirmadoSinCargar==='function'&&pqrsPuedeMarcarFirmadoSinCargar(expAct))
        acts+='<button type="button" class="btn bsm act-ico" style="background:#15803d;color:#fff" onclick="event.stopPropagation();openPqrsDirectorFirmarModal(\''+peid+'\')" title="Ya firmado">✓</button>';
      else acts+='<span class="bdg" style="background:#0d5c2e22;color:#0d5c2e;font-size:10px">🖊</span>';
    }
    if(faseWf===PQRS_WF.PENDIENTE_NOTIF||faseWf===PQRS_WF.LISTA_ENVIO){
      acts+=_pqrsActDocsIconBtnsHtml(wfRow,{expId:expAct._exp||t.exp});
      if(typeof esDirectorDsDeguv==='function'&&esDirectorDsDeguv())
        acts+='<span class="btn bsm act-ico" style="background:#185fa522;color:var(--bl);cursor:default;pointer-events:none" title="Por notificar">📬</span>';
      else if(typeof pqrsPuedeNotificarOficio==='function'&&pqrsPuedeNotificarOficio(expAct))
        acts+='<button type="button" class="btn bsm act-ico bp" onclick="event.stopPropagation();openPqrsNotificarOficioModal(\''+peid+'\')" title="Notificar">📬</button>';
      else{
        const quien=String(wfRow.notificar_por||'').trim();
        acts+='<span class="bdg" style="background:#185fa522;color:var(--bl);font-size:10px">📬'+(quien?' '+escAttr(quien):'')+'</span>';
      }
    }
    if(faseWf===PQRS_WF.REVISION_FINAL&&(esNcaDeguv()||esOficinaPqrsNca()||esAdministrador()))
      acts+='<button type="button" class="btn bsm act-ico" style="background:#6d3fa8;color:#fff" onclick="event.stopPropagation();ncaAprobarRevisionFinalNotif(\''+peid+'\')" title="Aprobar notificación">✅</button>';
    if((faseWf===PQRS_WF.SIN_RESPUESTA||faseWf===PQRS_WF.RECHAZADA)&&typeof puedeMarcarPqrsRespondida==='function'&&puedeMarcarPqrsRespondida(expAct)){
      if(typeof pqrsPuedeAtajoParaFirma==='function'&&pqrsPuedeAtajoParaFirma())
        acts+='<button type="button" class="btn bsm act-ico" style="background:#0d5c2e;color:#fff;border-color:#0d5c2e" onclick="event.stopPropagation();openPqrsRespuestaModal(\''+peid+'\',{modo:\'firma\'})" title="Enviar a firma">🖊</button>';
    }
  }
  return acts;
}

function actRefCellHtml(t){
  const expId=String(t.exp||'').trim();
  const taskId=String(t.id||'').trim();
  const tit=t.sinExpediente?'Ver actividad':(t.esPqrs?'Ver PQRSD en consulta':'Ver expediente en consulta');
  const refTxt=t.sinExpediente?String(t.codigo||t.exp||'').trim():String(t.exp||'').trim();
  const inner='<span class="act-ref-link">'+escAttr(refTxt)+'</span>';
  return '<button type="button" class="act-ref-btn" data-sst-action="abrirConsultaRefDesdeActividad" data-sst-exp="'+escAttr(expId)+'" data-sst-task="'+escAttr(taskId)+'" title="'+escAttr(tit)+'">'+inner+'</button>';
}

function renderActividadesRowHtml(t){
  const expActPre=typeof getExpById==='function'?getExpById(t.exp):null;
  if(expActPre&&typeof taskEsAtenderPqrs==='function'&&taskEsAtenderPqrs(t,expActPre)){
    const realT=(expActPre.tasks||[]).find(function(x){return x&&String(x.id)===String(t.id);});
    if(realT&&pqrsHealTaskTrasDevolucionDirector(expActPre,realT)){
      Object.assign(t,realT,{exp:t.exp,depto:t.depto,nombre:t.nombre,tram:t.tram,sinExpediente:t.sinExpediente,esPqrs:t.esPqrs,prioritaria:t.prioritaria});
      if(!window._pqrsHealDevDirPersist)window._pqrsHealDevDirPersist=new Set();
      const hk=String(expActPre._exp||'')+'|'+String(realT.id||'');
      if(!window._pqrsHealDevDirPersist.has(hk)){
        window._pqrsHealDevDirPersist.add(hk);
        try{persistExpedienteGranular(expActPre);}catch(err){console.warn('heal devolucion director:',err);}
      }
    }
  }
  const est=estadoTask(t),lbl=estadoTaskLabel(t),st=taskEstadoStyle(est,t),vencE=taskActividadVencida(t);
  const badgeHtml=typeof taskEstadoBadgeHtml==='function'?taskEstadoBadgeHtml(t):('<span class="bdg" style="background:'+st.bg+';color:'+st.fg+'">'+escAttr(lbl)+'</span>');
  const venceShow=taskVenceEfectivo(t)||t.vence;
  const esEncOwn=esTareaDelEncargado(t);
  const revDepto=esVistaActividadesDepto()?getTaskRevisionDepto(t):null;
  const cierre=est==='Atendida'?fmtF(t.fechaAtendida):esEncOwn&&est!=='Atendida'?'—':est==='Por verificar'?('Reportada '+fmtF(t.fechaReportada)):est==='Por corregir'?'Devuelta — corregir':'—';
  const cierreHtml=cierre;
  const refLbl=actRefCellHtml(t);
  const priorBadge=taskPrioridadBadgeHtml(t);
  const bibBadge=typeof bibTaskReposBadgeHtml==='function'?bibTaskReposBadgeHtml(t):'';
  const altaBadge=(expActPre&&typeof expAltaResponsableBadgeHtml==='function')?expAltaResponsableBadgeHtml(expActPre):'';
  const sol=getTaskSolicitudPendiente(t);
  const solBadge=sol?('<span class="solicitud-pill" title="'+(sol.tipo==='traslado'?'Traslado':'Eliminación')+' solicitada por '+escAttr(sol.por)+'">⚠ Solicitud</span>'):'';
  const expAct=getExpById(t.exp);
  const acts=renderActRowToolbarHtml(t,expAct);
  const respCol=esVistaActividadesDepto()?('<td style="font-size:12px;color:var(--tx2)">'+taskResponsablesLabel(t,true)+'</td>'):'';
  const esCrit=taskEsPrioridadCriticaVencimiento(t);
  const rowStyle=[
    esCrit?'background:linear-gradient(90deg,rgba(234,88,12,.08),transparent)':(t.prioritaria?'background:linear-gradient(90deg,rgba(163,45,45,.05),transparent)':''),
    taskEsReentregaTrasCorreccion(t)?'background:linear-gradient(90deg,rgba(194,65,12,.08),transparent);box-shadow:inset 3px 0 0 #ea580c':''
  ].filter(Boolean).join(';');
  const rowCls=esCrit?'prioritaria-crit':(t.prioritaria?'prioritaria':'');
  return '<tr'+(rowCls?' class="'+rowCls+'"':'')+(rowStyle?' style="'+rowStyle+'"':'')+'><td>'+badgeHtml+priorBadge+bibBadge+altaBadge+solBadge+taskReentregaBadgeHtml(t)+(revDepto?taskRevisionDeptoLabel(revDepto):'')+'</td>'+
    '<td style="font-family:\'DM Mono\',monospace;font-size:12px;color:var(--bl)">'+refLbl+'</td>'+
    '<td class="act-col-tram">'+escAttr(t.tram)+badgeDepto(t.depto)+'</td>'+
    '<td>'+actInteresadoCellHtml(t)+'</td><td>'+escAttr(t.desc||t.actividad)+'</td>'+
    respCol+
    '<td style="color:'+(vencE?'var(--rd)':'var(--tx)')+'">'+fmtF(venceShow)+'</td>'+
    '<td style="font-size:12px">'+cierreHtml+'</td>'+
    '<td><div class="fx" style="gap:4px">'+acts+'</div></td></tr>';
}
function updateActEstFilterForEnc(forEnc){
  const sel=document.getElementById('f-act-est');if(!sel)return;
  let cv=sel.value;
  if(cv==='parafirma'||cv==='porimprimir'||cv==='porfirmar'||cv==='firmados')cv='porfirma';
  const deptView=esVistaActividadesDepto();
  const isVital=typeof esCargoVital==='function'&&esCargoVital();
  const isResp=!deptView&&esModoResponsable();
  const isDir=typeof esDirectorDsDeguv==='function'&&esDirectorDsDeguv();
  const puedeImprimir=typeof pqrsPuedeFlujoPorImprimir==='function'&&pqrsPuedeFlujoPorImprimir();
  const puedeFirmarBan=typeof pqrsPuedeFlujoPorFirmarBandeja==='function'&&pqrsPuedeFlujoPorFirmarBandeja();
  const puedeFirmados=typeof pqrsPuedeVerPaletaFirmados==='function'?pqrsPuedeVerPaletaFirmados():isDir;
  const puedePorFirma=puedeImprimir||puedeFirmarBan||puedeFirmados;
  const optCorr=sel.querySelector('option[value="porcorr"]');
  const optVer=sel.querySelector('option[value="porver"]');
  const optRev=sel.querySelector('option[value="revisados"]');
  const optPorFirma=sel.querySelector('option[value="porfirma"]');
  const optNotif=sel.querySelector('option[value="pornotif"]');
  const optVenc=sel.querySelector('option[value="venc"]');
  if(optCorr)optCorr.hidden=deptView;
  if(optVer){optVer.hidden=false;optVer.textContent='Por revisar';}
  if(optRev)optRev.hidden=true;
  if(optPorFirma){
    optPorFirma.hidden=!puedePorFirma;
    optPorFirma.textContent='Por firma';
  }
  if(optNotif)optNotif.hidden=!(!isDir&&(puedeFirmarBan||isResp));
  if(optVenc){optVenc.hidden=false;optVenc.textContent='Vencidas';}
  // Director sigue el seguimiento en «Por firma», no actúa en Por notificar
  if(isDir&&optNotif)optNotif.hidden=true;
  const order=deptView
    ?['pend','prior','venc','porver','porfirma','pornotif','done','all']
    :(isVital
      ?['pend','prior','venc','porver','porcorr','porfirma','pornotif','done','all']
      :(isDir
        ?['pend','prior','venc','porfirma','pornotif','done','all']
        :['pend','prior','venc','porver','porcorr','pornotif','done','all']));
  if(puedePorFirma&&order.indexOf('porfirma')<0)
    order.splice(order.length-2,0,'porfirma');
  order.forEach(function(v){
    const o=sel.querySelector('option[value="'+v+'"]');
    if(o)sel.appendChild(o);
  });
  if(forEnc&&cv==='porcorr')sel.value='pend';
  else if(sel.querySelector('option[value="'+cv+'"]')&&!sel.querySelector('option[value="'+cv+'"]').hidden)sel.value=cv;
  else if(cv==='porfirma'&&optPorFirma&&optPorFirma.hidden)sel.value='pend';
}
function exportarActividadesExcel(){
  const list=window._actExportList||[];
  if(!list.length){notif('Sin actividades para exportar en este filtro','err');return;}
  const deptView=esVistaActividadesDepto();
  const hdr=['Estado','Ref.','Trámite','Interesado','Actividad'];
  if(deptView)hdr.push('Responsable');
  if(deptView)hdr.push('Resultado revisión');
  hdr.push('Vence','Cierre / reporte');
  const rows=list.map(t=>{
    const rev=deptView?getTaskRevisionDepto(t):null;
    const r=[estadoTaskLabel(t),t.exp||t.codigo||'',t.tram||'',t.nombre||'',t.desc||t.actividad||''];
    if(deptView)r.push(taskResponsablesLabel(t,false));
    if(deptView)r.push(rev?(rev.tipo==='aprobada'?'Aprobada':'Enviada a corregir'):'');
    r.push(fmtF(t.vence),estadoTask(t)==='Atendida'?fmtF(t.fechaAtendida):t.fechaReportada?fmtF(t.fechaReportada):'');
    return r;
  });
  exportarTablaExcel([{title:'Actividades',hdr,rows}],'actividades-'+labelDepto(deptoActivo).replace(/\W+/g,'-')+'-'+hoy());
}
function escCellExcel(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function pqrsMatrizEstadoFinal(e){
  if(!pqrsEstaCerrada(e))return '';
  if(e._pqrs_informativa)return 'CONFORME';
  if(pqrsRespuestaEnTermino(e)===false)return 'NO CONFORME';
  return 'CONFORME';
}
function pqrsMatrizCanalLabel(canal){
  const m={
    correo:'NOTIFICACIÓN POR CORREO ELECTRÓNICO',
    whatsapp:'NOTIFICACIÓN POR WHATSAPP',
    presencial:'NOTIFICACIÓN PERSONAL',
    fisica:'NOTIFICACIÓN POR CORREO FÍSICO',
    pagina:'NOTIFICACIÓN POR PÁGINA WEB',
    aviso:'NOTIFICACIÓN POR AVISO'
  };
  return m[canal]||'';
}
function pqrsMatrizObservaciones(e){
  if(!pqrsEstaCerrada(e))return '';
  const wf=getPqrsWorkflow(e);
  const canal=wf.canal||e._pqrs_respuesta_medio||'';
  const parts=[];
  if(e._pqrs_informativa)parts.push('PQRSD informativa');
  const canalLbl=pqrsMatrizCanalLabel(canal);
  if(canalLbl)parts.push(canalLbl);
  const mn=String(e._medio_notificacion||'').trim();
  if(mn&&mn!=='no_indica'){
    const ml=medioNotificacionLabel(mn);
    if(ml&&!parts.some(p=>p.toLowerCase().includes(String(ml).toLowerCase())))parts.push('Medio notificación: '+ml);
  }
  return parts.join(' · ');
}
function pqrsMatrizOficinaResponsable(e){
  const ofi=e._pqrs_oficina||'';
  if(!ofi||ofi==='secretaria')return labelOficina('secretaria')||'Secretaría DEGUV';
  return labelOficina(ofi)||ofi;
}
function pqrsMatrizDepartamento(e){
  return String(labelDepto(e._depto||'guaviare')||'Guaviare').toUpperCase();
}
function pqrsMatrizDiasRespuesta(e){
  if(!pqrsEstaCerrada(e))return '';
  const wf=getPqrsWorkflow(e);
  const resp=wf.fecha_respuesta||e._pqrs_respuesta_fecha||'';
  if(!resp)return '';
  const inicio=e._fecha||e._fecha_solicitud||'';
  if(!inicio)return '';
  return String(Math.max(0,diasEntre(inicio,resp)));
}
function pqrsMatrizDiasParaVencer(e){
  const p=getPqrsPlazoInfo(e);
  if(!p.vence)return '';
  if(pqrsEstaCerrada(e)){
    const wf=getPqrsWorkflow(e);
    const resp=wf.fecha_respuesta||e._pqrs_respuesta_fecha||'';
    if(resp)return String(diasEntre(resp,p.vence));
  }
  return String(diffDias(p.vence));
}
function buildPqrsMatrizRow(e,item){
  const rec=typeof buildPqrsMatrizRecord==='function'?buildPqrsMatrizRecord(e,item):null;
  if(rec)return[
    rec.item,fmtF(rec.fechaRecibo),rec.radicadoRecibo,rec.departamento,rec.tipo,rec.nombre,rec.asunto,
    rec.plazoDias,rec.responsable,fmtF(rec.fechaVence),rec.estado,
    rec.diasParaVencer===''?'':rec.diasParaVencer,
    rec.fechaContestacion?fmtF(rec.fechaContestacion):'',
    rec.radicadoContestacion,
    rec.diasRespuesta===''?'':rec.diasRespuesta,
    rec.estadoFinal,rec.observaciones
  ];
  e=normalizePqrsOficinaFields(e);
  const wf=getPqrsWorkflow(e);
  const p=getPqrsPlazoInfo(e);
  const plazo=p.plazo||getPqrsPlazoDias(e);
  const vence=p.vence||'';
  const cerrada=pqrsEstaCerrada(e);
  const resp=cerrada?(wf.fecha_respuesta||e._pqrs_respuesta_fecha||''):'';
  const oficio=cerrada?(wf.oficio||e._pqrs_respuesta_oficio||''):'';
  return[
    item,fmtF(e._fecha_solicitud||e._fecha||''),e._exp||'',pqrsMatrizDepartamento(e),e._tipo_solicitud||'',
    String(e._qd_nombre||e._pn_nombre||e._nombre||'').trim(),String(e.f_f1||e._pqrs_detalle||'').trim(),
    plazo,pqrsMatrizOficinaResponsable(e),fmtF(vence),getPqrsEstadoDisplay(e),pqrsMatrizDiasParaVencer(e),
    resp?fmtF(resp):'',oficio,pqrsMatrizDiasRespuesta(e),pqrsMatrizEstadoFinal(e),pqrsMatrizObservaciones(e)
  ];
}
function buildPqrsMatrizSeguimiento(list){
  let oportunas=0,fuera=0,sinResolver=0,sumDias=0,cntDias=0;
  list.forEach(e=>{
    if(!pqrsEstaCerrada(e)){sinResolver++;return;}
    const d=pqrsMatrizDiasRespuesta(e);
    if(d!==''){sumDias+=Number(d);cntDias++;}
    if(e._pqrs_informativa||pqrsRespuestaEnTermino(e)!==false)oportunas++;
    else fuera++;
  });
  const prom=cntDias?String(Math.round(sumDias/cntDias*10)/10):'';
  return{
    hdr:['TOTAL PQRSD RECIBIDAS','RESUELTAS OPORTUNAMENTE','RESUELTAS FUERA DE TÉRMINO','SIN RESOLVER','PROMEDIO DÍAS DE RESPUESTA'],
    rows:[[list.length,oportunas,fuera,sinResolver,prom]]
  };
}
function ordenarListaMatrizPqrs(list){
  return(list||[]).filter(e=>esPqrsSecretaria(e)).slice().sort((a,b)=>{
    const fa=String(a._fecha_solicitud||a._fecha||'');
    const fb=String(b._fecha_solicitud||b._fecha||'');
    return fa.localeCompare(fb)||String(a._exp||'').localeCompare(String(b._exp||''));
  });
}
async function exportarMatrizPqrsExcel(list,suffix,periodKey){
  list=ordenarListaMatrizPqrs(list);
  if(!list.length){notif('Sin PQRSD para exportar en el filtro actual','err');return;}
  const pk=periodKey||(suffix==='consolidado'?'cons':'q');
  const periodLbl=typeof labelPeriodo==='function'?labelPeriodo(pk):'';
  if(typeof exportarMatrizPqrsDesdePlantilla==='function'){
    try{
      const ok=await exportarMatrizPqrsDesdePlantilla(list,suffix,periodLbl);
      if(ok){
        if(typeof logAudit==='function')logAudit('Exportó matriz oficial PQRSD (plantilla)','pqrsd',null,list.length+' solicitud(es)');
        return;
      }
    }catch(err){
      console.warn('exportarMatrizPqrsDesdePlantilla:',err);
      notif('Plantilla no disponible — generando Excel simplificado ('+String(err.message||err).slice(0,60)+')','warn');
    }
  }
  const hdr=[
    'ITEM','FECHA RECIBO','RADICADO RECIBO','DEPARTAMENTO','TIPO PETICIÓN','NOMBRE DEL PETICIONARIO','ASUNTO',
    'TIEMPO DE RESPUESTA (días)','RESPONSABLE DEPENDENCIA','FECHA VENCIMIENTO','ESTADO','DÍAS PARA VENCIMIENTO',
    'FECHA CONTESTACIÓN','RADICADO CONTESTACIÓN','DÍAS DE RESPUESTA','ESTADO FINAL','OBSERVACIONES'
  ];
  const rows=list.map((e,i)=>buildPqrsMatrizRow(e,i+1));
  const seg=buildPqrsMatrizSeguimiento(list);
  exportarTablaExcel([
    {
      title:'CONSOLIDADO PQRSD',
      preamble:[
        'FORMATO: CONTROL PETICIONES, QUEJAS, RECLAMOS, SUGERENCIAS Y DENUNCIAS — PQRSD',
        'UNIDAD DE GESTIÓN: SECRETARÍA GENERAL — CDA DEGUV',
        'CÓDIGO: AGJ-CP-9-PR-02-FR-02 · VERSIÓN: 5',
        'FECHA CORTE: '+fmtF(hoy())+(periodLbl?' · Período filtro: '+periodLbl:'')
      ],
      hdr,rows
    },
    {title:'SEGUIMIENTO',hdr:seg.hdr,rows:seg.rows}
  ],'matriz-pqrs-'+(suffix||'reporte')+'-'+hoy());
  if(typeof logAudit==='function')logAudit('Exportó matriz oficial PQRSD','pqrsd',null,list.length+' solicitud(es)');
}
